@charset "UTF-8";
/* =====================================
   Bulbulustur Theme — Legacy Compatibility Bundle
===================================== */
/* =====================================
   Bundle Layer — Core Foundation
   Tokens, base, utilities and shared layout.
===================================== */
/* 1. Foundation / Tokens */
/* =====================================
   Bulbulustur Theme — Theme Profile
   Bootstrap-parallel token names
   Source: bb-* tokens
   Theme attribute: html[data-bs-theme="light|dark"]
   Surface attribute: html[data-bb-surface="b2b|b2c|fair|event|trust|tech|highlight"]
===================================== */
/* -------------------------------------
   LIGHT / DEFAULT
------------------------------------- */
:root,
html[data-bs-theme=light] {
  color-scheme: light;
  /* -------------------------------------
     Base
  ------------------------------------- */
  --bb-white: #ffffff;
  --bb-black: #000000;
  /* -------------------------------------
     Brand Core
     Bulbulustur primary identity.
  ------------------------------------- */
  --bb-yellow-50: #fffbea;
  --bb-yellow-100: #fff4bf;
  --bb-yellow-200: #ffe985;
  --bb-yellow-300: #ffe45c;
  --bb-yellow-400: #fede2e;
  --bb-yellow-500: #fed700;
  --bb-yellow-600: #e6c300;
  --bb-yellow-700: #b89400;
  --bb-yellow-800: #816800;
  --bb-yellow-900: #584700;
  --bb-yellow-rgb: 254, 215, 0;
  --bb-brand-yellow: var(--bb-yellow-500);
  --bb-brand-yellow-rgb: var(--bb-yellow-rgb);
  --bb-brand-yellow-hover: var(--bb-yellow-600);
  --bb-brand-yellow-active: var(--bb-yellow-700);
  --bb-brand-yellow-soft: var(--bb-yellow-100);
  --bb-brand-yellow-inverse: #0f1a33;
  /* -------------------------------------
     Navy / Ecosystem Dark
     Header/footer dark identity.
  ------------------------------------- */
  --bb-navy-50: #edf4fb;
  --bb-navy-100: #d8e7f5;
  --bb-navy-200: #a4bad0;
  --bb-navy-300: #6f8cab;
  --bb-navy-400: #435f7d;
  --bb-navy-500: #17324f;
  --bb-navy-600: #132a44;
  --bb-navy-700: #0f2238;
  --bb-navy-800: #0c1c2f;
  --bb-navy-900: #081626;
  --bb-navy-rgb: 8, 22, 38;
  --bb-brand-navy: var(--bb-navy-900);
  --bb-brand-navy-rgb: var(--bb-navy-rgb);
  --bb-brand-navy-soft: var(--bb-navy-700);
  --bb-brand-navy-inverse: var(--bb-white);
  /* -------------------------------------
     Neutral / Gray Scale
  ------------------------------------- */
  --bb-gray-50: #fafbfc;
  --bb-gray-100: #f4f6f8;
  --bb-gray-200: #e8edf3;
  --bb-gray-300: #d5dde8;
  --bb-gray-400: #b9c2d3;
  --bb-gray-500: #8a96a8;
  --bb-gray-600: #6b7894;
  --bb-gray-700: #445066;
  --bb-gray-800: #232d44;
  --bb-gray-900: #0f1a33;
  /* -------------------------------------
     Coal
  ------------------------------------- */
  --bb-coal-100: #161a22;
  --bb-coal-200: #13161e;
  --bb-coal-300: #0f1219;
  --bb-coal-400: #0c0f15;
  --bb-coal-500: #090b10;
  --bb-coal-600: #06080c;
  --bb-coal-black: #000000;
  --bb-coal-clarity-rgb: 15, 18, 25;
  --bb-coal-clarity-opacity: 0.55;
  --bb-coal-clarity: rgba(var(--bb-coal-clarity-rgb), var(--bb-coal-clarity-opacity));
  /* -------------------------------------
     Accent Palettes
     These do not replace primary.
  ------------------------------------- */
  --bb-blue-50: #eff6ff;
  --bb-blue-100: #dbeafe;
  --bb-blue-200: #b7d8fe;
  --bb-blue-300: #93c5fd;
  --bb-blue-400: #5c94f4;
  --bb-blue-500: #2563eb;
  --bb-blue-600: #2158e2;
  --bb-blue-700: #1d4ed8;
  --bb-blue-800: #143797;
  --bb-blue-900: #0e2568;
  --bb-blue-rgb: 37, 99, 235;
  --bb-turquoise-50: #ecfeff;
  --bb-turquoise-100: #cffafe;
  --bb-turquoise-200: #9bf1fc;
  --bb-turquoise-300: #67e8f9;
  --bb-turquoise-400: #36cfe6;
  --bb-turquoise-500: #06b6d4;
  --bb-turquoise-600: #0a95b2;
  --bb-turquoise-700: #0e7490;
  --bb-turquoise-800: #0a5165;
  --bb-turquoise-900: #073845;
  --bb-turquoise-rgb: 6, 182, 212;
  --bb-green-50: #f0fdf4;
  --bb-green-100: #dcfce7;
  --bb-green-200: #b1f6ca;
  --bb-green-300: #86efac;
  --bb-green-400: #54da85;
  --bb-green-500: #22c55e;
  --bb-green-600: #1ca24e;
  --bb-green-700: #15803d;
  --bb-green-800: #0f5a2b;
  --bb-green-900: #0a3d1d;
  --bb-green-rgb: 34, 197, 94;
  --bb-orange-50: #fff7ed;
  --bb-orange-100: #ffedd5;
  --bb-orange-200: #fed4a4;
  --bb-orange-300: #fdba74;
  --bb-orange-400: #fb9645;
  --bb-orange-500: #f97316;
  --bb-orange-600: #de5a11;
  --bb-orange-700: #c2410c;
  --bb-orange-800: #882e08;
  --bb-orange-900: #5d1f06;
  --bb-orange-rgb: 249, 115, 22;
  --bb-pink-50: #fdf2f8;
  --bb-pink-100: #fce7f3;
  --bb-pink-200: #fac8e4;
  --bb-pink-300: #f9a8d4;
  --bb-pink-400: #f278b6;
  --bb-pink-500: #ec4899;
  --bb-pink-600: #d5307b;
  --bb-pink-700: #be185d;
  --bb-pink-800: #851141;
  --bb-pink-900: #5b0c2d;
  --bb-pink-rgb: 236, 72, 153;
  --bb-purple-50: #f5f3ff;
  --bb-purple-100: #ede9fe;
  --bb-purple-200: #d8cffe;
  --bb-purple-300: #c4b5fd;
  --bb-purple-400: #a888fa;
  --bb-purple-500: #8b5cf6;
  --bb-purple-600: #7c42e8;
  --bb-purple-700: #6d28d9;
  --bb-purple-800: #4c1c98;
  --bb-purple-900: #341368;
  --bb-purple-rgb: 139, 92, 246;
  --bb-red-50: #fef2f2;
  --bb-red-100: #fee2e2;
  --bb-red-200: #fdc4c4;
  --bb-red-300: #fca5a5;
  --bb-red-400: #f67474;
  --bb-red-500: #ef4444;
  --bb-red-600: #d43030;
  --bb-red-700: #b91c1c;
  --bb-red-800: #821414;
  --bb-red-900: #590d0d;
  --bb-red-rgb: 239, 68, 68;
  /* -------------------------------------
     Body / Backgrounds
  ------------------------------------- */
  --bb-body-bg: var(--bb-white);
  --bb-body-color: var(--bb-gray-900);
  --bb-secondary-bg: var(--bb-gray-200);
  --bb-tertiary-bg: var(--bb-gray-100);
  --bb-surface-bg: var(--bb-white);
  --bb-surface-soft: var(--bb-gray-50);
  --bb-surface-muted: var(--bb-gray-100);
  --bb-surface-elevated: var(--bb-white);
  /* -------------------------------------
     Text
  ------------------------------------- */
  --bb-emphasis-color: var(--bb-body-color);
  --bb-secondary-color: var(--bb-gray-600);
  --bb-tertiary-color: var(--bb-gray-700);
  --bb-heading-color: var(--bb-emphasis-color);
  /* -------------------------------------
     RGB Helpers
  ------------------------------------- */
  --bb-body-bg-rgb: 255, 255, 255;
  --bb-body-color-rgb: 15, 26, 51;
  --bb-secondary-bg-rgb: 232, 237, 243;
  --bb-tertiary-bg-rgb: 244, 246, 248;
  --bb-secondary-color-rgb: 107, 120, 148;
  --bb-tertiary-color-rgb: 68, 80, 102;
  /* -------------------------------------
     Borders
  ------------------------------------- */
  --bb-border-color: var(--bb-gray-200);
  --bb-border-color-strong: var(--bb-gray-300);
  --bb-border-dashed-color: var(--bb-gray-300);
  --bb-border-width: 1px;
  /* -------------------------------------
     Shadows
  ------------------------------------- */
  --bb-shadow-rgb: 0, 0, 0;
  --bb-shadow-opacity-xs: 0.05;
  --bb-shadow-opacity-sm: 0.06;
  --bb-shadow-opacity-md: 0.08;
  --bb-shadow-opacity-lg: 0.10;
  --bb-shadow-opacity-inset: 0.08;
  --bb-shadow-xs: 0 0.10rem 0.65rem rgba(var(--bb-shadow-rgb), var(--bb-shadow-opacity-xs));
  --bb-shadow-sm: 0 0.25rem 1rem rgba(var(--bb-shadow-rgb), var(--bb-shadow-opacity-sm));
  --bb-shadow: 0 0.60rem 1.60rem rgba(var(--bb-shadow-rgb), var(--bb-shadow-opacity-md));
  --bb-shadow-lg: 0 1.20rem 2.80rem rgba(var(--bb-shadow-rgb), var(--bb-shadow-opacity-lg));
  --bb-shadow-inset: inset 0 1px 2px rgba(var(--bb-shadow-rgb), var(--bb-shadow-opacity-inset));
  /* -------------------------------------
     Layering
     Core stacking contracts shared by applications.
  ------------------------------------- */
  --bb-z-sticky: 1020;
  --bb-z-header: 1030; /* sticky içeriğin (1020) üstünde: header menüleri sayfa nesnelerinin altında kalmaz */
  --bb-z-dropdown: 1050;
  --bb-z-drawer: 1055;
  /* -------------------------------------
     Motion / Transition
  ------------------------------------- */
  --bb-motion-fast: 150ms;
  --bb-motion-normal: 200ms;
  --bb-motion-slow: 300ms;
  --bb-ease-in: ease-in;
  --bb-ease-out: ease-out;
  --bb-ease-in-out: ease-in-out;
  --bb-transition-fast: var(--bb-motion-fast) var(--bb-ease-in-out);
  --bb-transition-normal: var(--bb-motion-normal) var(--bb-ease-in-out);
  --bb-transition-slow: var(--bb-motion-slow) var(--bb-ease-in-out);
  --bb-transition-colors:
    color var(--bb-motion-fast) var(--bb-ease-in-out),
    background-color var(--bb-motion-fast) var(--bb-ease-in-out),
    border-color var(--bb-motion-fast) var(--bb-ease-in-out);
  /* -------------------------------------
     State
  ------------------------------------- */
  --bb-disabled-opacity: 0.55;
  --bb-loading-opacity: 0.65;
  /* -------------------------------------
     Semantic Brand Inputs
     Primary is always Bulbulustur yellow.
  ------------------------------------- */
  --bb-brand-primary: var(--bb-brand-yellow);
  --bb-brand-secondary: var(--bb-gray-200);
  --bb-brand-success: var(--bb-green-500);
  --bb-brand-info: var(--bb-blue-500);
  --bb-brand-warning: var(--bb-orange-500);
  --bb-brand-danger: var(--bb-red-600);
  --bb-brand-dark: var(--bb-brand-navy);
  --bb-brand-light: var(--bb-gray-100);
  --bb-brand-primary-rgb: var(--bb-brand-yellow-rgb);
  --bb-brand-secondary-rgb: 232, 237, 243;
  --bb-brand-success-rgb: var(--bb-green-rgb);
  --bb-brand-info-rgb: var(--bb-blue-rgb);
  --bb-brand-warning-rgb: var(--bb-orange-rgb);
  --bb-brand-danger-rgb: 212, 48, 48;
  --bb-brand-dark-rgb: var(--bb-brand-navy-rgb);
  --bb-brand-light-rgb: 244, 246, 248;
  --bb-brand-primary-inverse: var(--bb-brand-yellow-inverse);
  --bb-brand-secondary-inverse: var(--bb-gray-800);
  --bb-brand-success-inverse: var(--bb-navy-900);
  --bb-brand-info-inverse: var(--bb-white);
  --bb-brand-warning-inverse: var(--bb-navy-900);
  --bb-brand-danger-inverse: var(--bb-white);
  --bb-brand-dark-inverse: var(--bb-white);
  --bb-brand-light-inverse: var(--bb-gray-800);
  /* -------------------------------------
     Theme Inputs
  ------------------------------------- */
  --bb-theme-primary: var(--bb-brand-primary);
  --bb-theme-secondary: var(--bb-brand-secondary);
  --bb-theme-success: var(--bb-brand-success);
  --bb-theme-info: var(--bb-brand-info);
  --bb-theme-warning: var(--bb-brand-warning);
  --bb-theme-danger: var(--bb-brand-danger);
  --bb-theme-dark: var(--bb-brand-dark);
  --bb-theme-light: var(--bb-brand-light);
  --bb-theme-primary-rgb: var(--bb-brand-primary-rgb);
  --bb-theme-secondary-rgb: var(--bb-brand-secondary-rgb);
  --bb-theme-success-rgb: var(--bb-brand-success-rgb);
  --bb-theme-info-rgb: var(--bb-brand-info-rgb);
  --bb-theme-warning-rgb: var(--bb-brand-warning-rgb);
  --bb-theme-danger-rgb: var(--bb-brand-danger-rgb);
  --bb-theme-dark-rgb: var(--bb-brand-dark-rgb);
  --bb-theme-light-rgb: var(--bb-brand-light-rgb);
  --bb-theme-on-primary: var(--bb-brand-primary-inverse);
  --bb-theme-on-secondary: var(--bb-brand-secondary-inverse);
  --bb-theme-on-success: var(--bb-brand-success-inverse);
  --bb-theme-on-info: var(--bb-brand-info-inverse);
  --bb-theme-on-warning: var(--bb-brand-warning-inverse);
  --bb-theme-on-danger: var(--bb-brand-danger-inverse);
  --bb-theme-on-dark: var(--bb-brand-dark-inverse);
  --bb-theme-on-light: var(--bb-brand-light-inverse);
  /* -------------------------------------
     Semantic Aliases
  ------------------------------------- */
  --bb-primary: var(--bb-theme-primary);
  --bb-secondary: var(--bb-theme-secondary);
  --bb-success: var(--bb-theme-success);
  --bb-info: var(--bb-theme-info);
  --bb-warning: var(--bb-theme-warning);
  --bb-danger: var(--bb-theme-danger);
  --bb-dark: var(--bb-theme-dark);
  --bb-light: var(--bb-theme-light);
  --bb-primary-rgb: var(--bb-theme-primary-rgb);
  --bb-secondary-rgb: var(--bb-theme-secondary-rgb);
  --bb-success-rgb: var(--bb-theme-success-rgb);
  --bb-info-rgb: var(--bb-theme-info-rgb);
  --bb-warning-rgb: var(--bb-theme-warning-rgb);
  --bb-danger-rgb: var(--bb-theme-danger-rgb);
  --bb-dark-rgb: var(--bb-theme-dark-rgb);
  --bb-light-rgb: var(--bb-theme-light-rgb);
  --bb-primary-inverse: var(--bb-theme-on-primary);
  --bb-secondary-inverse: var(--bb-theme-on-secondary);
  --bb-success-inverse: var(--bb-theme-on-success);
  --bb-info-inverse: var(--bb-theme-on-info);
  --bb-warning-inverse: var(--bb-theme-on-warning);
  --bb-danger-inverse: var(--bb-theme-on-danger);
  --bb-dark-inverse: var(--bb-theme-on-dark);
  --bb-light-inverse: var(--bb-theme-on-light);
  /* -------------------------------------
     Page / Domain Accent
     This changes per surface. Primary does not.
  ------------------------------------- */
  --bb-page-accent: var(--bb-primary);
  --bb-page-accent-rgb: var(--bb-primary-rgb);
  --bb-page-accent-soft: var(--bb-yellow-50);
  --bb-page-accent-muted: var(--bb-yellow-100);
  --bb-page-accent-strong: var(--bb-yellow-700);
  --bb-page-accent-hover: var(--bb-primary-hover);
  --bb-page-accent-active: var(--bb-primary-active);
  --bb-page-accent-light: var(--bb-primary-light);
  --bb-page-accent-clarity: rgba(var(--bb-page-accent-rgb), 0.14);
  --bb-page-accent-clarity: color-mix(in srgb, var(--bb-page-accent) 14%, transparent);
  --bb-page-accent-inverse: var(--bb-primary-inverse);
  /* -------------------------------------
     Fixed Ecosystem Shell Tokens
     Header/footer should stay common.
  ------------------------------------- */
  --bb-header-bg: var(--bb-white);
  --bb-header-color: var(--bb-body-color);
  --bb-header-border-color: var(--bb-border-color);
  --bb-header-top-bg: var(--bb-primary);
  --bb-header-top-color: var(--bb-primary-inverse);
  --bb-header-top-muted-color: color-mix(in srgb, var(--bb-primary-inverse) 74%, transparent);
  --bb-header-top-border-color: color-mix(in srgb, var(--bb-primary-inverse) 12%, transparent);
  --bb-header-top-action-bg: color-mix(in srgb, var(--bb-primary-inverse) 8%, transparent);
  --bb-header-top-action-hover-bg: color-mix(in srgb, var(--bb-primary-inverse) 12%, transparent);
  /* Footer - neutral dark shell */
  --bb-footer-bg: var(--bb-coal-400);
  --bb-footer-bg-soft: var(--bb-coal-300);
  --bb-footer-bottom-bg: var(--bb-coal-500);
  --bb-footer-color: color-mix(in srgb, var(--bb-white) 84%, transparent);
  --bb-footer-muted-color: color-mix(in srgb, var(--bb-white) 64%, transparent);
  --bb-footer-subtle-color: color-mix(in srgb, var(--bb-white) 48%, transparent);
  --bb-footer-heading-color: var(--bb-white);
  --bb-footer-link-color: color-mix(in srgb, var(--bb-white) 76%, transparent);
  --bb-footer-link-hover-color: var(--bb-white);
  --bb-footer-border-color: color-mix(in srgb, var(--bb-white) 11%, transparent);
  --bb-footer-border-color-strong: color-mix(in srgb, var(--bb-white) 16%, transparent);
  --bb-footer-surface: color-mix(in srgb, var(--bb-white) 6%, transparent);
  --bb-footer-surface-hover: color-mix(in srgb, var(--bb-white) 9%, transparent);
  --bb-footer-surface-strong: color-mix(in srgb, var(--bb-white) 12%, transparent);
  --bb-footer-accent-surface: color-mix(in srgb, var(--bb-primary) 12%, transparent);
  --bb-footer-accent-border: color-mix(in srgb, var(--bb-primary) 34%, transparent);
  --bb-footer-topline-gradient:
  linear-gradient(
    90deg,
    transparent 0%,
    color-mix(in srgb, var(--bb-primary) 54%, transparent) 18%,
    color-mix(in srgb, var(--bb-primary) 86%, transparent) 50%,
    color-mix(in srgb, var(--bb-primary) 54%, transparent) 82%,
    transparent 100%
  );
  --bb-footer-shadow-accent:
    0 0.75rem 1.75rem color-mix(in srgb, var(--bb-primary) 15%, transparent);
  /* -------------------------------------
     Links
  ------------------------------------- */
  --bb-link-color: var(--bb-blue-700);
  --bb-link-hover-color: var(--bb-primary-active);
  /* -------------------------------------
     Selection
  ------------------------------------- */
  --bb-selection-bg: rgba(var(--bb-primary-rgb), 0.32);
  --bb-selection-bg: color-mix(in srgb, var(--bb-primary) 32%, transparent);
  --bb-selection-color: var(--bb-body-color);
  /* -------------------------------------
     Focus
  ------------------------------------- */
  --bb-focus-ring-width: 0.2rem;
  --bb-focus-ring-opacity: 0.35;
  --bb-focus-ring-alpha: 35%;
  --bb-focus-ring-color: var(--bb-primary);
}

/* -------------------------------------
   SURFACE / DOMAIN ACCENTS
   Primary, header and footer remain common.
------------------------------------- */
html[data-bb-surface=b2b] {
  --bb-page-accent: var(--bb-blue-500);
  --bb-page-accent-rgb: var(--bb-blue-rgb);
  --bb-page-accent-soft: var(--bb-blue-50);
  --bb-page-accent-muted: var(--bb-blue-100);
  --bb-page-accent-strong: var(--bb-blue-700);
  --bb-page-accent-hover: var(--bb-blue-700);
  --bb-page-accent-active: color-mix(in srgb, var(--bb-blue-700) 88%, #000);
  --bb-page-accent-light: var(--bb-blue-100);
  --bb-page-accent-clarity: rgba(var(--bb-blue-rgb), 0.14);
  --bb-page-accent-clarity: color-mix(in srgb, var(--bb-blue-500) 14%, transparent);
  --bb-page-accent-inverse: var(--bb-white);
}

html[data-bb-surface=b2c] {
  --bb-page-accent: var(--bb-orange-500);
  --bb-page-accent-rgb: var(--bb-orange-rgb);
  --bb-page-accent-soft: var(--bb-orange-50);
  --bb-page-accent-muted: var(--bb-orange-100);
  --bb-page-accent-strong: var(--bb-orange-700);
  --bb-page-accent-hover: var(--bb-orange-700);
  --bb-page-accent-active: color-mix(in srgb, var(--bb-orange-700) 88%, #000);
  --bb-page-accent-light: var(--bb-orange-100);
  --bb-page-accent-clarity: rgba(var(--bb-orange-rgb), 0.14);
  --bb-page-accent-clarity: color-mix(in srgb, var(--bb-orange-500) 14%, transparent);
  --bb-page-accent-inverse: var(--bb-white);
}

html[data-bb-surface=fair],
html[data-bb-surface=event] {
  --bb-page-accent: var(--bb-purple-500);
  --bb-page-accent-rgb: var(--bb-purple-rgb);
  --bb-page-accent-soft: var(--bb-purple-50);
  --bb-page-accent-muted: var(--bb-purple-100);
  --bb-page-accent-strong: var(--bb-purple-700);
  --bb-page-accent-hover: var(--bb-purple-700);
  --bb-page-accent-active: color-mix(in srgb, var(--bb-purple-700) 88%, #000);
  --bb-page-accent-light: var(--bb-purple-100);
  --bb-page-accent-clarity: rgba(var(--bb-purple-rgb), 0.14);
  --bb-page-accent-clarity: color-mix(in srgb, var(--bb-purple-500) 14%, transparent);
  --bb-page-accent-inverse: var(--bb-white);
}

html[data-bb-surface=trust] {
  --bb-page-accent: var(--bb-green-500);
  --bb-page-accent-rgb: var(--bb-green-rgb);
  --bb-page-accent-soft: var(--bb-green-50);
  --bb-page-accent-muted: var(--bb-green-100);
  --bb-page-accent-strong: var(--bb-green-700);
  --bb-page-accent-hover: var(--bb-green-700);
  --bb-page-accent-active: color-mix(in srgb, var(--bb-green-700) 88%, #000);
  --bb-page-accent-light: var(--bb-green-100);
  --bb-page-accent-clarity: rgba(var(--bb-green-rgb), 0.14);
  --bb-page-accent-clarity: color-mix(in srgb, var(--bb-green-500) 14%, transparent);
  --bb-page-accent-inverse: var(--bb-white);
}

html[data-bb-surface=tech] {
  --bb-page-accent: var(--bb-turquoise-500);
  --bb-page-accent-rgb: var(--bb-turquoise-rgb);
  --bb-page-accent-soft: var(--bb-turquoise-50);
  --bb-page-accent-muted: var(--bb-turquoise-100);
  --bb-page-accent-strong: var(--bb-turquoise-700);
  --bb-page-accent-hover: var(--bb-turquoise-700);
  --bb-page-accent-active: color-mix(in srgb, var(--bb-turquoise-700) 88%, #000);
  --bb-page-accent-light: var(--bb-turquoise-100);
  --bb-page-accent-clarity: rgba(var(--bb-turquoise-rgb), 0.14);
