  --bb-h4: 1.25rem; /* 20px */
  --bb-h5: 1.125rem; /* 18px */
  --bb-h6: 1rem; /* 16px */
  /* -------------------------------------
     Font Weight Scale
  ------------------------------------- */
  --bb-fw-thin: 100;
  --bb-fw-extralight: 200;
  --bb-fw-light: 300;
  --bb-fw-normal: 400;
  --bb-fw-medium: 500;
  --bb-fw-semibold: 600;
  --bb-fw-bold: 700;
  --bb-fw-extrabold: 800;
  --bb-fw-black: 900;
  /* -------------------------------------
     Semantic Font Weight Tokens
  ------------------------------------- */
  --bb-fw-body: var(--bb-fw-normal);
