/* 4. Layout */
/* =====================================
   Bulbulustur Layout Core
   Type-1 Dashboard (Sidebar | Main)
   ===================================== */
/* -------------------------------------------------
   APP ROOT (en üst)
------------------------------------------------- */
.bb-app {
  min-height: 100vh;
  display: flex;
  flex-direction: row; /* 🔥 YAN YANA */
}

/* -------------------------------------------------
   RIGHT SIDE (header + main + footer)
------------------------------------------------- */
.bb-shell {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

/* -------------------------------------------------
   HEADER (üstte sabit)
------------------------------------------------- */
/* HEADER */
.bb-shell-header {
  position: relative;
  z-index: var(--bb-z-header, 1030);
  flex-shrink: 0;
  background-color: var(--bb-body-bg);
  border-bottom: 1px solid var(--bb-border-color);
}

.bb-shell-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--bb-shell-header-height, 64px);
}

/* LEFT / RIGHT */
.bb-shell-header-left,
.bb-shell-header-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* HEADER MENU */
.bb-shell-header-menu .bb-menu-link {
  padding: 0.5rem 0.75rem;
  font-weight: var(--bb-fw-medium);
  color: var(--bb-body-color);
}

.bb-shell-header-menu .bb-menu-link.is-active {
  color: var(--bb-primary);
}

/* -------------------------------------------------
   MAIN AREA (ortadaki büyüyen alan)
------------------------------------------------- */
.bb-main {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
}

/* -------------------------------------------------
   MAIN INNER (ORTALAYAN KATMAN)
------------------------------------------------- */
.bb-main-inner {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: var(--bb-main-max-width, 1320px);
  margin-left: auto;
  margin-right: auto;
}

/* -------------------------------------------------
   CONTENT (scroll burada)
------------------------------------------------- */
.bb-content {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
}

/* -------------------------------------------------
   FOOTER (altta)
------------------------------------------------- */
.bb-shell-footer {
  flex-shrink: 0;
}

/* =====================================
   Grid System – Bulbulustur Theme
   Bootstrap-safe
   ===================================== */
:root {
  --bb-container-max-width: 1460px;
  --bb-gutter-x: 1.5rem;
  --bb-gutter-y: 1.5rem;
}

/* BB Container (Bootstrap container'ı KIRMAZ) */
.bb-container {
  width: 100%;
  max-width: var(--bb-container-max-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: var(--bb-gutter-x);
  padding-right: var(--bb-gutter-x);
}

/* BB Row (isteğe bağlı, bootstrap'a alternatif) */
.bb-row {
  display: flex;
  flex-wrap: wrap;
  margin-top: calc(-1 * var(--bb-gutter-y));
  margin-left: calc(-0.5 * var(--bb-gutter-x));
  margin-right: calc(-0.5 * var(--bb-gutter-x));
}

/* BB Column */
.bb-col {
  flex: 1 0 0%;
  max-width: 100%;
  padding-left: calc(0.5 * var(--bb-gutter-x));
  padding-right: calc(0.5 * var(--bb-gutter-x));
  margin-top: var(--bb-gutter-y);
}

/* =====================================
   Header Layout
   Minimal + token-first (dark/light safe)
   ===================================== */
.bb-header {
  /* local tokens (override-friendly) */
  --bb-header-bg: var(--bb-body-bg);
  --bb-header-border-width: var(--bb-border-width, 1px);
  --bb-header-border-color: var(--bb-border-color);
  --bb-header-height-local: var(--bb-header-height, 70px);
  --bb-header-zindex: var(--bb-z-header, 1030);
  background-color: var(--bb-header-bg);
  border-bottom: var(--bb-header-border-width) solid var(--bb-header-border-color);
  position: sticky;
  top: 0;
  z-index: var(--bb-header-zindex);
}

.bb-header .container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: var(--bb-header-height-local);
}

.bb-logo {
  font-size: var(--bb-fs-2xl);
  font-weight: var(--bb-fw-bold);
  color: var(--bb-primary);
  text-decoration: none;
}

/* dikkat: bb-nav component ile çakışmasın */
.bb-header-nav {
  display: flex;
  gap: 2rem;
}

.bb-header-nav a {
  color: var(--bb-tertiary-color);
  text-decoration: none;
  font-weight: var(--bb-fw-medium);
}

.bb-header-nav a:hover {
  color: var(--bb-primary);
}

/* =====================================
    Bulbulustur Sidebar
    ===================================== */
.bb-sidebar {
  --bb-sidebar-width: 16.25rem;
  /* colors */
  --bb-sidebar-bg: var(--bb-coal-400);
  --bb-sidebar-border-color: var(--bb-border-color);
  --bb-sidebar-header-divider: rgba(255, 255, 255, 0.06);
  --bb-sidebar-footer-divider: rgba(255, 255, 255, 0.05);
  --bb-sidebar-text-color: rgba(255, 255, 255, 0.85);
  /* layout */
  width: var(--bb-sidebar-width);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  min-height: 100%;
  background-color: var(--bb-sidebar-bg);
  color: var(--bb-sidebar-text-color);
  border-right: 1px solid var(--bb-sidebar-border-color);
}

/* -------------------------------------
Header
------------------------------------- */
.bb-sidebar-header {
  flex-shrink: 0;
  padding: 1rem 1.25rem;
  display: flex;
  align-items: center;
  border-bottom: 1px solid var(--bb-sidebar-header-divider);
}

.bb-sidebar-logo img {
  height: 28px;
  display: block;
}

/* -------------------------------------
    Body (scrollable)
------------------------------------- */
.bb-sidebar-body {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 0.5rem 0;
}

/* -------------------------------------
    Footer
------------------------------------- */
.bb-sidebar-footer {
  flex-shrink: 0;
  padding: 0.75rem 1.25rem;
  border-top: 1px solid var(--bb-sidebar-footer-divider);
}

/* =====================================
   Bulbulustur Toolbar
   ===================================== */
.bb-toolbar {
  flex-shrink: 0;
  border-bottom: 1px solid var(--bb-border-color);
  background-color: var(--bb-body-bg);
  margin-bottom: var(--bb-layout-gap, 1.5rem);
  margin-top: var(--bb-layout-gap, 1.5rem);
}

.bb-toolbar-inner {
  padding: 0;
}

/* ASIL OLAY BURADA */
.bb-toolbar-row {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 1rem;
}

/* LEFT */
.bb-toolbar-col-left {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

/* RIGHT */
.bb-toolbar-col-right {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  white-space: nowrap;
}

/* Mobile */
@media (max-width: 767.98px) {
  .bb-toolbar-row {
    grid-template-columns: 1fr;
  }
  .bb-toolbar-col-right {
    margin-top: 0.5rem;
  }
}
/* =====================================
   Bulbulustur Footer
   Type-1 Dashboard
   ===================================== */
.bb-footer {
  flex-shrink: 0;
  width: 100%;
}

/* ZEMİN */
.bb-footer-bar {
  width: 100%;
  background-color: var(--bb-body-bg);
  border-top: 1px solid var(--bb-border-color);
}

/* İÇ HİZALAMA */
.bb-footer-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 56px;
  padding: 0 1rem;
}

.bb-footer-left,
.bb-footer-right {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.bb-footer-brand {
  font-weight: var(--bb-fw-semibold);
  color: var(--bb-body-color);
  text-decoration: none;
}

.bb-footer-brand:hover {
  color: var(--bb-primary);
}

/* Mobile */
@media (max-width: 767.98px) {
  .bb-footer-inner {
    flex-direction: column;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
  }
}
/* =====================================
   Bundle Layer — Panel Shell
   Panel-only shell/page layouts.
===================================== */
/* Panel + component catalog dark profile.
   Neutral charcoal only: no navy/blue cast in UI surfaces. */
html[data-bb-ui-profile=neutral][data-bs-theme=dark] {
  color-scheme: dark;
  --bb-body-bg: #15171b;
  --bb-body-color: #d2d6dc;
  --bb-fw-body: var(--bb-fw-medium);
  --bb-sidebar-text-color: #c3c8d0;
  --bb-secondary-bg: #202228;
  --bb-tertiary-bg: #1c1e23;
  --bb-surface-bg: #1a1c20;
  --bb-surface-soft: #1e2025;
  --bb-surface-muted: #23262c;
  --bb-surface-elevated: #292c33;
  --bb-emphasis-color: #dde1e6;
  --bb-heading-color: #e1e4e8;
  --bb-secondary-color: #a8aeb8;
  --bb-tertiary-color: #808792;
  --bb-body-bg-rgb: 21, 23, 27;
  --bb-body-color-rgb: 210, 214, 220;
  --bb-secondary-bg-rgb: 32, 34, 40;
  --bb-tertiary-bg-rgb: 28, 30, 35;
  --bb-secondary-color-rgb: 168, 174, 184;
  --bb-tertiary-color-rgb: 128, 135, 146;
  --bb-border-color: rgba(255, 255, 255, 0.08);
  --bb-border-color-strong: rgba(255, 255, 255, 0.13);
  --bb-border-dashed-color: rgba(255, 255, 255, 0.12);
  --bb-brand-secondary: #23262c;
  --bb-brand-secondary-rgb: 35, 38, 44;
  --bb-brand-secondary-inverse: #e3e5e8;
  --bb-brand-dark: #0b0c0f;
  --bb-brand-dark-rgb: 11, 12, 15;
  --bb-brand-dark-inverse: #e3e5e8;
  --bb-brand-light: #292c33;
  --bb-brand-light-rgb: 41, 44, 51;
  --bb-brand-light-inverse: #e3e5e8;
  --bb-theme-secondary: var(--bb-brand-secondary);
  --bb-theme-dark: var(--bb-brand-dark);
  --bb-theme-light: var(--bb-brand-light);
  --bb-theme-secondary-rgb: var(--bb-brand-secondary-rgb);
  --bb-theme-dark-rgb: var(--bb-brand-dark-rgb);
  --bb-theme-light-rgb: var(--bb-brand-light-rgb);
  --bb-theme-on-secondary: var(--bb-brand-secondary-inverse);
  --bb-theme-on-dark: var(--bb-brand-dark-inverse);
  --bb-theme-on-light: var(--bb-brand-light-inverse);
  --bb-secondary: var(--bb-theme-secondary);
  --bb-dark: var(--bb-theme-dark);
  --bb-light: var(--bb-theme-light);
  --bb-secondary-rgb: var(--bb-theme-secondary-rgb);
  --bb-dark-rgb: var(--bb-theme-dark-rgb);
  --bb-light-rgb: var(--bb-theme-light-rgb);
  --bb-secondary-inverse: var(--bb-theme-on-secondary);
  --bb-dark-inverse: var(--bb-theme-on-dark);
  --bb-light-inverse: var(--bb-theme-on-light);
  --bb-header-bg: #181a1f;
  --bb-header-color: #d2d6dc;
  --bb-header-border-color: var(--bb-border-color);
  --bb-footer-bg: #15171b;
  --bb-footer-bg-soft: #191b20;
  --bb-footer-bottom-bg: #121317;
  --bb-link-color: #b6bcc5;
  --bb-link-hover-color: var(--bb-primary);
}

/* =====================================
   Panel Template — Faz 1: Shell
   Existing layout and component classes are reused.
   ===================================== */
.bb-app.bb-panel {
  --bb-panel-sidebar-width: var(--bb-sidebar-width, 16.25rem);
  --bb-panel-sidebar-collapsed-width: 4.5rem;
  --bb-panel-content-gap: var(--bb-layout-gap, 1.5rem);
  --bb-panel-header-height: var(--bb-shell-header-height, 4rem);
  --bb-container-max-width: var(--bb-main-max-width, 1320px);
  /* Panel typography: compact dashboard rhythm, sourced from global tokens. */
  --bb-panel-title-size: var(--bb-h4);
  --bb-panel-title-weight: var(--bb-fw-semibold);
  --bb-panel-title-color: var(--bb-emphasis-color);
  --bb-panel-nav-size: var(--bb-fs-sm);
  --bb-panel-nav-weight: var(--bb-fw-medium);
  --bb-panel-crumb-size: var(--bb-fs-xs);
  --bb-panel-muted-color: var(--bb-secondary-color);
  background: var(--bb-tertiary-bg);
  color: var(--bb-body-color);
}

/* Keep panel titles Bulbulustur-scale without shrinking site-wide headings. */
.bb-panel .bb-page-title {
  font-family: var(--bb-font-heading);
  font-size: var(--bb-panel-title-size);
  font-weight: var(--bb-panel-title-weight);
  line-height: var(--bb-line-height-heading);
  letter-spacing: var(--bb-heading-letter-spacing);
  color: var(--bb-panel-title-color);
}

.bb-panel .bb-breadcrumb {
  --bb-breadcrumb-font-size: var(--bb-panel-crumb-size);
  --bb-breadcrumb-color: var(--bb-panel-muted-color);
  --bb-breadcrumb-active-color: var(--bb-panel-title-color);
}

.bb-panel .bb-panel-brand-text {
  font-size: var(--bb-fs-lg);
  font-weight: var(--bb-fw-semibold);
}

/* Compact panel actions; keep global button scale and explicit sizes unchanged. */
.bb-panel .btn:not(.btn-sm):not(.btn-lg),
.bb-panel .bb-btn:not(.bb-btn-sm):not(.bb-btn-lg):not(.btn-sm):not(.btn-lg) {
  --bb-btn-font-size: var(--bb-fs-sm);
  --bb-btn-padding-x: var(--bb-space-4);
  --bb-btn-line-height: var(--bb-line-height-heading);
}

.bb-panel > .bb-sidebar {
  width: var(--bb-panel-sidebar-width);
  height: 100vh;
  min-height: 0;
  position: sticky;
  top: 0;
  transition: width var(--bb-transition-normal);
}

.bb-panel .bb-shell {
  min-height: 100vh;
}

.bb-panel .bb-shell-header-inner {
  min-height: var(--bb-panel-header-height);
  height: auto;
  padding-inline: var(--bb-panel-content-gap);
  gap: var(--bb-panel-content-gap);
}

.bb-panel .bb-shell-header-left,
.bb-panel .bb-shell-header-right,
.bb-panel .bb-sidebar-header {
  min-width: 0;
}

.bb-panel .bb-sidebar-header,
.bb-panel .bb-sidebar-footer {
  gap: var(--bb-panel-content-gap);
}

.bb-panel .bb-sidebar-header {
  justify-content: space-between;
}

.bb-panel .bb-sidebar-header .bb-sidebar-logo {
  min-width: 0;
  overflow: hidden;
}

.bb-panel .bb-sidebar-logo img {
  max-width: 100%;
}

.bb-panel .bb-sidebar-footer {
  color: inherit;
}

.bb-panel .bb-panel-content-container {
  width: 100%;
  padding-inline: var(--bb-panel-content-gap);
}

.bb-panel .bb-toolbar {
  margin-block: var(--bb-panel-content-gap);
  border: 0;
  background: transparent;
}

.bb-panel .bb-content {
  padding-bottom: var(--bb-panel-content-gap);
}

.bb-panel .bb-shell-footer {
  margin-top: auto;
}

.bb-panel .bb-panel-icon-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  border: 0;
  background: transparent;
  color: inherit;
  border-radius: var(--bb-radius);
  padding: var(--bb-menu-link-py, 0.65rem);
  cursor: pointer;
}

.bb-panel .bb-panel-icon-button:hover {
  background: var(--bb-tertiary-bg);
  color: var(--bb-primary-text);
}

.bb-panel .bb-panel-icon-button:focus-visible {
  outline: var(--bb-focus-ring-width, 0.2rem) solid var(--bb-primary);
  outline-offset: var(--bb-focus-ring-width);
}

.bb-panel .bb-sidebar .bb-panel-icon-button:hover {
  background: color-mix(in srgb, currentColor 12%, transparent);
  color: inherit;
}

.bb-panel .bb-panel-brand-text {
  font-weight: var(--bb-fw-semibold);
  white-space: nowrap;
}

.bb-panel .bb-panel-sidebar-label {
  white-space: nowrap;
}

.bb-panel .bb-panel-sidebar-link {
  display: flex;
  align-items: center;
  gap: var(--bb-panel-content-gap);
  padding: var(--bb-menu-link-py, 0.65rem) var(--bb-menu-link-px, 0.9rem);
  color: inherit;
  text-decoration: none;
  border-radius: var(--bb-radius);
}

.bb-panel .bb-panel-sidebar-link:hover,
.bb-panel .bb-panel-sidebar-link[aria-current=page] {
  background: color-mix(in srgb, currentColor 12%, transparent);
  color: inherit;
}

.bb-panel .bb-panel-sidebar-link:focus-visible {
  outline: var(--bb-focus-ring-width, 0.2rem) solid currentColor;
  outline-offset: var(--bb-focus-ring-width);
}

.bb-panel .bb-panel-sidebar-link .material-symbols-outlined {
  flex: 0 0 auto;
}

.bb-panel .bb-panel-backdrop {
  display: none;
}

@media (min-width: 992px) {
  .bb-panel[data-bb-sidebar-collapsed=true] {
    --bb-panel-sidebar-width: var(--bb-panel-sidebar-collapsed-width);
  }
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-sidebar-header {
    justify-content: center;
  }
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-sidebar-logo,
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-panel-sidebar-label,
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-panel-brand-text {
    display: none;
  }
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-panel-sidebar-link {
    justify-content: center;
  }
}
@media (max-width: 991.98px) {
  .bb-app.bb-panel > .bb-sidebar {
    position: fixed;
    inset-block: 0;
    inset-inline-start: 0;
    z-index: var(--bb-z-drawer);
    transform: translateX(-100%);
    transition: transform var(--bb-transition-normal);
    width: var(--bb-panel-sidebar-width);
    max-width: 85vw;
  }
  .bb-app.bb-panel[data-bb-sidebar-open=true] > .bb-sidebar {
    transform: translateX(0);
  }
  .bb-panel .bb-panel-backdrop {
    position: fixed;
    inset: 0;
    display: block;
    border: 0;
    background: color-mix(in srgb, var(--bb-black) 45%, transparent);
    z-index: calc(var(--bb-z-drawer) - 1);
    visibility: hidden;
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--bb-transition-normal), visibility var(--bb-transition-normal);
  }
  .bb-panel[data-bb-sidebar-open=true] .bb-panel-backdrop {
    visibility: visible;
    opacity: 1;
    pointer-events: auto;
  }
  .bb-panel .bb-shell {
    width: 100%;
  }
  .bb-panel .bb-shell-header-inner {
    flex-wrap: wrap;
  }
}
@media (prefers-reduced-motion: reduce) {
  .bb-app.bb-panel > .bb-sidebar,
  .bb-panel .bb-panel-backdrop {
    transition: none;
  }
}
/* Faz 2 — Panel sidebar / existing bb-menu extensions */
.bb-panel .bb-sidebar .bb-menu {
  --bb-menu-bg: var(--bb-sidebar-bg);
  --bb-menu-link-font-size: var(--bb-panel-nav-size);
  --bb-menu-link-font-weight: var(--bb-panel-nav-weight);
  --bb-menu-section-font-size: var(--bb-panel-crumb-size);
  --bb-menu-link-color: var(--bb-sidebar-text-color);
  --bb-menu-link-hover-color: var(--bb-sidebar-text-color);
  --bb-menu-link-active-color: var(--bb-sidebar-text-color);
  --bb-menu-link-hover-bg: color-mix(in srgb, currentColor 10%, transparent);
  --bb-menu-link-active-bg: color-mix(in srgb, var(--bb-primary) 30%, transparent);
  --bb-menu-link-here-bg: color-mix(in srgb, var(--bb-primary) 15%, transparent);
  --bb-menu-section-color: var(--bb-sidebar-text-color);
  --bb-menu-bullet-color: var(--bb-sidebar-text-color);
  padding-inline: var(--bb-menu-gap);
}

/* Sidebar accordion is vertical. Core .bb-menu-item defaults to a flex row,
   which places submenu beside its trigger and spills out of the sidebar. */
.bb-panel .bb-sidebar .bb-menu.bb-menu-column .bb-menu-item {
  flex-direction: column;
  width: 100%;
  min-width: 0;
}

.bb-panel .bb-sidebar .bb-menu.bb-menu-column .bb-menu-item > .bb-menu-link {
  flex: 0 0 auto;
}

.bb-panel .bb-sidebar .bb-menu.bb-menu-column .bb-menu-sub-accordion {
  width: 100%;
  min-width: 0;
}

.bb-panel .bb-sidebar .bb-menu.bb-menu-column .bb-menu-sub-content {
  min-width: 0;
}

.bb-panel .bb-sidebar .bb-menu-link {
  border: 0;
  background: transparent;
  cursor: pointer;
  text-align: start;
}

.bb-panel .bb-sidebar .bb-menu .bb-menu-section {
  margin-block-start: var(--bb-menu-gap);
}

.bb-panel .bb-sidebar .bb-menu .bb-menu-item.active > .bb-menu-link,
.bb-panel .bb-sidebar .bb-menu .bb-menu-link[aria-current=page] {
  color: var(--bb-sidebar-text-color);
  background: var(--bb-menu-link-active-bg);
}

.bb-panel .bb-sidebar .bb-menu .bb-menu-link:focus-visible {
  outline: var(--bb-focus-ring-width) solid var(--bb-primary);
  outline-offset: var(--bb-focus-ring-width);
}

.bb-panel .bb-sidebar .bb-menu .bb-menu-sub-accordion .bb-menu-link {
  font-size: var(--bb-fs-sm);
}

.bb-panel .bb-sidebar .bb-menu .bb-menu-sub .bb-menu-sub .bb-menu-link {
  padding-inline-start: calc(var(--bb-menu-link-px) + var(--bb-menu-link-px) + var(--bb-menu-icon-size));
}

.bb-panel .bb-sidebar .bb-menu .bb-menu-item:not(.show) > .bb-menu-sub-accordion {
  visibility: hidden;
}

.bb-panel .bb-sidebar .bb-menu .bb-menu-item.show > .bb-menu-sub-accordion {
  visibility: visible;
}

@media (min-width: 992px) {
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-sidebar .bb-menu .bb-menu-section,
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-sidebar .bb-menu .bb-menu-title,
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-sidebar .bb-menu .bb-menu-arrow,
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-sidebar .bb-menu .bb-menu-badge,
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-sidebar .bb-menu .bb-menu-sub {
    display: none;
  }
  .bb-panel[data-bb-sidebar-collapsed=true] .bb-sidebar .bb-menu .bb-menu-link {
    justify-content: center;
  }
}
/* Faz 3 — Panel header navigation */
.bb-panel .bb-panel-topnav {
  display: flex;
  align-items: center;
  gap: var(--bb-menu-gap, 0.25rem);
  min-width: 0;
}

.bb-panel .bb-panel-topnav .bb-menu {
  --bb-menu-sub-z: var(--bb-z-dropdown);
  --bb-menu-link-font-size: var(--bb-panel-nav-size);
  --bb-menu-link-font-weight: var(--bb-panel-nav-weight);
  --bb-menu-link-color: var(--bb-panel-muted-color);
  --bb-menu-link-hover-color: var(--bb-panel-title-color);
}

.bb-panel .bb-panel-topnav .bb-menu-sub {
  min-width: var(--bb-menu-sub-min-width);
}

.bb-panel .bb-panel-topnav .bb-menu-link {
  white-space: nowrap;
}

/* Header menu: normalize button triggers to the same flat navigation as links.
   Bootstrap's generic button appearance must not leak into bb-menu. */
.bb-panel .bb-panel-topnav .bb-menu-item > .bb-menu-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--bb-space-2);
  appearance: none;
  margin: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  padding: var(--bb-space-2) var(--bb-space-3);
  border-radius: var(--bb-radius);
  color: var(--bb-panel-muted-color);
  font-family: var(--bb-font-sans);
  font-size: var(--bb-panel-nav-size);
  font-weight: var(--bb-panel-nav-weight);
  line-height: var(--bb-line-height-heading);
  text-decoration: none;
  cursor: pointer;
}

.bb-panel .bb-panel-topnav .bb-menu-item > .bb-menu-link:hover,
.bb-panel .bb-panel-topnav .bb-menu-item.show > .bb-menu-link,
.bb-panel .bb-panel-topnav .bb-menu-item > .bb-menu-link[aria-current=page] {
  background: var(--bb-tertiary-bg);
  color: var(--bb-panel-title-color);
}

.bb-panel .bb-panel-topnav .bb-menu-item > .bb-menu-link:focus-visible {
  outline: var(--bb-focus-ring-width) solid var(--bb-primary);
  outline-offset: 2px;
}

.bb-panel .bb-panel-topnav .bb-menu-arrow {
  opacity: 0.7;
}

.bb-panel .bb-panel-topnav .bb-menu-sub {
