  gap: var(--bb-space-2);
  width: 100%;
  padding: var(--bb-space-2) var(--bb-space-3);
  border: 0;
  border-radius: var(--bb-radius-sm);
  background: transparent;
  color: var(--bb-body-color);
  text-align: left;
  font-size: var(--bb-fs-sm);
}

.bb-panel .bb-panel-user-language-option:hover,
.bb-panel .bb-panel-user-language-option.active {
