  height: 1.35rem;
  border-radius: var(--bb-radius-pill);
  object-fit: cover;
  flex: none;
}

.bb-panel .bb-panel-language-check {
  visibility: hidden;
  color: var(--bb-primary-text);
  font-size: var(--bb-fs-base);
}

.bb-panel .bb-panel-user-language-option.active .bb-panel-language-check {
  visibility: visible;
}

/* Faz 5 — toolbar varyantları; mevcut .bb-toolbar tamamlayıcıları */
.bb-panel .bb-panel-toolbar-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: var(--bb-menu-gap, 0.25rem);
}

.bb-panel .bb-panel-toolbar-description {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
}

.bb-panel .bb-panel-toolbar-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--bb-menu-gap, 0.25rem);
  margin-block-start: var(--bb-panel-content-gap);
  border-bottom: var(--bb-border-width, 1px) solid var(--bb-border-color);
}

.bb-panel .bb-panel-toolbar-tabs a {
  color: var(--bb-secondary-color);
  text-decoration: none;
  padding: var(--bb-menu-link-py, 0.65rem) var(--bb-menu-link-px, 0.9rem);
  border-bottom: var(--bb-border-width, 1px) solid transparent;
}

.bb-panel .bb-panel-toolbar-tabs a[aria-current=page] {
  border-bottom-color: var(--bb-primary);
  color: var(--bb-primary-text);
}

@media (max-width: 767.98px) {
  .bb-panel .bb-panel-toolbar-actions {
    justify-content: flex-start;
  }
}
/* Faz 6 — same shell, three layout modes */
.bb-panel[data-bb-panel-layout=top] > .bb-sidebar,
.bb-panel[data-bb-panel-layout=auth] > .bb-sidebar {
  display: none;
}

.bb-panel[data-bb-panel-layout=top] .bb-panel-topnav {
  display: flex;
}

.bb-panel[data-bb-panel-layout=auth] .bb-shell-header,
.bb-panel[data-bb-panel-layout=auth] .bb-toolbar,
.bb-panel[data-bb-panel-layout=auth] .bb-shell-footer {
  display: none;
}

.bb-panel[data-bb-panel-layout=auth] .bb-main,
.bb-panel[data-bb-panel-layout=auth] .bb-main-inner {
  justify-content: center;
  align-items: center;
}

.bb-panel[data-bb-panel-layout=auth] .bb-content {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}

.bb-panel[data-bb-panel-layout=auth] .bb-panel-content-container {
  max-width: var(--bb-menu-sub-min-width, 24rem);
}

.bb-panel .bb-panel-layout-switcher {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--bb-menu-gap, 0.25rem);
}

.bb-panel .bb-panel-layout-switcher button[aria-pressed=true] {
  background-color: var(--bb-primary);
  color: var(--bb-primary-inverse);
}

@media (max-width: 991.98px) {
  .bb-panel[data-bb-panel-layout=top] .bb-panel-topnav {
    display: flex;
    flex-wrap: wrap;
  }
  .bb-panel[data-bb-panel-layout=top] [data-bb-panel-sidebar-toggle] {
    display: none;
  }
}
/* Faz 7 — selected placeholder page styling */
.bb-panel .bb-panel-template-catalog {
  display: flex;
  flex-wrap: wrap;
  gap: var(--bb-menu-gap, 0.25rem);
}

.bb-panel .bb-menu-link[aria-current=page] {
  font-weight: var(--bb-fw-semibold);
}

.bb-panel .bb-empty-state .material-symbols-outlined {
  color: var(--bb-secondary-color);
}

/* Faz 8.1 — KPI cards, reuse bb-card */
.bb-panel .bb-dashboard-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--bb-panel-content-gap);
}

.bb-panel .bb-dashboard-kpi {
  --bb-dashboard-kpi-accent:var(--bb-primary);
  position: relative;
  overflow: hidden;
}

.bb-panel .bb-dashboard-kpi-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--bb-menu-gap);
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
}

.bb-panel .bb-dashboard-kpi-icon {
  color: var(--bb-dashboard-kpi-accent);
}

.bb-panel .bb-dashboard-kpi-value {
  display: block;
  color: var(--bb-body-color);
  font-size: var(--bb-h2);
  font-weight: var(--bb-fw-bold);
  margin-block: var(--bb-menu-link-py);
}

.bb-panel .bb-dashboard-kpi-foot {
  display: flex;
  align-items: center;
  gap: var(--bb-menu-gap);
  font-size: var(--bb-fs-sm);
  color: var(--bb-secondary-color);
}

.bb-panel .bb-dashboard-kpi[data-tone=success] {
  --bb-dashboard-kpi-accent:var(--bb-chart-3);
}

.bb-panel .bb-dashboard-kpi[data-tone=info] {
  --bb-dashboard-kpi-accent:var(--bb-chart-1);
}

.bb-panel .bb-dashboard-kpi[data-tone=warning] {
  --bb-dashboard-kpi-accent:var(--bb-chart-4);
}

.bb-panel .bb-dashboard-kpi .bb-progress {
  --bb-progress-bar-bg:var(--bb-dashboard-kpi-accent);
  margin-block-start: var(--bb-panel-content-gap);
}

.bb-panel .bb-dashboard-kpi .bb-progress__bar[data-level="86"] {
  width: 86%;
}

.bb-panel .bb-dashboard-kpi .bb-progress__bar[data-level="72"] {
  width: 72%;
}

.bb-panel .bb-dashboard-kpi .bb-progress__bar[data-level="61"] {
  width: 61%;
}

.bb-panel .bb-dashboard-kpi .bb-progress__bar[data-level="94"] {
  width: 94%;
}

@media (max-width: 1199.98px) {
  .bb-panel .bb-dashboard-kpis {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 575.98px) {
  .bb-panel .bb-dashboard-kpis {
    grid-template-columns: 1fr;
  }
}
/* Faz 8.2 — donut and legend with chart tokens */
.bb-panel .bb-dashboard-donut-layout {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: var(--bb-panel-content-gap);
}

.bb-panel .bb-dashboard-donut {
  width: 11rem;
  aspect-ratio: 1;
  flex: none;
  border-radius: var(--bb-radius-pill);
  background: conic-gradient(var(--bb-chart-1) 0% 44%, var(--bb-chart-3) 44% 74%, var(--bb-chart-2) 74% 90%, var(--bb-chart-4) 90% 100%);
  display: grid;
  place-items: center;
}

.bb-panel .bb-dashboard-donut-center {
  width: 72%;
  aspect-ratio: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  border-radius: var(--bb-radius-pill);
  background: var(--bb-body-bg);
  color: var(--bb-body-color);
  text-align: center;
}

.bb-panel .bb-dashboard-donut-center strong {
  font-size: var(--bb-h3);
}

.bb-panel .bb-dashboard-donut-center small {
  color: var(--bb-secondary-color);
}

.bb-panel .bb-dashboard-legend {
  flex: 1 1 12rem;
  list-style: none;
  margin: 0;
  padding: 0;
}

.bb-panel .bb-dashboard-legend li {
  display: flex;
  align-items: center;
  gap: var(--bb-menu-gap);
  padding-block: var(--bb-menu-link-py);
  border-bottom: var(--bb-border-width, 1px) solid var(--bb-border-color);
}

.bb-panel .bb-dashboard-legend li:last-child {
  border: 0;
}

.bb-panel .bb-dashboard-legend-label {
  flex: 1;
  color: var(--bb-secondary-color);
}

.bb-panel .bb-dashboard-legend-mark {
  width: var(--bb-menu-icon-size, 1.15rem);
  aspect-ratio: 1;
  border-radius: var(--bb-radius-pill);
  background: var(--bb-chart-1);
}

.bb-panel .bb-dashboard-legend-mark[data-series="2"] {
  background: var(--bb-chart-2);
}

.bb-panel .bb-dashboard-legend-mark[data-series="3"] {
  background: var(--bb-chart-3);
}

.bb-panel .bb-dashboard-legend-mark[data-series="4"] {
  background: var(--bb-chart-4);
}

/* Faz 8.3 — week strip and appointments */
.bb-panel .bb-dashboard-week {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: var(--bb-menu-gap);
}

.bb-panel .bb-dashboard-day {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--bb-menu-gap);
  padding: var(--bb-menu-link-py);
  border: var(--bb-border-width, 1px) solid var(--bb-border-color);
  border-radius: var(--bb-radius);
  background: var(--bb-body-bg);
  color: var(--bb-body-color);
  text-align: center;
}

.bb-panel .bb-dashboard-day small {
  color: var(--bb-secondary-color);
}

.bb-panel .bb-dashboard-day[aria-current=date] {
  background: var(--bb-primary-light);
  border-color: var(--bb-primary);
  color: var(--bb-primary-text);
}

.bb-panel .bb-dashboard-appointments {
  margin: 0;
  padding: 0;
  list-style: none;
}

.bb-panel .bb-dashboard-appointments li {
  display: flex;
  gap: var(--bb-panel-content-gap);
  padding-block: var(--bb-menu-link-py);
  border-bottom: var(--bb-border-width, 1px) solid var(--bb-border-color);
}

.bb-panel .bb-dashboard-appointments li:last-child {
  border: 0;
}

.bb-panel .bb-dashboard-appointments time {
  flex: none;
  font-weight: var(--bb-fw-semibold);
}

.bb-panel .bb-dashboard-appointments small {
  display: block;
  color: var(--bb-secondary-color);
}

@media (max-width: 575.98px) {
  .bb-panel .bb-dashboard-day {
    padding: var(--bb-menu-gap);
  }
  .bb-panel .bb-dashboard-week {
    gap: 0;
  }
}
/* Calendar page: month leave planner + resource appointment grid. Only panel composition. */
.bb-panel .bb-calendar-page .bb-panel-content-container {
  display: grid;
  gap: var(--bb-space-3);
}

.bb-panel .bb-cal-shell {
  overflow: hidden;
  min-width: 0;
}

.bb-panel .bb-cal-topbar {
