  white-space: nowrap;
}

.bb-panel .bb-cal-mode-switch,
.bb-panel .bb-cal-view-switch {
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius);
  padding: var(--bb-space-1);
