}

.bb-panel .bb-cal-mode-switch button,
.bb-panel .bb-cal-view-switch button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--bb-space-2);
  padding: var(--bb-space-2) var(--bb-space-3);
  border: 0;
  border-radius: var(--bb-radius-sm);
  background: transparent;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
