}

.bb-panel .bb-cal-mini-weekdays,
.bb-panel .bb-cal-mini-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
}

.bb-panel .bb-cal-mini-weekdays {
  margin-top: var(--bb-space-3);
  text-align: center;
  font-size: var(--bb-fs-xs);
  color: var(--bb-secondary-color);
}

.bb-panel .bb-cal-mini-grid {
  gap: var(--bb-space-1);
  margin-top: var(--bb-space-2);
}

.bb-panel .bb-cal-mini-day {
  display: grid;
  place-items: center;
