  background: var(--bb-primary-light);
  font-weight: var(--bb-fw-semibold);
}

.bb-panel .bb-cal-mini-dot {
  position: absolute;
  bottom: var(--bb-space-1);
  width: var(--bb-space-1);
  height: var(--bb-space-1);
