.bb-panel .bb-cal-side-section {
  display: grid;
  gap: var(--bb-space-3);
  min-width: 0;
}

.bb-panel .bb-cal-upcoming,
.bb-panel .bb-cal-team-list {
  display: grid;
  gap: var(--bb-space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}

.bb-panel .bb-cal-upcoming-link {
