.bb-panel .bb-chat-presence > span.is-online {
  background: var(--bb-success);
}

.bb-panel .bb-chat-presence small {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
}

.bb-panel .bb-chat-messages {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--bb-space-4);
  min-height: 0;
  max-height: 58vh;
  overflow: auto;
  padding: calc(var(--bb-space-4) + var(--bb-space-2));
}

.bb-panel .bb-chat-message {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  max-width: min(78%, 38rem);
  gap: var(--bb-space-2);
}

.bb-panel .bb-chat-message[data-side=out] {
  align-self: flex-end;
  align-items: flex-end;
}

.bb-panel .bb-chat-message-meta {
  display: flex;
  align-items: center;
  gap: var(--bb-space-2);
  font-size: var(--bb-fs-xs);
}

.bb-panel .bb-chat-message-meta strong {
  color: var(--bb-heading-color);
  font-weight: var(--bb-fw-semibold);
}

.bb-panel .bb-chat-message-meta small {
  color: var(--bb-secondary-color);
}

.bb-panel .bb-chat-bubble {
  padding: var(--bb-space-3) var(--bb-space-4);
  border-radius: var(--bb-radius);
  background: var(--bb-tertiary-bg);
  color: var(--bb-body-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
  overflow-wrap: anywhere;
}

.bb-panel .bb-chat-message[data-side=out] .bb-chat-bubble {
  background: var(--bb-primary-light);
  color: var(--bb-body-color);
}

.bb-panel .bb-chat-compose {
  padding: var(--bb-space-4);
  border-top: var(--bb-border-width) solid var(--bb-border-color);
}

.bb-panel .bb-chat-compose textarea {
  resize: vertical;
  min-height: 5rem;
  max-height: 11rem;
}

.bb-panel .bb-chat-compose-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--bb-space-3);
  margin-top: var(--bb-space-3);
}

.bb-panel .bb-chat-compose-tools {
  display: flex;
  align-items: center;
  gap: var(--bb-space-1);
}

.bb-panel .bb-chat-list-item:focus-visible {
  outline: var(--bb-focus-ring-width) solid var(--bb-primary);
  outline-offset: var(--bb-focus-ring-width);
}

@media (max-width: 991.98px) {
  .bb-panel .bb-chat-workspace {
    grid-template-columns: minmax(16rem, 0.75fr) minmax(0, 1.25fr);
  }
  .bb-panel .bb-chat-message {
    max-width: 88%;
  }
}
@media (max-width: 767.98px) {
  .bb-panel .bb-chat-workspace {
    grid-template-columns: 1fr;
  }
  .bb-panel .bb-chat-list {
    max-height: 22rem;
  }
  .bb-panel .bb-chat-thread {
    min-height: 38rem;
  }
  .bb-panel .bb-chat-messages {
    max-height: 48vh;
  }
}
@media (max-width: 575.98px) {
  .bb-panel .bb-chat-page {
    padding: var(--bb-space-3);
  }
  .bb-panel .bb-chat-message {
    max-width: 94%;
  }
  .bb-panel .bb-chat-compose-actions {
    align-items: stretch;
    flex-direction: column;
  }
  .bb-panel .bb-chat-compose-actions > .btn {
    width: 100%;
  }
}
/* Chat mesaj başlığı: mevcut bb-chat düzeninin sayfaya özgü avatar kompozisyonu. */
.bb-panel .bb-chat-message-heading {
  display: flex;
  align-items: center;
  gap: var(--bb-space-2);
}

.bb-panel .bb-chat-message[data-side=out] .bb-chat-message-heading {
  flex-direction: row-reverse;
}

.bb-panel .bb-chat-message-avatar {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: calc(var(--bb-space-4) * 2);
  height: calc(var(--bb-space-4) * 2);
  border-radius: var(--bb-radius-pill);
  background: var(--bb-tertiary-bg);
  color: var(--bb-primary-text);
  object-fit: cover;
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-semibold);
}

.bb-panel .bb-chat-list-item[aria-current=true] {
  border-color: var(--bb-primary);
  background: var(--bb-primary-light);
}

/* Support Center — panel-scoped, shared card/form/accordion tokens. */
.bb-panel .bb-support-hero {
  overflow: hidden;
}

.bb-panel .bb-support-hero-inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(12rem, 36%);
  gap: var(--bb-space-4);
  align-items: center;
  padding: clamp(1.25rem, 4vw, 3rem);
}

.bb-panel .bb-support-hero h2 {
  margin: 0 0 var(--bb-space-4);
  font-size: var(--bb-h3);
  font-weight: var(--bb-fw-semibold);
  color: var(--bb-emphasis-color);
}

.bb-panel .bb-support-search {
  position: relative;
  max-width: 32rem;
}

.bb-panel .bb-support-search .material-symbols-outlined {
  position: absolute;
  inset-inline-start: var(--bb-space-3);
  top: 50%;
  transform: translateY(-50%);
  color: var(--bb-primary-text);
}

.bb-panel .bb-support-search .form-control {
  padding-inline-start: 2.8rem;
  min-height: 3rem;
}

.bb-panel .bb-support-illustration {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 12rem;
  isolation: isolate;
  position: relative;
}

.bb-panel .bb-support-illustration::before {
  content: "";
  position: absolute;
  width: min(14rem, 80%);
  aspect-ratio: 1;
  border-radius: 50%;
  background: color-mix(in srgb, var(--bb-primary) 12%, transparent);
  z-index: -1;
}

.bb-panel .bb-support-illustration .material-symbols-outlined {
  font-size: clamp(5rem, 10vw, 9rem);
  color: var(--bb-primary-text);
  font-variation-settings: "FILL" 0, "wght" 200;
}

.bb-panel .bb-support-hero-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: var(--bb-space-3);
  padding: var(--bb-space-3) var(--bb-space-4);
  background: var(--bb-tertiary-bg);
}

.bb-panel .bb-support-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--bb-space-2);
}

.bb-panel .bb-support-tab {
  border: 0;
  border-radius: var(--bb-radius);
  background: transparent;
  color: var(--bb-secondary-color);
  padding: var(--bb-space-2) var(--bb-space-3);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-medium);
  cursor: pointer;
}

.bb-panel .bb-support-tab[aria-selected=true] {
  background: var(--bb-primary-light);
  color: var(--bb-primary-text);
}

.bb-panel .bb-support-tab:focus-visible {
  outline: var(--bb-focus-ring-width) solid var(--bb-primary);
}

.bb-panel .bb-support-resource-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--bb-panel-content-gap);
  margin-top: var(--bb-panel-content-gap);
}

.bb-panel .bb-support-resource-grid > .bb-card {
  min-width: 0;
}

.bb-panel .bb-support-resource-grid .bb-card-body {
  padding: var(--bb-space-4);
}

.bb-panel .bb-support-card-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--bb-space-3);
  margin-bottom: var(--bb-space-3);
}

.bb-panel .bb-support-card-heading h3 {
  margin: 0;
  font-size: var(--bb-fs-lg);
  color: var(--bb-emphasis-color);
  font-weight: var(--bb-fw-semibold);
}

.bb-panel .bb-support-card-heading a {
  color: var(--bb-primary-text);
  font-size: var(--bb-fs-xs);
  text-decoration: none;
}

.bb-panel .bb-support-qa {
  border-bottom: var(--bb-border-width, 1px) solid var(--bb-border-color);
}

.bb-panel .bb-support-qa:last-child {
  border-bottom: 0;
}

.bb-panel .bb-support-qa button {
  display: flex;
  align-items: center;
  width: 100%;
  gap: var(--bb-space-2);
  padding: var(--bb-space-3) 0;
  border: 0;
  background: transparent;
  color: var(--bb-body-color);
  text-align: start;
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-medium);
  cursor: pointer;
}

.bb-panel .bb-support-qa button .material-symbols-outlined {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-base);
  transition: transform var(--bb-transition-fast);
}

.bb-panel .bb-support-qa button[aria-expanded=true] .material-symbols-outlined {
  transform: rotate(90deg);
  color: var(--bb-primary-text);
}

.bb-panel .bb-support-qa [hidden] {
  display: none;
}

.bb-panel .bb-support-qa-answer {
  padding: 0 0 var(--bb-space-3) calc(var(--bb-space-3) + var(--bb-fs-base));
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
}

.bb-panel .bb-support-video {
  display: grid;
  place-items: center;
  min-height: 12rem;
  gap: var(--bb-space-2);
  background: var(--bb-tertiary-bg);
  border-radius: var(--bb-radius);
  color: var(--bb-emphasis-color);
  text-align: center;
}

.bb-panel .bb-support-video .material-symbols-outlined {
  font-size: 3rem;
  color: var(--bb-primary-text);
}

.bb-panel .bb-support-docs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--bb-space-3);
}

.bb-panel .bb-support-docs a {
  display: flex;
  gap: var(--bb-space-2);
  align-items: center;
  padding: var(--bb-space-3);
  color: var(--bb-body-color);
  font-size: var(--bb-fs-sm);
  text-decoration: none;
  border-radius: var(--bb-radius);
}

.bb-panel .bb-support-docs a:hover {
  background: var(--bb-tertiary-bg);
  color: var(--bb-primary-text);
}

.bb-panel .bb-support-docs .material-symbols-outlined {
  font-size: var(--bb-fs-base);
  color: var(--bb-secondary-color);
}

.bb-panel .bb-support-notice {
  font-size: var(--bb-fs-xs);
  color: var(--bb-secondary-color);
}

.bb-panel .bb-support-empty[hidden], .bb-panel .bb-support-item[hidden], .bb-panel .bb-support-view[hidden] {
  display: none;
}

@media (max-width: 991.98px) {
  .bb-panel .bb-support-resource-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 575.98px) {
  .bb-panel .bb-support-hero-inner {
    grid-template-columns: 1fr;
  }
  .bb-panel .bb-support-illustration {
    display: none;
  }
  .bb-panel .bb-support-docs {
    grid-template-columns: 1fr;
  }
  .bb-panel .bb-support-hero-footer {
    align-items: stretch;
  }
  .bb-panel .bb-support-hero-footer .btn {
    width: 100%;
  }
}
/* Updates / changelog page */
.bb-panel .bb-updates-page {
  padding: var(--bb-space-4);
}

.bb-panel .bb-updates-hero {
  margin-bottom: calc(var(--bb-space-4) + var(--bb-space-2));
}

.bb-panel .bb-updates-hero .bb-card-body {
  padding: calc(var(--bb-space-4) * 1.5);
}

.bb-panel .bb-updates-date {
  display: flex;
  align-items: center;
  gap: var(--bb-space-2);
  margin-bottom: var(--bb-space-3);
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
}

.bb-panel .bb-updates-hero h2 {
  margin: 0 0 var(--bb-space-2);
  font-size: var(--bb-h3);
  color: var(--bb-heading-color);
}

.bb-panel .bb-updates-hero h3 {
  margin: var(--bb-space-4) 0 var(--bb-space-2);
  font-size: var(--bb-h5);
  color: var(--bb-heading-color);
}

.bb-panel .bb-updates-hero p {
  margin: 0;
  max-width: 72rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

.bb-panel .bb-updates-section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--bb-space-3);
  margin-bottom: var(--bb-space-4);
  padding-bottom: var(--bb-space-3);
  border-bottom: var(--bb-border-width) dashed var(--bb-border-color);
}

.bb-panel .bb-updates-section-head h2 {
  margin: 0 0 var(--bb-space-1);
  font-size: var(--bb-h5);
  color: var(--bb-heading-color);
}

.bb-panel .bb-updates-section-head p {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
}

.bb-panel .bb-updates-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--bb-space-4);
}

.bb-panel .bb-update-card {
  min-width: 0;
}

.bb-panel .bb-update-visual {
  position: relative;
  display: grid;
  place-items: center;
  aspect-ratio: 16/7;
  overflow: hidden;
  border-radius: var(--bb-radius);
  background: color-mix(in srgb, var(--bb-success-light) 72%, var(--bb-surface-muted));
}

.bb-panel .bb-update-visual::before,
.bb-panel .bb-update-visual::after {
  content: "";
  position: absolute;
  border-radius: var(--bb-radius-pill);
  background: color-mix(in srgb, var(--bb-success) 12%, transparent);
}

.bb-panel .bb-update-visual::before {
  width: 38%;
  aspect-ratio: 1;
  inset-inline-start: -8%;
  inset-block-end: -24%;
}

.bb-panel .bb-update-visual::after {
  width: 34%;
  aspect-ratio: 1;
  inset-inline-end: 8%;
  inset-block-start: -18%;
}

.bb-panel .bb-update-visual .material-symbols-outlined {
  position: relative;
  z-index: 1;
  font-size: clamp(2.25rem, 4vw, 4rem);
  color: var(--bb-success);
}

.bb-panel .bb-update-card[data-kind=iyileştirme] .bb-update-visual {
  background: color-mix(in srgb, var(--bb-info-light) 76%, var(--bb-surface-muted));
}

.bb-panel .bb-update-card[data-kind=iyileştirme] .bb-update-visual::before,
.bb-panel .bb-update-card[data-kind=iyileştirme] .bb-update-visual::after {
  background: color-mix(in srgb, var(--bb-info) 10%, transparent);
}

.bb-panel .bb-update-card[data-kind=iyileştirme] .bb-update-visual .material-symbols-outlined {
  color: var(--bb-info);
}

.bb-panel .bb-update-card[data-kind=düzeltme] .bb-update-visual {
  background: color-mix(in srgb, var(--bb-warning-light) 80%, var(--bb-surface-muted));
}

.bb-panel .bb-update-card[data-kind=düzeltme] .bb-update-visual::before,
.bb-panel .bb-update-card[data-kind=düzeltme] .bb-update-visual::after {
  background: color-mix(in srgb, var(--bb-warning) 12%, transparent);
}

.bb-panel .bb-update-card[data-kind=düzeltme] .bb-update-visual .material-symbols-outlined {
  color: var(--bb-warning);
}

.bb-panel .bb-update-card-body {
  position: relative;
  padding: var(--bb-space-3) 0 0;
}

.bb-panel .bb-update-badge {
  display: inline-flex;
  align-items: center;
  min-height: 1.35rem;
  margin-bottom: var(--bb-space-2);
  padding: 0 var(--bb-space-2);
  border-radius: var(--bb-radius-sm);
  background: var(--bb-success-light);
  color: var(--bb-success-text);
  font-size: var(--bb-fs-2xs);
  font-weight: var(--bb-fw-semibold);
}

.bb-panel .bb-update-card[data-kind=iyileştirme] .bb-update-badge {
  background: var(--bb-info-light);
  color: var(--bb-info-text);
}

.bb-panel .bb-update-card[data-kind=düzeltme] .bb-update-badge {
  background: var(--bb-warning-light);
  color: var(--bb-warning-text);
}

.bb-panel .bb-update-card h3 {
  margin: 0 0 var(--bb-space-2);
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-base);
  line-height: var(--bb-line-height-heading);
}

.bb-panel .bb-update-card p {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

@media (max-width: 1199.98px) {
  .bb-panel .bb-updates-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .bb-panel .bb-updates-page {
    padding: var(--bb-space-3);
  }
  .bb-panel .bb-updates-grid {
    grid-template-columns: 1fr;
  }
}
/* Subscription details — GlobalTheme card, form, table and semantic tokens. */
.bb-panel .bb-subscription-layout {
  display: grid;
  grid-template-columns: minmax(0, 2.25fr) minmax(17rem, 1fr);
  align-items: start;
  gap: var(--bb-panel-content-gap);
}

.bb-panel .bb-subscription-main {
  display: grid;
  gap: var(--bb-panel-content-gap);
  min-width: 0;
}

.bb-panel .bb-subscription-summary {
  position: sticky;
  top: var(--bb-space-4);
  min-width: 0;
}

.bb-panel .bb-subscription-card .bb-card-body {
  padding: var(--bb-space-4);
}

.bb-panel .bb-subscription-customer {
  display: flex;
  align-items: center;
  gap: var(--bb-space-3);
  margin-block: var(--bb-space-3);
}

.bb-panel .bb-subscription-customer .bb-symbol {
  flex: none;
}

.bb-panel .bb-subscription-customer strong, .bb-panel .bb-subscription-method strong {
  display: block;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-sm);
}

.bb-panel .bb-subscription-customer small, .bb-panel .bb-subscription-method small {
  display: block;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
}

.bb-panel .bb-subscription-notice {
  border: var(--bb-border-width, 1px) dashed var(--bb-primary);
  border-radius: var(--bb-radius);
  background: var(--bb-tertiary-bg);
  padding: var(--bb-space-4);
  font-size: var(--bb-fs-sm);
}

.bb-panel .bb-subscription-notice p {
  color: var(--bb-secondary-color);
  margin: var(--bb-space-1) 0 0;
}

.bb-panel .bb-subscription-table-wrap {
  overflow-x: auto;
}

.bb-panel .bb-subscription-table {
  width: 100%;
  font-size: var(--bb-fs-sm);
}

.bb-panel .bb-subscription-table th {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-medium);
  white-space: nowrap;
}

.bb-panel .bb-subscription-table th, .bb-panel .bb-subscription-table td {
  padding: var(--bb-space-3);
  vertical-align: middle;
  border-bottom: var(--bb-border-width, 1px) solid var(--bb-border-color);
}

.bb-panel .bb-subscription-table tr:last-child td {
  border-bottom: 0;
}

.bb-panel .bb-subscription-table button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  background: transparent;
  border-radius: var(--bb-radius);
  color: var(--bb-secondary-color);
  padding: var(--bb-space-2);
}

.bb-panel .bb-subscription-table button:hover {
  color: var(--bb-danger-text);
  background: var(--bb-tertiary-bg);
}

.bb-panel .bb-subscription-method {
  display: flex;
  align-items: center;
  gap: var(--bb-space-3);
  padding: var(--bb-space-3) 0;
  border-bottom: var(--bb-border-width, 1px) dashed var(--bb-border-color);
}

.bb-panel .bb-subscription-method:last-child {
  border-bottom: 0;
}

.bb-panel .bb-subscription-method input {
  flex: none;
}

.bb-panel .bb-subscription-method-info {
  flex: 1;
  min-width: 0;
}

.bb-panel .bb-subscription-method .material-symbols-outlined {
  color: var(--bb-primary-text);
  font-size: var(--bb-fs-lg);
}

.bb-panel .bb-subscription-payment-detail {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--bb-space-3);
  padding: var(--bb-space-3) 0 var(--bb-space-4);
  font-size: var(--bb-fs-xs);
}

.bb-panel .bb-subscription-payment-detail dt {
  color: var(--bb-secondary-color);
}

.bb-panel .bb-subscription-payment-detail dd {
  margin: 0;
  overflow-wrap: anywhere;
}

.bb-panel .bb-subscription-payment-detail[hidden] {
  display: none;
}

.bb-panel .bb-subscription-custom-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) auto;
  gap: var(--bb-space-2);
  margin-bottom: var(--bb-space-2);
  align-items: center;
}

.bb-panel .bb-subscription-option {
  padding: var(--bb-space-4);
  border: var(--bb-border-width, 1px) dashed var(--bb-border-color);
  border-radius: var(--bb-radius);
}

.bb-panel .bb-subscription-option .form-check-label {
  font-size: var(--bb-fs-sm);
