.bb-btn.bb-btn-lg {
  --bb-btn-padding-x: 1.25rem;
  --bb-btn-padding-y: 0.8125rem;
  --bb-btn-font-size: var(--bb-fs-base);
}

.btn .material-symbols-outlined,
.bb-btn .material-symbols-outlined,
.btn .svg-icon,
.bb-btn .svg-icon,
.btn i,
.bb-btn i {
  display: inline-flex;
