  --bb-status-color: var(--bb-status-good);
}

.bb-status-away,
.bb-status-warning {
  --bb-status-color: var(--bb-status-warning);
}

.bb-status-serious {
  --bb-status-color: var(--bb-status-serious);
}

.bb-status-busy,
.bb-status-critical {
  --bb-status-color: var(--bb-status-critical);
}

.bb-status-offline {
  --bb-status-color: var(--bb-status-neutral);
