.bb-status-history-hero-wrap {
  background-color: var(--bb-body-bg);
  padding: 30px 0 0;
}

.bb-status-history-hero {
  position: relative;
  overflow: hidden;
  min-height: 254px;
  padding: 34px 36px;
  color: var(--bb-white);
  background: radial-gradient(circle at 96% 0%, rgba(var(--bb-warning-rgb), 0.2), transparent 27%), radial-gradient(circle at 0% 100%, rgba(var(--bb-success-rgb), 0.12), transparent 30%), linear-gradient(135deg, var(--bb-navy-800) 0%, var(--bb-navy-700) 56%, var(--bb-navy-700) 100%);
  border: 1px solid color-mix(in srgb, var(--bb-white) 10%, transparent);
  border-radius: var(--bb-status-card-radius);
  box-shadow: var(--bb-shadow-lg);
}

.bb-status-history-hero::before {
  content: "";
  position: absolute;
  right: -120px;
  top: -160px;
  width: 360px;
  height: 360px;
  border-radius: 50%;
  background: rgba(var(--bb-warning-rgb), 0.12);
  pointer-events: none;
}

.bb-status-history-hero::after {
  content: "";
  position: absolute;
  left: -90px;
  bottom: -120px;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: rgba(var(--bb-success-rgb), 0.08);
  pointer-events: none;
}

.bb-status-history-hero-content {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(420px, 0.85fr);
  gap: 34px;
  align-items: center;
}

