  border-color: color-mix(in srgb, var(--bb-white) 14%, transparent);
}

.bb-status-component-summary-title {
  margin: 0 0 18px;
  color: var(--bb-white);
  font-size: var(--bb-fs-lg);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-summary-row {
  display: flex;
  justify-content: space-between;
  gap: 1.125rem;
  padding: 0.8125rem 0;
  border-top: 1px solid color-mix(in srgb, var(--bb-white) 12%, transparent);
  color: color-mix(in srgb, var(--bb-white) 72%, transparent);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-summary-row strong {
  color: var(--bb-white);
  font-weight: var(--bb-fw-medium);
  text-align: right;
}

.bb-status-component-main {
  padding: 18px 0 28px;
  margin-top: 30px;
}

.bb-status-component-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 16px;
  align-items: start;
}

.bb-status-component-stack {
  min-width: 0;
  display: grid;
  gap: 1.125rem;
}

.bb-status-component-side {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.bb-status-component-card-header {
  padding: 22px 24px 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.bb-status-component-section-label {
  --bb-chip-bg: var(--bb-success-light);
  --bb-chip-color: var(--bb-success-text);
  --bb-chip-border-color: transparent;
  --bb-chip-padding-x: .65rem;
  --bb-chip-padding-y: 0.25rem;
  --bb-chip-font-size: var(--bb-fs-xs);
  --bb-chip-font-weight: var(--bb-fw-semibold);
  --bb-chip-min-height: 26px;
  width: fit-content;
  margin-bottom: 0.625rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.bb-status-component-section-label .material-symbols-outlined {
  font-size: var(--bb-fs-sm);
}

.bb-status-component-card-title {
  margin: 0;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-lg);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-medium);
  letter-spacing: -0.015em;
}

.bb-status-component-card-text {
  margin: 8px 0 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-health-card {
  padding: 22px 24px 24px;
}

.bb-status-component-health-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-top: 18px;
}

.bb-status-component-health-item {
  padding: 16px;
  background-color: var(--bb-tertiary-bg);
  border: var(--bb-status-panel-border);
  border-radius: var(--bb-status-panel-radius);
}

.bb-status-component-health-label {
  display: block;
  margin-bottom: 6px;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-semibold);
}

.bb-status-component-health-value {
  display: block;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-lg);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-health-note {
  display: grid;
  gap: 10px;
  margin-top: 0.875rem;
}

.bb-status-component-health-note-item {
  padding: 14px 16px;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  background-color: var(--bb-body-bg);
  border: var(--bb-status-panel-border);
  border-radius: var(--bb-status-panel-radius);
}

.bb-status-component-health-note-item > .material-symbols-outlined {
  width: 34px;
  height: 34px;
  border-radius: var(--bb-status-card-inner-radius);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  color: var(--bb-success);
  background-color: var(--bb-success-light);
  font-size: var(--bb-fs-lg);
}

.bb-status-component-health-note-item strong {
  display: block;
  margin-bottom: 4px;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-semibold);
}

.bb-status-component-health-note-item span {
  display: block;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-table-line-height);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-metric-grid {
  padding: 15px 24px 24px;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.bb-status-component-metric {
  background-color: var(--bb-tertiary-bg);
  padding: 16px;
}

.bb-status-component-metric-label {
  display: block;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-semibold);
  margin-bottom: 5px;
}

.bb-status-component-metric-value {
  display: block;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-lg);
  font-weight: var(--bb-fw-medium);
  letter-spacing: -0.02em;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.bb-status-component-side-card {
  padding: 20px;
}

.bb-status-component-side-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.bb-status-component-side-title {
  margin: 0;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-lg);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-side-icon {
  width: 38px;
  height: 38px;
  border-radius: var(--bb-status-card-inner-radius);
  background-color: var(--bb-warning-light);
  color: var(--bb-heading-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.bb-status-component-side-icon .material-symbols-outlined {
  font-size: var(--bb-fs-sm);
}

.bb-status-component-side-list {
  display: grid;
  gap: 10px;
}

.bb-status-component-side-item {
  display: block;
  background-color: var(--bb-tertiary-bg);
  padding: 0.8125rem;
  color: inherit;
  text-decoration: none;
  transition: border-color var(--bb-transition-fast), box-shadow var(--bb-transition-fast), transform var(--bb-transition-fast);
}

.bb-status-component-side-item:hover {
  border-color: var(--bb-border-color-strong);
  box-shadow: var(--bb-shadow-xs);
  transform: translateY(-1px);
  color: inherit;
  text-decoration: none;
}

.bb-status-component-side-item-title {
  margin: 0 0 6px;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

.bb-status-component-side-item-text {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-table-line-height);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-side-item-meta {
  margin-top: 8px;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-side-empty {
  background-color: var(--bb-tertiary-bg);
  padding: 14px;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-medium);
}

.bb-status-component-side-empty strong,
.bb-status-component-side-empty code {
  color: var(--bb-heading-color);
}

@media (max-width: 1199.98px) {
  .bb-status-component-layout {
    grid-template-columns: minmax(0, 1fr);
  }
}
@media (max-width: 1100px) {
  .bb-status-component-hero-content {
    grid-template-columns: 1fr;
  }
  .bb-status-component-health-grid,
  .bb-status-component-metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .bb-status-component-hero-wrap {
    padding-top: 20px;
  }
  .bb-status-component-hero {
    min-height: unset;
    padding: 24px 20px;
  }
  .bb-status-component-text {
    font-size: var(--bb-fs-sm);
  }
  .bb-status-component-health-card {
    padding: 18px;
  }
  .bb-status-component-health-grid,
  .bb-status-component-metric-grid {
    grid-template-columns: 1fr;
  }
  .bb-status-component-metric-grid {
    padding: 0 18px 18px;
  }
}
/* Status overrides (sayfalar arası son düzeltmeler, sayfalama, dil menüsü, tema anahtarı) — Bulbulustur.Service.Status.API status.css (18.11.2026) ile aynı içerik; artık yalnız buradan yönetilir. */
.bb-status-bar.nodata {
  background: var(--bb-gray-300);
}

.bb-status-bar-tooltip-state.nodata {
  background: var(--bb-gray-100);
  color: var(--bb-gray-600);
}

.bb-status-bar-tooltip-note.nodata {
  color: var(--bb-gray-600);
}

.bb-status-legend-item.nodata .bb-status-dot {
  background: var(--bb-gray-300);
}

/* ---- Empty state / timeline title / history date ---- */
.bb-status-empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 2.5rem 1rem;
  text-align: center;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  background-color: var(--bb-surface-soft);
  border: 1px dashed var(--bb-border-dashed-color);
  border-radius: var(--bb-status-card-inner-radius);
}

.bb-status-timeline-title {
  margin: 0;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-base);
  font-weight: var(--bb-fw-semibold);
  line-height: 1.35;
}

.bb-status-history-container {
  display: flex;
  flex-direction: column;
  gap: var(--bb-status-section-gap);
}

.bb-status-history-date {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-medium);
  line-height: 1.5;
  white-space: nowrap;
}

/* ---- Pagination ---- */
.bb-status-pagination-wrap {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-top: var(--bb-status-section-gap);
}

.bb-status-page-notify {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
}

.bb-status-pagination {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.bb-status-pagination-link,
.bb-status-pagination-arrow {
  min-width: 2.25rem;
  height: 2.25rem;
  padding: 0 0.625rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-body-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-medium);
  text-decoration: none;
  background-color: var(--bb-surface-bg);
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius);
}

.bb-status-pagination-link:hover,
.bb-status-pagination-arrow:hover {
  background-color: var(--bb-tertiary-bg);
  color: var(--bb-emphasis-color);
}

.bb-status-pagination-link.active {
  color: var(--bb-brand-yellow-inverse);
  background-color: var(--bb-brand-yellow);
  border-color: var(--bb-brand-yellow);
}

/* ---- Language menu (footer) ---- */
.bb-lang {
  position: relative;
}

.bb-lang > summary {
  list-style: none;
}

.bb-lang > summary::-webkit-details-marker {
  display: none;
}

.bb-lang-toggle {
  height: 2.25rem;
  padding: 0 0.75rem;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius);
  background-color: transparent;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-medium);
  cursor: pointer;
}

.bb-lang-toggle:hover,
.bb-lang[open] > .bb-lang-toggle {
  color: var(--bb-emphasis-color);
  background-color: var(--bb-tertiary-bg);
}

.bb-lang-flag {
  width: 1.25rem;
  height: 0.9375rem;
  object-fit: cover;
  border-radius: var(--bb-radius);
  box-shadow: var(--bb-shadow-xs);
  flex: 0 0 auto;
}

.bb-lang-menu {
  position: absolute;
  top: calc(100% + 0.375rem);
  right: 0;
  z-index: 1000;
  min-width: 11rem;
  max-height: none;
  overflow: visible;
  padding: 0.375rem;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius);
  background-color: var(--bb-surface-elevated);
  box-shadow: var(--bb-shadow);
}

.bb-lang-up .bb-lang-menu {
  top: auto;
  bottom: calc(100% + 0.375rem);
}

.bb-lang-menu a {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.5rem 0.625rem;
  border-radius: var(--bb-radius);
  color: var(--bb-body-color);
  font-size: var(--bb-fs-xs);
  text-decoration: none;
}

.bb-lang-menu a:hover {
  background-color: var(--bb-tertiary-bg);
}

.bb-lang-menu a.is-active {
  color: var(--bb-emphasis-color);
  font-weight: var(--bb-fw-semibold);
}

.bb-status-footer-links .bb-lang-menu a:first-child {
  color: var(--bb-body-color);
  font-weight: var(--bb-fw-normal);
}

.bb-status-footer-links .bb-lang-menu a.is-active {
  font-weight: var(--bb-fw-semibold);
}

/* ---- Theme switch (footer) ---- */
.bb-status-theme {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.1875rem;
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-surface-soft);
}

.bb-status-theme-choice {
  width: 2rem;
  height: 2rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  color: var(--bb-secondary-color);
  background-color: transparent;
  border: 0;
  border-radius: var(--bb-radius-pill);
  cursor: pointer;
}

.bb-status-theme-choice .material-symbols-outlined {
  font-size: var(--bb-fs-base);
}

.bb-status-theme-choice:hover {
  color: var(--bb-emphasis-color);
}

.bb-status-theme-choice.is-active {
  color: var(--bb-brand-yellow-inverse);
  background-color: var(--bb-brand-yellow);
}

.bb-status-footer-links .bb-lang-menu a::before,
.bb-status-footer-links .bb-lang-menu a::after,
.bb-lang-menu a::before,
.bb-lang-menu a::after {
  content: none;
  display: none;
}

.bb-lang-menu a,
.bb-status-footer-links .bb-lang-menu a {
  width: 100%;
  margin: 0;
  justify-content: flex-start;
  text-align: left;
  white-space: nowrap;
}

.bb-lang-menu a.is-active {
  background-color: var(--bb-tertiary-bg);
}

.bb-lang-menu .bb-lang-flag {
  order: 0;
}

