/* Bulbulustur Pages*/
/* =====================================
   Web Project Scope
   Main CSS tokenlarını web projesi içinde kullanır.
   Electro renk ritmini sadece bu proje scope'u içinde bb token sistemine bağlar.
===================================== */
/* =====================================
   Web Project Scope
   Main CSS tokenlarını web projesi içinde kullanır.
   Core theme token override etmez.
===================================== */
.bb-web-page {
  /* =====================================
     Web Project Legacy Aliases
     Eski Electro renk sözlüğü.
     Sadece eski web componentleri için alias olarak kalır.
     Core --bb-* theme tokenlarını ezmez.
  ===================================== */
  --bb-web-blue: var(--bb-blue-700);
  --bb-web-indigo: #2d1582;
  --bb-web-purple: var(--bb-purple-500);
  --bb-web-pink: var(--bb-pink-500);
  --bb-web-red: var(--bb-red-500);
  --bb-web-orange: var(--bb-orange-500);
  --bb-web-yellow: var(--bb-primary);
  --bb-web-green: var(--bb-green-500);
  --bb-web-teal: var(--bb-turquoise-500);
  --bb-web-cyan: var(--bb-turquoise-500);
  --bb-web-white: var(--bb-white);
  --bb-web-black: var(--bb-black);
  --bb-web-gray: var(--bb-secondary-color);
  --bb-web-gray-dark: var(--bb-emphasis-color);
  --bb-web-primary: var(--bb-primary);
  --bb-web-primary-2: var(--bb-link-color);
  --bb-web-secondary: var(--bb-secondary-color);
  --bb-web-success: var(--bb-success);
  --bb-web-info: var(--bb-info);
  --bb-web-warning: var(--bb-warning);
  --bb-web-danger: var(--bb-danger);
  --bb-web-light: var(--bb-surface-soft);
  --bb-web-dark: var(--bb-emphasis-color);
  --bb-web-sale: var(--bb-danger);
  /* =====================================
     Web Project Semantic Helpers
  ===================================== */
  --bb-web-link-color: var(--bb-link-color);
  --bb-web-link-hover-color: var(--bb-link-hover-color);
  --bb-web-heading-color: var(--bb-heading-color);
  --bb-web-body-color: var(--bb-body-color);
  --bb-web-muted-color: var(--bb-secondary-color);
  /* =====================================
     Web Project Layout Tokens
  ===================================== */
  --bb-web-section-y: 4rem;
  --bb-web-section-y-sm: 3rem;
  /* Semantic rhythm: Core spacing/typography is the source, Web names the role. */
  --bb-web-section-gap: 3rem;
  --bb-web-section-gap-tight: 2rem;
  --bb-web-section-gap-tablet: 2.5rem;
  --bb-web-section-gap-mobile: 2rem;
  --bb-web-section-gap-last: 4rem;
  --bb-web-stage-padding: var(--bb-space-6);
  --bb-web-stage-padding-tablet: var(--bb-space-5);
  --bb-web-stage-padding-mobile: var(--bb-space-4);
  --bb-web-section-head-gap: var(--bb-space-5);
  --bb-web-section-head-margin: var(--bb-space-6);
  --bb-web-content-gap: var(--bb-space-4);
  --bb-web-meta-gap: var(--bb-space-2);
  --bb-web-page-title-size: clamp(var(--bb-fs-display-sm), 3.6vw, var(--bb-fs-display-lg));
  --bb-web-section-title-size: clamp(var(--bb-fs-2xl), 2.8vw, var(--bb-fs-display-md));
  --bb-web-subsection-title-size: clamp(var(--bb-fs-xl), 2.2vw, var(--bb-fs-display-sm));
  --bb-web-lead-size: var(--bb-page-lead-font-size);
  --bb-web-body-size: var(--bb-page-text-font-size);
  --bb-web-meta-size: var(--bb-fs-sm);
  --bb-web-kicker-size: var(--bb-fs-xs);
  --bb-web-control-size: var(--bb-ui-font-size);
  --bb-web-page-title-weight: var(--bb-fw-display);
  --bb-web-section-title-weight: var(--bb-fw-title-strong);
  --bb-web-subsection-title-weight: var(--bb-fw-title-strong);
  --bb-web-page-title-line-height: var(--bb-line-height-display);
  --bb-web-section-title-line-height: var(--bb-line-height-heading);
  --bb-web-page-title-letter-spacing: var(--bb-display-letter-spacing);
  --bb-web-section-title-letter-spacing: var(--bb-heading-letter-spacing);
  --bb-web-kicker-letter-spacing: 0.08em;
  --bb-web-card-bg: var(--bb-surface-elevated);
  --bb-web-card-border-color: var(--bb-border-color);
  --bb-web-card-border: var(--bb-border-width) solid var(--bb-web-card-border-color);
  --bb-web-card-radius: var(--bb-radius-2xl);
  --bb-web-card-inner-radius: var(--bb-radius-lg);
  --bb-web-card-shadow: var(--bb-shadow-xs);
  --bb-web-card-padding: var(--bb-space-6);
  --bb-web-panel-bg: var(--bb-surface-elevated);
  --bb-web-panel-border: var(--bb-border-width) solid var(--bb-border-color);
  --bb-web-panel-radius: var(--bb-radius-lg);
  --bb-web-section-soft-bg: var(--bb-surface-soft);
  --bb-web-section-muted-bg: var(--bb-surface-muted);
  min-height: 100vh;
  background-color: var(--bb-body-bg);
  color: var(--bb-body-color);
}

