  flex-wrap: wrap;
  gap: 0.625rem;
  margin-top: 1rem;
}

.bb-hero-dark .bb-hero-card {
  background-color: color-mix(in srgb, var(--bb-surface-elevated) 10%, transparent);
  border-color: color-mix(in srgb, var(--bb-white) 14%, transparent);
