  color: color-mix(in srgb, var(--bb-primary) 46%, var(--bb-dark));
  background-color: color-mix(in srgb, var(--bb-primary) 13%, var(--bb-surface-elevated));
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-2xs);
