  font-size: var(--bb-fs-md);
  font-weight: var(--bb-fw-bold);
}

.bb-error-visual-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: calc(var(--bb-space-1) * 14);
  height: calc(var(--bb-space-1) * 14);
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-primary-light);
  color: var(--bb-primary);
}

/* Öneri kartları */
.bb-error-suggestion-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
  gap: var(--bb-space-4);
}

.bb-error-suggestion-card {
  display: flex;
  flex-direction: column;
  gap: var(--bb-space-2);
  padding: var(--bb-space-5);
