  width: 2.625rem;
  height: 42px;
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-blog-accent-soft);
  color: var(--bb-heading-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}

.bb-blog-search-icon .material-symbols-outlined {
  font-size: var(--bb-fs-xl);
}

.bb-blog-search-input,
.bb-blog-subscribe-card-input {
  width: 100%;
  border: 0;
  outline: none;
  color: var(--bb-body-color);
  font-size: var(--bb-fs-sm);
  background-color: transparent;
  min-width: 0;
}

.bb-blog-search-input {
  height: 42px;
}

.bb-blog-search-button,
.bb-blog-subscribe-card-button {
  border: 0;
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-blog-dark-surface);
  color: var(--bb-white);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-blog-search-button {
  min-width: 116px;
  height: 42px;
  padding: 0 18px;
}

.bb-blog-search-button:hover,
.bb-blog-subscribe-card-button:hover {
  background-color: var(--bb-emphasis-color);
}

/* =====================================
   Featured
===================================== */
.bb-blog-featured-card {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(320px, 1.18fr);
  gap: 22px;
  align-items: stretch;
  min-height: 380px;
  padding: var(--bb-web-card-padding);
  border-radius: var(--bb-radius-2xl);
  background-color: color-mix(in srgb, var(--bb-body-bg) 88%, transparent);
  border: 1px solid color-mix(in srgb, var(--bb-border-color) 92%, transparent);
  box-shadow: var(--bb-shadow-lg);
  backdrop-filter: blur(0.625rem);
  -webkit-backdrop-filter: blur(0.625rem);
  overflow: hidden;
}

.bb-blog-featured-copy {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  padding: 10px 6px 10px 8px;
}

.bb-blog-featured-label {
  gap: 0.4375rem;
  min-height: 1.75rem;
  padding: 0 0.625rem;
  margin-bottom: 14px;
  background-color: var(--bb-blog-accent-soft);
  color: var(--bb-blog-accent-text);
  font-size: var(--bb-fs-xs);
}

.bb-blog-featured-label .material-symbols-outlined {
  font-size: var(--bb-fs-sm);
}

.bb-blog-featured-title {
  display: -webkit-box;
  -webkit-line-clamp: 4;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin: 0 0 14px;
  color: var(--bb-heading-color);
  font-size: var(--bb-web-section-title-size);
  line-height: var(--bb-line-height-heading);
  letter-spacing: -0.035em;
  font-weight: var(--bb-fw-bold);
}

.bb-blog-featured-text {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  margin: 0 0 22px;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-loose);
}

.bb-blog-featured-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  margin-bottom: 20px;
}

.bb-blog-featured-cta,
.bb-blog-read-more,
.bb-blog-view-all {
  display: inline-flex;
  align-items: center;
  text-decoration: none !important;
  font-weight: var(--bb-fw-bold);
}

.bb-blog-featured-cta {
  justify-content: center;
  gap: 0.5rem;
  width: fit-content;
  min-height: 44px;
  padding: 0 18px;
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-blog-dark-surface);
  color: var(--bb-white) !important;
  font-size: var(--bb-fs-sm);
}

.bb-blog-featured-cta:hover {
  background-color: var(--bb-emphasis-color);
}

.bb-blog-featured-cta .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
}

.bb-blog-featured-media {
  position: relative;
  min-height: 336px;
  border-radius: var(--bb-radius-xl);
  overflow: hidden;
  background-color: var(--bb-tertiary-bg);
}

.bb-blog-featured-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform: scale(1.01);
}

.bb-blog-featured-media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 55%, color-mix(in srgb, var(--bb-coal-300) 18%, transparent) 100%);
  pointer-events: none;
}

.bb-blog-featured-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 340px;
  border-radius: var(--bb-radius-2xl);
  background-color: var(--bb-body-bg);
  border: 1px dashed var(--bb-blog-card-border-strong);
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

/* =====================================
   Categories / Main
===================================== */
.bb-blog-category-card {
  padding: 14px 16px 16px;
  border-radius: var(--bb-radius-2xl);
  background-color: color-mix(in srgb, var(--bb-body-bg) 94%, transparent);
  border: 1px solid color-mix(in srgb, var(--bb-border-color) 92%, transparent);
  box-shadow: var(--bb-shadow-xs);
}

.bb-blog-category-row {
  display: block;
}

.bb-blog-section-head,
.bb-blog-special-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--bb-web-section-head-gap);
  margin-bottom: 24px;
}

.bb-blog-section-kicker {
  gap: 0.4375rem;
  min-height: 1.75rem;
  padding: 0 0.625rem;
  margin-bottom: 0.625rem;
  background-color: var(--bb-blog-accent-soft);
  color: var(--bb-blog-accent-text);
  font-size: var(--bb-fs-xs);
}

.bb-blog-section-kicker .material-symbols-outlined,
.bb-blog-special-kicker .material-symbols-outlined {
  font-size: var(--bb-fs-sm);
}

.bb-blog-section-title {
  margin: 0;
  color: var(--bb-heading-color);
  font-size: var(--bb-web-section-title-size);
  line-height: var(--bb-line-height-tight);
  letter-spacing: -0.035em;
  font-weight: var(--bb-fw-bold);
}

.bb-blog-section-text {
  max-width: 720px;
  margin: 8px 0 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-loose);
}

.bb-blog-view-all {
  gap: 6px;
  color: var(--bb-heading-color) !important;
  font-size: var(--bb-fs-sm);
  white-space: nowrap;
}

.bb-blog-view-all:hover,
.bb-blog-read-more:hover {
  color: var(--bb-link-color) !important;
}

.bb-blog-view-all .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
}

/* =====================================
   Blog Cards Compatibility
===================================== */
.bb-blog-grid,
.bb-blog-special-grid,
.bb-blog-hub-grid {
  display: grid;
}

.bb-blog-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 30px;
}

.bb-blog-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 428px;
  border-radius: var(--bb-radius-2xl);
  background-color: var(--bb-body-bg);
  border: 1px solid var(--bb-blog-card-border);
  box-shadow: var(--bb-shadow-xs);
  overflow: hidden;
  transition: transform var(--bb-transition-normal), box-shadow var(--bb-transition-normal), border-color var(--bb-transition-normal);
}

.bb-blog-card:hover {
  transform: translateY(-4px);
  border-color: var(--bb-blog-card-border-strong);
  box-shadow: var(--bb-shadow-sm);
}

.bb-blog-card-media {
  position: relative;
  height: 210px;
  background-color: var(--bb-tertiary-bg);
  overflow: hidden;
}

.bb-blog-card-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform var(--bb-transition-normal);
}

.bb-blog-card:hover .bb-blog-card-media img {
  transform: scale(1.035);
}

.bb-blog-card-badge {
  position: absolute;
  left: 14px;
  top: 14px;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 1.75rem;
  padding: 0 0.625rem;
  border-radius: var(--bb-radius-pill);
  background-color: color-mix(in srgb, var(--bb-body-bg) 74%, transparent);
  color: var(--bb-heading-color);
  border: 1px solid color-mix(in srgb, var(--bb-body-bg) 62%, transparent);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
  backdrop-filter: blur(0.625rem);
  -webkit-backdrop-filter: blur(0.625rem);
}

.bb-blog-card-badge .material-symbols-outlined {
  font-size: var(--bb-fs-sm);
  color: var(--bb-blog-accent-hover);
}

.bb-blog-card-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 18px;
}

.bb-blog-card-meta {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
  margin-bottom: 0.625rem;
}

.bb-blog-card-title {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  min-height: 58px;
  max-height: 58px;
  overflow: hidden;
  margin: 0 0 10px;
  color: var(--bb-heading-color);
  font-size: var(--bb-h4);
  line-height: 1.38;
  letter-spacing: -0.02em;
  font-weight: var(--bb-fw-bold);
}

.bb-blog-card-link {
  color: inherit !important;
  text-decoration: none !important;
}

.bb-blog-card-link:hover .bb-blog-card-title {
  color: var(--bb-link-color);
}

.bb-blog-card-text {
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  min-height: 74px;
  max-height: 74px;
  overflow: hidden;
  margin: 0 0 16px;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

.bb-blog-card-footer {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid var(--bb-border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.bb-blog-read-more {
  gap: 6px;
  color: var(--bb-heading-color) !important;
  font-size: var(--bb-fs-sm);
}

.bb-blog-read-more .material-symbols-outlined {
  font-size: var(--bb-fs-md);
}

.bb-blog-mini-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--bb-blog-accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--bb-blog-accent) 16%, transparent);
  flex: 0 0 auto;
}

/* =====================================
   Special Shelf
===================================== */
.bb-blog-special-section {
  --bb-blog-special-accent: var(--bb-blog-accent, var(--bb-primary));
  --bb-blog-special-dark-bg: var(--bb-coal-300, var(--bb-emphasis-color));
  --bb-blog-special-on-dark: var(--bb-theme-on-dark, var(--bb-white));
  --bb-blog-special-card-bg: var(--bb-surface-elevated, var(--bb-body-bg));
  --bb-blog-special-card-border: color-mix(in srgb, var(--bb-border-color) 84%, transparent);
  --bb-blog-special-card-title-color: var(--bb-heading-color, var(--bb-emphasis-color));
  --bb-blog-special-card-text-color: var(--bb-secondary-color);
  --bb-blog-special-label-bg: color-mix(in srgb, var(--bb-blog-special-accent) 18%, var(--bb-body-bg));
  --bb-blog-special-label-border: color-mix(in srgb, var(--bb-blog-special-accent) 32%, var(--bb-border-color));
  --bb-blog-special-label-color: var(
      --bb-blog-accent-text,
      color-mix(in srgb, var(--bb-blog-special-accent) 76%, var(--bb-emphasis-color))
  );
  --bb-blog-special-bg:
      radial-gradient(circle at 90% 12%, color-mix(in srgb, var(--bb-blog-special-accent) 20%, transparent) 0, transparent 30%),
      linear-gradient(135deg, var(--bb-blog-special-dark-bg) 0%, color-mix(in srgb, var(--bb-blog-special-dark-bg) 86%, var(--bb-info, var(--bb-primary))) 100%);
  --bb-blog-special-kicker-bg: color-mix(in srgb, var(--bb-blog-special-on-dark) 12%, transparent);
  --bb-blog-special-kicker-color: color-mix(in srgb, var(--bb-blog-special-accent) 36%, var(--bb-blog-special-on-dark));
  --bb-blog-special-text-color: color-mix(in srgb, var(--bb-blog-special-on-dark) 72%, transparent);
  position: relative;
  overflow: hidden;
  margin: 46px 0;
  padding: 30px;
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-blog-special-on-dark) 10%, transparent);
  border-radius: var(--bb-radius-2xl);
  background: var(--bb-blog-special-bg);
  color: var(--bb-blog-special-on-dark);
  box-shadow: var(--bb-shadow-lg);
}

.bb-blog-special-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--bb-web-section-head-gap);
  margin-bottom: 22px;
}

.bb-blog-special-kicker {
  display: inline-flex;
  align-items: center;
  gap: 0.4375rem;
  width: fit-content;
  min-height: 1.75rem;
  padding: 0 0.625rem;
  margin-bottom: 9px;
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-blog-special-kicker-color);
  color: color-mix(in srgb, var(--bb-blog-special-accent) 36%, var(--bb-blog-special-on-dark));
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
}

.bb-blog-special-kicker .material-symbols-outlined,
.bb-blog-special-kicker .material-icons {
  color: var(--bb-blog-special-accent);
  font-size: var(--bb-icon-size-sm);
  line-height: 1;
}

.bb-blog-special-title {
  margin: 0;
  color: var(--bb-blog-special-on-dark);
  font-size: var(--bb-web-subsection-title-size);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-bold);
  letter-spacing: -0.03em;
}

.bb-blog-special-text {
  max-width: 720px;
  margin: 7px 0 0;
  color: var(--bb-blog-special-text-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

.bb-blog-special-controls {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.bb-blog-special-control {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-blog-special-on-dark) 18%, transparent);
  border-radius: var(--bb-radius-pill);
  background-color: color-mix(in srgb, var(--bb-blog-special-on-dark) 9%, transparent);
  color: var(--bb-blog-special-on-dark);
  transition: transform var(--bb-transition-normal), background-color var(--bb-transition-normal), border-color var(--bb-transition-normal);
}

.bb-blog-special-control:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--bb-blog-special-accent) 40%, transparent);
  background-color: color-mix(in srgb, var(--bb-blog-special-accent) 18%, transparent);
}

.bb-blog-special-control .material-symbols-outlined,
.bb-blog-special-control .material-icons {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-blog-special-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--bb-space-5);
}

.bb-blog-special-card {
  display: flex;
  flex-direction: column;
  min-height: 370px;
  overflow: hidden;
  border: var(--bb-border-width) solid var(--bb-blog-special-card-border);
  border-radius: var(--bb-radius-2xl);
  background-color: var(--bb-blog-special-card-bg);
  color: var(--bb-body-color);
  text-decoration: none !important;
  box-shadow: var(--bb-shadow-xs);
  transition: transform var(--bb-transition-normal), box-shadow var(--bb-transition-normal), border-color var(--bb-transition-normal);
}

.bb-blog-special-card:hover {
  transform: translateY(-4px);
  border-color: color-mix(in srgb, var(--bb-blog-special-accent) 34%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-lg);
}

.bb-blog-special-media {
  height: 180px;
  background-color: var(--bb-tertiary-bg);
}

.bb-blog-special-media img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.bb-blog-special-body {
  padding: 17px;
}

.bb-blog-special-label {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  min-height: 26px;
  padding: 0 9px;
  margin-bottom: 0.625rem;
  border: var(--bb-border-width) solid var(--bb-blog-special-label-border);
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-blog-special-label-bg);
  color: var(--bb-blog-special-label-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
}

.bb-blog-special-card-title {
  display: -webkit-box;
  overflow: hidden;
  min-height: 54px;
  max-height: 54px;
  margin: 0 0 8px;
  color: var(--bb-blog-special-card-title-color);
  font-size: var(--bb-h5);
  line-height: 1.48;
  font-weight: var(--bb-fw-bold);
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.bb-blog-special-card-text {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: var(--bb-blog-special-card-text-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

/* =====================================
   Special Shelf Dark Tokens
===================================== */
[data-bs-theme=dark] .bb-blog-special-section {
  --bb-blog-special-dark-bg: var(--bb-body-bg);
  --bb-blog-special-on-dark: var(--bb-emphasis-color);
  --bb-blog-special-card-bg: var(--bb-surface-elevated, var(--bb-body-bg));
  --bb-blog-special-card-border: color-mix(in srgb, var(--bb-border-color) 86%, transparent);
  --bb-blog-special-bg:
      radial-gradient(circle at 90% 12%, color-mix(in srgb, var(--bb-blog-special-accent) 16%, transparent) 0, transparent 30%),
      linear-gradient(135deg, color-mix(in srgb, var(--bb-body-bg) 94%, var(--bb-blog-special-accent)) 0%, color-mix(in srgb, var(--bb-body-bg) 82%, var(--bb-blog-special-accent)) 100%);
  --bb-blog-special-kicker-bg: color-mix(in srgb, var(--bb-blog-special-accent) 14%, var(--bb-body-bg));
  --bb-blog-special-kicker-color: color-mix(in srgb, var(--bb-blog-special-accent) 84%, var(--bb-emphasis-color));
  --bb-blog-special-text-color: var(--bb-secondary-color);
}

/* =====================================
   Special Shelf Responsive
===================================== */
@media (max-width: 1199.98px) {
  .bb-blog-special-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .bb-blog-special-section {
    margin: 2.25rem 0;
    padding: 20px;
    border-radius: var(--bb-radius-xl);
  }
  .bb-blog-special-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .bb-blog-special-grid {
    grid-template-columns: 1fr;
  }
  .bb-blog-special-card {
    min-height: 0;
  }
  .bb-blog-special-media {
    height: 205px;
  }
}
/* =====================================
   Pagination
===================================== */
.bb-blog-pagination-wrap {
  margin-top: 34px;
  margin-bottom: 48px;
  padding: 14px 16px;
  border-radius: var(--bb-radius-2xl);
  border: 1px solid var(--bb-blog-card-border);
  background-color: var(--bb-body-bg);
  box-shadow: var(--bb-shadow-xs);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--bb-space-5);
}

.bb-blog-page-notify {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--bb-body-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

.bb-blog-page-notify::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--bb-blog-accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--bb-blog-accent) 16%, transparent);
}

.bb-blog-pagination {
  display: flex;
  align-items: center;
  gap: 0.4375rem;
  padding: 0;
  margin: 0;
  list-style: none;
}

.bb-blog-pagination-link,
.bb-blog-pagination-arrow {
  min-width: 38px;
  height: 38px;
  border-radius: var(--bb-radius-lg);
  border: 1px solid var(--bb-border-color);
  background-color: var(--bb-body-bg);
  color: var(--bb-body-color);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  text-decoration: none !important;
}

.bb-blog-pagination-link:hover,
.bb-blog-pagination-arrow:hover {
  background-color: var(--bb-blog-accent-soft);
  border-color: color-mix(in srgb, var(--bb-blog-accent) 32%, var(--bb-border-color));
  color: var(--bb-heading-color) !important;
}

.bb-blog-pagination-link.active {
  background-color: var(--bb-blog-dark-surface);
  border-color: var(--bb-blog-dark-surface);
  color: var(--bb-white) !important;
}

.bb-blog-pagination-arrow .material-symbols-outlined {
  font-size: var(--bb-fs-xl);
}

/* =====================================
   Hub
===================================== */
.bb-blog-hub-section {
  padding: 48px 0 38px;
}

.bb-blog-hub-grid {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.bb-blog-hub-card {
  position: relative;
  min-height: 168px;
  padding: 20px;
  border-radius: var(--bb-radius-2xl);
  border: 1px solid var(--bb-blog-card-border);
  background-color: var(--bb-body-bg);
  box-shadow: var(--bb-shadow-xs);
  overflow: hidden;
  text-decoration: none !important;
  color: inherit !important;
  transition: transform var(--bb-transition-normal), border-color var(--bb-transition-normal), box-shadow var(--bb-transition-normal);
}

.bb-blog-hub-card:hover {
  transform: translateY(-4px);
  border-color: var(--bb-blog-card-border-strong);
  box-shadow: var(--bb-shadow-sm);
}

.bb-blog-hub-card:nth-child(1) {
  background: linear-gradient(135deg, var(--bb-body-bg) 0%, var(--bb-blog-orange-soft) 100%);
}

.bb-blog-hub-card:nth-child(2) {
  background: linear-gradient(135deg, var(--bb-body-bg) 0%, var(--bb-blog-blue-soft) 100%);
}

.bb-blog-hub-card:nth-child(3) {
  background: linear-gradient(135deg, var(--bb-body-bg) 0%, var(--bb-blog-green-soft) 100%);
}

.bb-blog-hub-card:nth-child(4) {
  background: linear-gradient(135deg, var(--bb-body-bg) 0%, var(--bb-blog-purple-soft) 100%);
}

.bb-blog-hub-icon {
  width: 2.625rem;
  height: 42px;
  border-radius: var(--bb-radius-lg);
  background-color: var(--bb-body-bg);
  border: 1px solid var(--bb-border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-blog-dark-surface);
  margin-bottom: 14px;
}

.bb-blog-hub-icon .material-symbols-outlined {
  font-size: var(--bb-fs-xl);
}

.bb-blog-hub-title {
  margin: 0 0 8px;
  color: var(--bb-heading-color);
  font-size: var(--bb-h5);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-bold);
}

.bb-blog-hub-text {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

/* =====================================
   Subscribe / Empty
===================================== */
.bb-blog-subscribe-section {
  padding: 0;
}

.bb-blog-subscribe-card {
  margin-top: 0;
  padding: 32px;
  border-radius: var(--bb-radius-2xl);
  background: radial-gradient(circle at 88% 8%, color-mix(in srgb, var(--bb-blog-accent) 24%, transparent) 0, transparent 32%), linear-gradient(135deg, var(--bb-blog-warm) 0%, var(--bb-body-bg) 100%);
  border: 1px solid color-mix(in srgb, var(--bb-blog-accent) 24%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-sm);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.82fr);
  gap: 22px;
  align-items: center;
}

.bb-blog-subscribe-card-title {
  margin: 0 0 9px;
  color: var(--bb-heading-color);
  font-size: var(--bb-web-subsection-title-size);
  line-height: var(--bb-line-height-heading);
  letter-spacing: -0.03em;
  font-weight: var(--bb-fw-bold);
}

.bb-blog-subscribe-card-text {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-loose);
  margin: 0;
}

.bb-blog-subscribe-card-form {
  padding: 0.5rem;
}

.bb-blog-subscribe-card-input {
  height: 42px;
  padding: 0 12px;
}

.bb-blog-subscribe-card-button {
  min-width: 124px;
  height: 42px;
  padding: 0 18px;
}

.bb-blog-empty-card {
  min-height: 320px;
  border-radius: var(--bb-radius-2xl);
  background-color: var(--bb-body-bg);
  border: 1px solid var(--bb-blog-card-border);
  box-shadow: var(--bb-shadow-sm);
  display: grid;
  grid-template-columns: 140px minmax(0, 1fr);
  gap: 26px;
  align-items: center;
  padding: 34px;
}

.bb-blog-empty-icon {
  width: 128px;
  height: 128px;
  border-radius: var(--bb-radius-2xl);
  background-color: var(--bb-blog-accent-soft);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-blog-dark-surface);
}

.bb-blog-empty-icon .material-symbols-outlined {
  font-size: var(--bb-icon-size-4xl);
}

.bb-blog-empty-title {
  margin: 0 0 10px;
  color: var(--bb-heading-color);
  font-size: var(--bb-h2);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-bold);
}

.bb-blog-empty-text {
  max-width: 47.5rem;
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-base);
  line-height: var(--bb-line-height-loose);
}

/* =====================================
   Responsive
===================================== */
@media (max-width: 1199.98px) {
  .bb-blog-hero-inner,
  .bb-blog-featured-card,
  .bb-blog-subscribe-card {
    grid-template-columns: 1fr;
  }
  .bb-blog-featured-media {
    min-height: 320px;
  }
  .bb-blog-grid,
  .bb-blog-special-grid,
  .bb-blog-hub-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .bb-blog-search-card {
    border-radius: var(--bb-radius-xl);
    align-items: stretch;
    flex-direction: column;
    padding: 12px;
  }
  .bb-blog-search-icon {
    display: none;
  }
  .bb-blog-search-input {
    width: 100%;
    height: 44px;
    padding: 0 12px;
    background-color: var(--bb-tertiary-bg);
    border-radius: var(--bb-radius-lg);
  }
  .bb-blog-search-button {
    width: 100%;
  }
  .bb-blog-featured-card {
    padding: 16px;
    min-height: 0;
    border-radius: var(--bb-radius-2xl);
  }
  .bb-blog-featured-media {
    min-height: 220px;
    border-radius: var(--bb-radius-xl);
  }
  .bb-blog-category-card {
    padding: 14px;
    overflow: visible;
  }
  .bb-blog-section-head,
  .bb-blog-special-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .bb-blog-grid,
  .bb-blog-special-grid,
  .bb-blog-hub-grid {
    grid-template-columns: 1fr;
  }
  .bb-blog-card {
    min-height: 0;
  }
  .bb-blog-card-media {
    height: 205px;
  }
  .bb-blog-special-section {
    padding: 20px;
  }
  .bb-blog-pagination-wrap {
    align-items: flex-start;
    flex-direction: column;
    margin-bottom: 38px;
  }
  .bb-blog-subscribe-card {
    padding: var(--bb-web-card-padding);
  }
  .bb-blog-subscribe-card-form {
    border-radius: var(--bb-radius-xl);
    align-items: stretch;
    flex-direction: column;
  }
  .bb-blog-subscribe-card-button {
    width: 100%;
  }
  .bb-blog-empty-card {
    grid-template-columns: 1fr;
    padding: 24px;
  }
}
/* =====================================
   Blog Index Page Hero
   /blog index hero makyajı.
   Default bb-hero omurgası üzerine çalışır.
===================================== */
/* =====================================
   Blog Hero Breadcrumb
===================================== */
/* =====================================
   Blog Hero Layout
===================================== */
.bb-blog-eyebrow,
.bb-blog-featured-label {
  display: inline-flex;
  align-items: center;
  border-radius: var(--bb-radius-pill);
}

.bb-blog-eyebrow {
  gap: 0.5rem;
  width: fit-content;
  min-height: 2rem;
  padding: 0.25rem 0.75rem 0.25rem 0.35rem;
  margin-bottom: 1.25rem;
  color: color-mix(in srgb, var(--bb-primary) 58%, var(--bb-emphasis-color));
  background-color: color-mix(in srgb, var(--bb-primary) 10%, var(--bb-surface-elevated));
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-primary) 22%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-xs);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-blog-eyebrow .material-symbols-outlined {
  width: 1.625rem;
  height: 1.625rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-dark);
  background-color: var(--bb-primary);
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-base);
  line-height: 1;
}

.bb-blog-hero-title span {
  color: color-mix(in srgb, var(--bb-primary) 58%, var(--bb-dark));
}

/* =====================================
   Blog Search
===================================== */
.bb-blog-search-card {
  position: relative;
  max-width: 33rem;
  min-height: 4rem;
  margin-top: var(--bb-web-section-head-margin);
  padding: 0.5rem 0.5rem 0.5rem 4.125rem;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 78%, transparent);
  border-radius: var(--bb-radius-pill);
  box-shadow: var(--bb-shadow-sm);
}

.bb-blog-search-icon {
  position: absolute;
  left: 0.5rem;
  top: 50%;
  transform: translateY(-50%);
  width: 3rem;
  height: 3rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-dark);
  background-color: var(--bb-primary);
  border-radius: 50%;
}

.bb-blog-search-icon .material-symbols-outlined {
  color: currentColor;
  font-size: var(--bb-icon-size-lg);
  line-height: 1;
}

.bb-blog-search-input {
  width: 100%;
  min-width: 0;
  height: 3rem;
  padding: 0;
  color: var(--bb-heading-color);
  background-color: transparent;
  border: 0;
  outline: 0;
  box-shadow: none !important;
  font-size: var(--bb-fs-base);
  font-weight: var(--bb-fw-medium);
}

.bb-blog-search-input::placeholder {
  color: var(--bb-secondary-color);
}

.bb-blog-search-button {
  min-width: 7.25rem;
  min-height: 3rem;
  padding: 0 var(--bb-space-6);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  color: var(--bb-white);
  color: var(--bb-white);
  border: 0;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
  cursor: pointer;
}

.bb-blog-search-button:hover {
  color: var(--bb-white);
  background-color: color-mix(in srgb, var(--bb-coal-300) 90%, black);
}

.bb-blog-search-button .material-symbols-outlined {
  color: currentColor;
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

/* =====================================
   Blog Featured Card
===================================== */
.bb-blog-featured-card {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(18rem, 1fr);
  gap: 1.5rem;
  align-items: stretch;
  padding: var(--bb-web-card-padding);
  background-color: color-mix(in srgb, var(--bb-body-bg) 94%, transparent);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 78%, transparent);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-lg);
  backdrop-filter: blur(0.625rem);
  -webkit-backdrop-filter: blur(0.625rem);
}

.bb-blog-featured-copy {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 0.5rem 0 0.25rem;
}

.bb-blog-featured-label {
  gap: 0.45rem;
  min-height: 2rem;
  padding: 0.25rem 0.75rem;
  color: color-mix(in srgb, var(--bb-primary) 58%, var(--bb-emphasis-color));
  background-color: color-mix(in srgb, var(--bb-primary) 12%, var(--bb-white));
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-primary) 18%, var(--bb-border-color));
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-blog-featured-label .material-symbols-outlined {
  color: color-mix(in srgb, var(--bb-primary) 52%, var(--bb-dark));
  font-size: var(--bb-fs-base);
  line-height: 1;
}

.bb-blog-featured-title {
  margin: 1rem 0 0;
  color: var(--bb-heading-color);
  font-size: var(--bb-web-section-title-size);
  font-weight: var(--bb-fw-extrabold);
  line-height: 1.07;
  letter-spacing: -0.05em;
}

.bb-blog-featured-text {
  margin: 1rem 0 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-base);
  line-height: var(--bb-line-height-content);
}

.bb-blog-featured-meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.625rem;
  margin-top: 1.25rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-medium);
  line-height: var(--bb-line-height-base);
}

.bb-blog-mini-dot {
  width: 0.5rem;
  height: 0.5rem;
  display: inline-flex;
  flex: 0 0 auto;
  background-color: var(--bb-primary);
  border-radius: 50%;
  box-shadow: 0 0 0 0.25rem color-mix(in srgb, var(--bb-primary) 16%, transparent);
}

.bb-blog-featured-cta {
  min-height: 3rem;
  margin-top: auto;
  padding: 0 1.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  color: var(--bb-white) !important;
  color: var(--bb-white);
  border-radius: var(--bb-radius-pill);
  text-decoration: none !important;
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-blog-featured-cta:hover {
  color: var(--bb-white) !important;
  background-color: color-mix(in srgb, var(--bb-coal-300) 90%, black);
}

.bb-blog-featured-cta .material-symbols-outlined {
  color: currentColor;
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-blog-featured-media {
  overflow: hidden;
  display: block;
  background-color: var(--bb-tertiary-bg);
  border-radius: var(--bb-radius-2xl);
}

.bb-blog-featured-media img {
  width: 100%;
  height: 100%;
  min-height: 26rem;
  display: block;
  object-fit: cover;
}

/* Empty featured fallback */
.bb-blog-featured-empty {
  padding: 2rem;
  color: var(--bb-secondary-color);
  background-color: color-mix(in srgb, var(--bb-body-bg) 92%, transparent);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 78%, transparent);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-xs);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
  line-height: var(--bb-line-height-content);
}

/* =====================================
   Blog Categories Card
   Hero altındaki başlık seçimi paneli.
===================================== */
.bb-blog-category-section {
  position: relative;
  z-index: 5;
}

.bb-blog-category-card {
  margin-top: -5.25rem;
  padding: 1.25rem;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 78%, transparent);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-lg);
}

.bb-blog-category-row {
  min-width: 0;
}

/* Component içinden gelen başlık varsa premiumlaştır */
.bb-blog-category-card h2,
.bb-blog-category-card .bb-blog-category-title {
  margin: 0 0 1rem;
  color: var(--bb-heading-color);
  font-size: var(--bb-web-subsection-title-size);
  font-weight: var(--bb-fw-extrabold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: var(--bb-letter-spacing-tight, -0.035em);
}

/* Component içindeki chip/nav/pill yapıları için güvenli genel düzen */
.bb-blog-category-card .bb-chip,
.bb-blog-category-card a,
.bb-blog-category-card button {
  text-decoration: none;
}

.bb-blog-category-card .material-symbols-outlined {
  color: currentColor;
  line-height: 1;
}

/* =====================================
   Blog Index Responsive
===================================== */
@media (max-width: 1199.98px) {
  .bb-blog-featured-card {
    grid-template-columns: minmax(0, 0.8fr) minmax(18rem, 1fr);
  }
  .bb-blog-featured-media img {
    min-height: 22rem;
  }
}
@media (max-width: 991.98px) {
  .bb-blog-featured-card {
    grid-template-columns: 1fr;
  }
  .bb-blog-featured-media {
    order: -1;
  }
  .bb-blog-featured-media img {
    min-height: 20rem;
    max-height: 24rem;
  }
  .bb-blog-category-card {
    margin-top: -2.25rem;
  }
}
@media (max-width: 767.98px) {
  .bb-blog-search-card {
    max-width: 100%;
    padding-right: 0.5rem;
  }
  .bb-blog-search-button {
    min-width: auto;
    padding-inline: 1rem;
  }
  .bb-blog-featured-card {
    padding: 1rem;
    border-radius: var(--bb-radius-xl);
  }
  .bb-blog-featured-media {
    border-radius: var(--bb-radius-xl);
  }
  .bb-blog-category-card {
    margin-top: -1.5rem;
    padding: 1rem;
    border-radius: var(--bb-radius-xl);
  }
}
@media (max-width: 575.98px) {
  .bb-blog-search-card {
    padding: 0.5rem;
    flex-wrap: wrap;
    border-radius: var(--bb-radius-xl);
  }
  .bb-blog-search-icon {
    position: static;
    transform: none;
    width: 2.75rem;
    height: 2.75rem;
  }
  .bb-blog-search-input {
    width: calc(100% - 3.5rem);
    flex: 1 1 0;
  }
  .bb-blog-search-button {
    width: 100%;
  }
  .bb-blog-featured-title {
    font-size: var(--bb-web-section-title-size);
  }
}
/* =====================================
   Hero + Breadcrumb
