/* =====================================
   Blog Detail Author Card
===================================== */
.bb-blog-author-card {
  --bb-blog-author-card-border: color-mix(in srgb, var(--bb-border-color) 88%, transparent);
  --bb-blog-author-card-bg:
      radial-gradient(circle at 94% 12%, color-mix(in srgb, var(--bb-primary) 20%, transparent) 0, transparent 34%),
      var(--bb-surface-elevated, var(--bb-body-bg));
  --bb-blog-author-avatar-border: color-mix(in srgb, var(--bb-white) 70%, transparent);
  --bb-blog-author-avatar-bg:
      linear-gradient(135deg, var(--bb-emphasis-color) 0%, color-mix(in srgb, var(--bb-emphasis-color) 82%, var(--bb-primary)) 100%);
  --bb-blog-author-label-bg: color-mix(in srgb, var(--bb-primary) 18%, var(--bb-body-bg));
  --bb-blog-author-label-color: color-mix(in srgb, var(--bb-primary) 72%, var(--bb-emphasis-color));
  position: relative;
