  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  width: 5.375rem;
  height: 5.375rem;
  border: var(--bb-border-width) solid var(--bb-blog-author-avatar-border);
  border-radius: var(--bb-radius-2xl);
  background: var(--bb-blog-author-avatar-bg);
  box-shadow: var(--bb-shadow-sm);
}

.bb-blog-author-avatar img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.bb-blog-author-avatar .material-symbols-outlined,
.bb-blog-author-avatar .material-icons {
  color: var(--bb-primary);
  font-size: var(--bb-icon-size-2xl, 2.375rem);
  line-height: 1;
}

.bb-blog-author-body {
  min-width: 0;
}

.bb-blog-author-label {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  min-height: 1.625rem;
  padding: 0 0.625rem;
  margin-bottom: 0.5625rem;
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-blog-author-label-color);
  color: color-mix(in srgb, var(--bb-primary) 72%, var(--bb-emphasis-color));
  font-size: var(--bb-fs-xs);
  line-height: 1;
  font-weight: var(--bb-fw-bold);
}

.bb-blog-author-label .material-symbols-outlined,
.bb-blog-author-label .material-icons {
  color: color-mix(in srgb, var(--bb-primary) 82%, var(--bb-emphasis-color));
