  font-size: var(--bb-fs-xs);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-semibold);
}

.bb-blog-author-footnote .material-symbols-outlined,
.bb-blog-author-footnote .material-icons {
  color: color-mix(in srgb, var(--bb-primary) 82%, var(--bb-emphasis-color));
  font-size: var(--bb-icon-size-sm, 0.9375rem);
  line-height: 1;
}

/* =====================================
   Blog Detail Author Card Dark Tokens
===================================== */
[data-bs-theme=dark] .bb-blog-author-card {
  --bb-blog-author-card-border: color-mix(in srgb, var(--bb-border-color) 84%, transparent);
  --bb-blog-author-card-bg:
      radial-gradient(circle at 94% 12%, color-mix(in srgb, var(--bb-primary) 16%, transparent) 0, transparent 34%),
      var(--bb-surface-elevated, var(--bb-body-bg));
  --bb-blog-author-avatar-border: color-mix(in srgb, var(--bb-white) 14%, transparent);
  --bb-blog-author-avatar-bg:
      linear-gradient(135deg, color-mix(in srgb, var(--bb-emphasis-color) 88%, var(--bb-body-bg)) 0%, color-mix(in srgb, var(--bb-primary) 24%, var(--bb-body-bg)) 100%);
  --bb-blog-author-label-bg: color-mix(in srgb, var(--bb-primary) 20%, var(--bb-body-bg));
  --bb-blog-author-label-color: color-mix(in srgb, var(--bb-primary) 84%, var(--bb-emphasis-color));
