  display: inline-flex;
  align-items: center;
  margin-bottom: 14px;
  padding: 6px 12px;
  border-radius: var(--bb-radius-pill, 999px);
  font-size: var(--bb-fs-sm, 0.875rem);
  font-weight: var(--bb-fw-bold, 700);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.bb-roadmap-status-planned {
  background-color: var(--bb-roadmap-planned-soft);
  color: var(--bb-secondary-color, #64748b);
}

.bb-roadmap-status-progress {
  background-color: var(--bb-roadmap-progress-soft);
  color: var(--bb-roadmap-progress-text);
}

.bb-roadmap-status-completed {
  background-color: var(--bb-roadmap-completed-soft);
  color: var(--bb-roadmap-completed-text);
}

.bb-roadmap-title {
  margin-bottom: 12px;
  color: var(--bb-emphasis-color, #333e48);
  font-size: clamp(1.45rem, 2.4vw, 2rem);
  line-height: 1.3;
  font-weight: var(--bb-fw-bold, 700);
  letter-spacing: -0.02em;
}

.bb-roadmap-text {
  color: var(--bb-secondary-color, #64748b);
  font-size: var(--bb-fs-base, 1rem);
  line-height: var(--bb-line-height-loose, 1.75);
}

.bb-roadmap-text p:last-child {
  margin-bottom: 0;
}

.bb-roadmap-banner-section {
  padding-top: 0;
}

/* =====================================
   Dark Mode
===================================== */
[data-bs-theme=dark] .bb-roadmap-page {
  --bb-roadmap-planned-soft: color-mix(in srgb, var(--bb-roadmap-planned) 22%, transparent);
  --bb-roadmap-progress-soft: color-mix(in srgb, var(--bb-roadmap-progress) 24%, transparent);
  --bb-roadmap-completed-soft: color-mix(in srgb, var(--bb-roadmap-completed) 22%, transparent);
  --bb-roadmap-progress-text: color-mix(in srgb, var(--bb-roadmap-progress) 82%, #ffffff);
  --bb-roadmap-completed-text: color-mix(in srgb, var(--bb-roadmap-completed) 78%, #ffffff);
}

/* =====================================
   Responsive
===================================== */
@media (max-width: 767.98px) {
  .bb-roadmap-timeline {
    padding-left: 24px;
  }
  .bb-roadmap-item::before {
    left: -28px;
  }
  .bb-roadmap-card {
    padding: 20px;
  }
  .bb-roadmap-filter {
    width: 100%;
  }
}
/* =====================================
   Hero
===================================== */
.bb-ir-hero {
  position: relative;
  overflow: hidden;
  background: radial-gradient(circle at 88% 18%, var(--bb-primary-light) 0, transparent 26%), linear-gradient(180deg, var(--bb-tertiary-bg) 0%, var(--bb-secondary-bg) 100%);
  border-bottom: 1px solid var(--bb-border-color);
}

.bb-ir-hero::before {
  content: "";
  position: absolute;
  top: -70px;
  right: -50px;
  width: 16.25rem;
  height: 260px;
  border-radius: 50%;
  background-color: color-mix(in srgb, var(--bb-coal-300) 6%, transparent);
}

.bb-ir-hero::after {
  content: "";
  position: absolute;
  right: 140px;
  top: 130px;
  width: 170px;
  height: 170px;
  border-radius: 50%;
  background-color: color-mix(in srgb, var(--bb-primary) 14%, transparent);
}

.bb-ir-hero-inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 390px;
  gap: 48px;
  align-items: center;
}

.bb-ir-hero-content {
  min-width: 0;
}

.bb-ir-label {
  margin-bottom: 14px;
}

.bb-ir-title {
  max-width: 780px;
  margin-bottom: 18px;
  font-size: clamp(2rem, 4vw, 3.35rem);
}

.bb-ir-text {
  max-width: 47.5rem;
  margin-bottom: 0;
}

.bb-ir-actions {
  margin-top: 32px;
}

/* =====================================
   Snapshot
===================================== */
.bb-ir-snapshot {
  position: relative;
  z-index: 2;
  padding: 26px;
  background-color: var(--bb-body-bg);
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-sm);
}

.bb-ir-snapshot h2 {
  margin-bottom: 1rem;
  color: var(--bb-heading-color);
  font-size: var(--bb-h3);
  line-height: 1.3;
  font-weight: var(--bb-fw-bold);
}

.bb-ir-snapshot-row {
  padding: 14px 0;
  border-top: 1px solid var(--bb-border-color);
}

.bb-ir-snapshot-row:first-of-type {
  border-top: 0;
  padding-top: 0;
}

.bb-ir-snapshot-row strong {
  display: block;
  margin-bottom: 5px;
  color: var(--bb-tertiary-color);
  font-size: var(--bb-fs-sm);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.bb-ir-snapshot-row span {
  display: block;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
  font-weight: var(--bb-fw-semibold);
}

/* =====================================
   Shared
===================================== */
.bb-ir-section-head {
  max-width: 820px;
  margin-bottom: 32px;
}

.bb-ir-section-title {
  margin-bottom: 1rem;
  font-size: clamp(1.8rem, 3vw, 2.7rem);
}

.bb-ir-section-text {
  margin-bottom: 0;
}

.bb-ir-overview-section {
  padding-bottom: 32px;
}

.bb-ir-overview-card {
  max-width: 1040px;
  margin: 0 auto;
  padding: 32px;
  text-align: center;
  background-color: var(--bb-body-bg);
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-xs);
}

.bb-ir-overview-card p:last-child {
  margin-bottom: 0;
}

/* =====================================
   Highlight Cards
===================================== */
.bb-ir-highlight-card,
.bb-ir-resource-card,
.bb-ir-update-card {
  height: 100%;
  padding: 24px;
  background-color: var(--bb-body-bg);
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-xs);
}

.bb-ir-highlight-card strong {
  display: block;
  margin-bottom: 0.75rem;
  color: var(--bb-heading-color);
  font-size: var(--bb-h2);
  line-height: 1;
  font-weight: var(--bb-fw-bold);
}

.bb-ir-highlight-card h3,
.bb-ir-resource-card h3,
.bb-ir-update-card h3 {
  margin-bottom: 0.75rem;
  color: var(--bb-heading-color);
  font-size: var(--bb-h3);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-bold);
}

.bb-ir-highlight-card p,
.bb-ir-resource-card p,
.bb-ir-update-card p {
  margin-bottom: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: 1.9;
}

/* =====================================
   Resource Cards
===================================== */
.bb-ir-resource-card {
  display: block;
  color: inherit;
  text-decoration: none;
  transition: transform var(--bb-transition-normal), box-shadow var(--bb-transition-normal), border-color var(--bb-transition-normal);
}

.bb-ir-resource-card:hover {
  transform: translateY(-4px);
  border-color: color-mix(in srgb, var(--bb-primary) 45%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-sm);
  color: inherit;
}

.bb-ir-resource-icon {
  width: 54px;
  height: 54px;
  margin-bottom: 1rem;
  border-radius: var(--bb-radius-lg);
  background-color: var(--bb-tertiary-bg);
  border: 1px solid var(--bb-border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-heading-color);
}

.bb-ir-resource-icon .material-symbols-outlined {
  font-size: var(--bb-fs-2xl);
}

.bb-ir-resource-card p {
  margin-bottom: 1rem;
}

.bb-ir-resource-link {
  color: var(--bb-heading-color);
  font-weight: var(--bb-fw-bold);
}

.bb-ir-resource-card:hover .bb-ir-resource-link {
  color: var(--bb-link-color);
}

/* =====================================
   Founder
===================================== */
.bb-ir-founder {
  padding: 32px;
  background: linear-gradient(135deg, var(--bb-body-bg) 0%, var(--bb-tertiary-bg) 100%);
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-xs);
}

.bb-ir-founder-quote {
  margin-bottom: 1rem;
  color: var(--bb-link-color);
  font-size: var(--bb-icon-size-4xl);
  line-height: 1;
  font-weight: var(--bb-fw-bold);
}

.bb-ir-founder h3 {
  margin-bottom: 1rem;
  color: var(--bb-heading-color);
  font-size: clamp(1.7rem, 3vw, 2.3rem);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-bold);
}

.bb-ir-founder p {
  margin-bottom: 1rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-base);
  line-height: 1.95;
}

.bb-ir-founder p:last-child {
  margin-bottom: 0;
}

/* =====================================
   Hidden Quarter Block
===================================== */
.bb-ir-quarter-hidden {
  display: none;
}

.bb-ir-quarter {
  position: relative;
  overflow: hidden;
  background: linear-gradient(135deg, #022b57 0%, #083b74 100%);
}

.bb-ir-quarter::after {
  content: "";
  position: absolute;
  right: -60px;
  top: -60px;
  width: 180px;
  height: 180px;
  border-radius: 50%;
  background-color: color-mix(in srgb, var(--bb-primary) 14%, transparent);
}

.bb-ir-quarter .bb-web-container {
  position: relative;
  z-index: 2;
}

.bb-ir-quarter-head {
  max-width: 960px;
  margin: 0 auto 32px;
  text-align: center;
}

.bb-ir-quarter .bb-ir-section-title,
.bb-ir-quarter .bb-ir-section-text {
  color: var(--bb-white);
}

.bb-ir-quarter-card {
  height: 100%;
  padding: 1.375rem;
  text-align: center;
  background-color: color-mix(in srgb, var(--bb-body-bg) 96%, transparent);
  border-radius: var(--bb-radius-xl);
  box-shadow: var(--bb-shadow-sm);
}

.bb-ir-quarter-card-icon {
  width: 54px;
  height: 54px;
  margin: 0 auto 16px;
  border-radius: var(--bb-radius-lg);
  background-color: var(--bb-tertiary-bg);
  border: 1px solid var(--bb-border-color);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-heading-color);
}

.bb-ir-quarter-card-icon .material-symbols-outlined {
  font-size: var(--bb-fs-2xl);
}

.bb-ir-quarter-card h3 {
  margin-bottom: 0;
  color: var(--bb-heading-color);
  font-size: var(--bb-h5);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-bold);
}

/* =====================================
   Banner
===================================== */
/* =====================================
   Responsive
===================================== */
@media (max-width: 991.98px) {
  .bb-ir-hero-inner {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .bb-ir-snapshot {
    max-width: 560px;
  }
}
@media (max-width: 767.98px) {
  .bb-ir-snapshot,
  .bb-ir-overview-card,
  .bb-ir-highlight-card,
  .bb-ir-resource-card,
  .bb-ir-founder,
  .bb-ir-quarter-card {
    padding: 20px;
  }
}
.bb-company-label {
  margin-bottom: 14px;
}

.bb-company-title {
  margin-bottom: 18px;
  font-size: clamp(2rem, 4vw, 3.2rem);
}

.bb-company-text {
  max-width: 720px;
  margin-bottom: 0;
}

/* =====================================
   Layout
===================================== */
.bb-company-info-section {
  background-color: transparent;
}

.bb-company-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(340px, 0.85fr);
  gap: 24px;
  margin-top: 24px;
}

/* =====================================
   Cards
===================================== */
.bb-company-card {
  height: 100%;
  padding: 26px;
  background-color: var(--bb-body-bg);
  border: 1px solid var(--bb-border-color);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-xs);
  transition: transform var(--bb-transition-normal), box-shadow var(--bb-transition-normal), border-color var(--bb-transition-normal);
}

.bb-company-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--bb-shadow-sm);
}

.bb-company-card-primary {
  border-color: color-mix(in srgb, var(--bb-primary) 36%, var(--bb-border-color));
  box-shadow: 0 12px 34px color-mix(in srgb, var(--bb-primary) 10%, transparent);
}

.bb-company-card-head {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
}

.bb-company-card-icon {
  width: 44px;
  height: 44px;
  border-radius: var(--bb-radius-lg);
  background-color: var(--bb-primary-light);
  color: color-mix(in srgb, var(--bb-primary) 58%, var(--bb-dark));
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
}

.bb-company-card-icon .material-symbols-outlined {
  font-size: var(--bb-fs-xl);
  line-height: 1;
}

.bb-company-card-title {
  margin: 0;
  color: var(--bb-heading-color);
  font-size: var(--bb-h3);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-bold);
  letter-spacing: -0.02em;
}

/* =====================================
   Fields
===================================== */
.bb-company-info-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.125rem;
}

.bb-company-field-list {
  display: grid;
  gap: 16px;
}

.bb-company-field {
  min-width: 0;
}

.bb-company-field span {
  display: block;
  margin-bottom: 7px;
  color: var(--bb-tertiary-color);
  font-size: var(--bb-fs-sm);
  line-height: 1;
  font-weight: var(--bb-fw-bold);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.bb-company-field strong {
  display: block;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-semibold);
  word-break: break-word;
  overflow-wrap: anywhere;
}

.bb-company-address p {
  margin-bottom: 0.625rem;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-base);
  line-height: 1.85;
  font-weight: var(--bb-fw-semibold);
}

.bb-company-address p:last-child {
  margin-bottom: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
}

/* =====================================
   Banner
===================================== */
.bb-company-banner-section {
  padding-bottom: 0;
}

/* =====================================
   Responsive
===================================== */
@media (max-width: 1199.98px) {
  .bb-company-info-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 991.98px) {
  .bb-company-grid {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 767.98px) {
  .bb-company-card {
    padding: 20px;
  }
  .bb-company-info-grid {
    grid-template-columns: 1fr;
  }
  .bb-company-card-head {
    align-items: flex-start;
  }
}
/* =====================================
   Bulbulustur Web — Draugr Product
   Dark product surface with Bulbulustur primary accent.
   Application layer only; all primitives come from Core.
===================================== */
.bb-draugr-page {
  --bb-draugr-bg: var(--bb-dark);
  --bb-draugr-ink: var(--bb-theme-on-dark);
  --bb-draugr-muted: color-mix(in srgb, var(--bb-theme-on-dark) 66%, transparent);
  --bb-draugr-soft: color-mix(in srgb, var(--bb-theme-on-dark) 5%, var(--bb-dark));
  --bb-draugr-soft-strong: color-mix(in srgb, var(--bb-theme-on-dark) 8%, var(--bb-dark));
  --bb-draugr-line: color-mix(in srgb, var(--bb-theme-on-dark) 12%, transparent);
  --bb-draugr-line-strong: color-mix(in srgb, var(--bb-theme-on-dark) 20%, transparent);
  --bb-draugr-accent: var(--bb-primary);
  --bb-draugr-accent-soft: color-mix(in srgb, var(--bb-primary) 14%, transparent);
  --bb-draugr-accent-line: color-mix(in srgb, var(--bb-primary) 34%, transparent);
  overflow: hidden;
  color: var(--bb-draugr-ink);
  background: var(--bb-draugr-bg);
}

.bb-draugr-page .bb-web-container {
  width: min(100% - 2rem, 90rem);
  margin-inline: auto;
}

.bb-draugr-page .bb-page-section {
  padding: clamp(4.5rem, 8vw, 8rem) 0;
  color: var(--bb-draugr-ink);
  background: var(--bb-draugr-bg);
}

.bb-draugr-page .bb-page-hero-label,
.bb-draugr-page .bb-draugr-section-label {
  color: var(--bb-draugr-accent);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.bb-draugr-page .bb-page-hero-title,
.bb-draugr-page .bb-draugr-section-title,
.bb-draugr-page h2,
.bb-draugr-page h3 {
  color: var(--bb-draugr-ink);
}

/* =====================================
   Hero
===================================== */
.bb-draugr-page-hero {
  position: relative;
  padding: clamp(5rem, 8vw, 8.5rem) 0 clamp(4rem, 7vw, 7rem);
  color: var(--bb-draugr-ink);
  background: radial-gradient(circle at 82% 12%, var(--bb-draugr-accent-soft), transparent 30%), var(--bb-draugr-bg);
  border-bottom: 1px solid var(--bb-draugr-accent-line);
}

.bb-draugr-page-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(90deg, transparent 0 49.9%, color-mix(in srgb, var(--bb-theme-on-dark) 4%, transparent) 50%, transparent 50.1%), linear-gradient(0deg, transparent 0 49.9%, color-mix(in srgb, var(--bb-theme-on-dark) 3%, transparent) 50%, transparent 50.1%);
  background-size: 4rem 4rem;
  mask-image: linear-gradient(to bottom, color-mix(in srgb, var(--bb-dark) 60%, transparent), transparent 72%);
}

.bb-draugr-hero-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(32rem, 1.1fr);
  gap: clamp(3rem, 7vw, 7rem);
  align-items: center;
}

.bb-draugr-hero-copy {
  max-width: 45rem;
}

.bb-draugr-label {
  display: inline-flex;
  align-items: center;
  gap: var(--bb-space-2);
  margin-bottom: 1.5rem;
}

.bb-draugr-label::before {
  content: "";
  width: 2.25rem;
  height: 0.125rem;
  background: var(--bb-draugr-accent);
}

.bb-draugr-hero-title {
  max-width: 11ch;
  margin: 0;
  font-size: clamp(3.25rem, 6.6vw, 6.75rem);
  font-weight: var(--bb-fw-extrabold);
  line-height: 0.94;
  letter-spacing: -0.065em;
}

.bb-draugr-hero-text {
  max-width: 42rem;
  margin: 1.75rem 0 0;
  color: var(--bb-draugr-muted);
  font-size: clamp(var(--bb-fs-base), 1.6vw, var(--bb-fs-xl));
  line-height: var(--bb-line-height-loose);
}

.bb-draugr-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--bb-space-3);
  margin-top: 2rem;
}

.bb-draugr-page .bb-draugr-primary-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--bb-space-2);
  color: var(--bb-dark);
  background: var(--bb-draugr-accent);
  border-color: var(--bb-draugr-accent);
  border-radius: var(--bb-radius-pill);
  font-weight: var(--bb-fw-bold);
}

.bb-draugr-page .bb-draugr-primary-action:hover {
  color: var(--bb-dark);
  background: var(--bb-primary-hover);
  border-color: var(--bb-primary-hover);
}

.bb-draugr-page .bb-draugr-secondary-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--bb-space-2);
  color: var(--bb-draugr-ink);
  background: transparent;
  border-color: var(--bb-draugr-line-strong);
  border-radius: var(--bb-radius-pill);
}

.bb-draugr-page .bb-draugr-secondary-action:hover {
  color: var(--bb-draugr-ink);
  background: var(--bb-draugr-soft-strong);
  border-color: var(--bb-draugr-line-strong);
}

.bb-draugr-hero-proof {
  display: flex;
  flex-wrap: wrap;
  gap: var(--bb-space-5);
  margin-top: 2rem;
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-sm);
}

.bb-draugr-hero-proof span {
  display: inline-flex;
  align-items: center;
  gap: var(--bb-space-2);
}

.bb-draugr-hero-proof .material-symbols-outlined {
  color: var(--bb-draugr-accent);
  font-size: var(--bb-fs-base);
}

/* =====================================
   Hero product console
===================================== */
.bb-draugr-console {
  overflow: hidden;
  border: 1px solid var(--bb-draugr-line-strong);
  border-radius: var(--bb-radius-2xl);
  background: color-mix(in srgb, var(--bb-theme-on-dark) 3%, var(--bb-dark));
  box-shadow: var(--bb-shadow-lg);
}

.bb-draugr-console-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--bb-space-4);
  padding: 1rem 1.25rem;
  border-bottom: 1px solid var(--bb-draugr-line);
}

.bb-draugr-console-brand,
.bb-draugr-console-live {
  display: inline-flex;
  align-items: center;
  gap: var(--bb-space-2);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

.bb-draugr-console-brand .material-symbols-outlined,
.bb-draugr-console-live {
  color: var(--bb-draugr-accent);
}

.bb-draugr-console-live::before {
  content: "";
  width: 0.5rem;
  height: 0.5rem;
  background: var(--bb-draugr-accent);
  border-radius: var(--bb-radius-pill);
  box-shadow: 0 0 0 0.25rem var(--bb-draugr-accent-soft);
}

.bb-draugr-console-body {
  display: grid;
  grid-template-columns: 4.25rem minmax(0, 1fr);
  min-height: 31rem;
}

.bb-draugr-console-rail {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--bb-space-5);
  padding: 1.5rem var(--bb-space-2);
  border-right: 1px solid var(--bb-draugr-line);
}

.bb-draugr-console-rail .material-symbols-outlined {
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-lg);
}

.bb-draugr-console-rail .is-active {
  color: var(--bb-draugr-accent);
}

.bb-draugr-console-stage {
  padding: clamp(1.25rem, 3vw, 2rem);
}

.bb-draugr-console-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--bb-space-4);
  margin-bottom: 1.5rem;
}

.bb-draugr-console-heading small {
  display: block;
  margin-bottom: var(--bb-space-1);
  color: var(--bb-draugr-muted);
}

.bb-draugr-console-heading strong {
  color: var(--bb-draugr-ink);
  font-size: var(--bb-fs-xl);
}

.bb-draugr-console-score {
  color: var(--bb-draugr-accent);
  font-family: var(--bb-font-mono);
  font-size: var(--bb-fs-sm);
}

.bb-draugr-console-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--bb-space-3);
}

.bb-draugr-console-metric {
  padding: 1rem;
  border: 1px solid var(--bb-draugr-line);
  border-radius: var(--bb-radius-lg);
  background: var(--bb-draugr-soft);
}

.bb-draugr-console-metric span,
.bb-draugr-console-metric small {
  display: block;
}

.bb-draugr-console-metric span {
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-xs);
}

.bb-draugr-console-metric strong {
  display: block;
  margin: var(--bb-space-2) 0 var(--bb-space-1);
  color: var(--bb-draugr-ink);
  font-size: var(--bb-fs-2xl);
}

.bb-draugr-console-metric small {
  color: var(--bb-draugr-accent);
  font-size: var(--bb-fs-2xs);
}

.bb-draugr-console-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(13rem, 0.6fr);
  gap: var(--bb-space-3);
  margin-top: var(--bb-space-3);
}

.bb-draugr-console-chart,
.bb-draugr-console-feed {
  min-height: 15rem;
  padding: 1rem;
  border: 1px solid var(--bb-draugr-line);
  border-radius: var(--bb-radius-lg);
  background: var(--bb-draugr-soft);
}

.bb-draugr-console-chart-head,
.bb-draugr-console-feed-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--bb-space-3);
  margin-bottom: 1rem;
  color: var(--bb-draugr-ink);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

.bb-draugr-console-bars {
  display: flex;
  align-items: flex-end;
  gap: 0.375rem;
  height: 10rem;
  padding-top: 1rem;
  border-bottom: 1px solid var(--bb-draugr-line);
}

.bb-draugr-console-bars span {
  flex: 1 1 0;
  min-width: 0.25rem;
  height: var(--bb-draugr-bar, 50%);
  background: var(--bb-draugr-accent);
  border-radius: var(--bb-radius-xs) var(--bb-radius-xs) 0 0;
  opacity: 0.88;
}

.bb-draugr-console-bars span:nth-child(2n) {
  opacity: 0.56;
}

.bb-draugr-console-bars span:nth-child(1) {
  height: 32%;
}

.bb-draugr-console-bars span:nth-child(2) {
  height: 44%;
}

.bb-draugr-console-bars span:nth-child(3) {
  height: 38%;
}

.bb-draugr-console-bars span:nth-child(4) {
  height: 58%;
}

.bb-draugr-console-bars span:nth-child(5) {
  height: 72%;
}

.bb-draugr-console-bars span:nth-child(6) {
  height: 64%;
}

.bb-draugr-console-bars span:nth-child(7) {
  height: 82%;
}

.bb-draugr-console-bars span:nth-child(8) {
  height: 94%;
}

.bb-draugr-console-bars span:nth-child(9) {
  height: 76%;
}

.bb-draugr-console-bars span:nth-child(10) {
  height: 68%;
}

.bb-draugr-console-bars span:nth-child(11) {
  height: 54%;
}

.bb-draugr-console-bars span:nth-child(12) {
  height: 42%;
}

.bb-draugr-console-feed {
  display: flex;
  flex-direction: column;
}

.bb-draugr-console-event {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: var(--bb-space-2);
  padding: var(--bb-space-3) 0;
  border-top: 1px solid var(--bb-draugr-line);
}

.bb-draugr-console-event:first-of-type {
  border-top: 0;
}

.bb-draugr-console-event .material-symbols-outlined {
  color: var(--bb-draugr-accent);
  font-size: var(--bb-fs-base);
}

.bb-draugr-console-event strong,
.bb-draugr-console-event span {
  display: block;
}

.bb-draugr-console-event strong {
  color: var(--bb-draugr-ink);
  font-size: var(--bb-fs-xs);
}

.bb-draugr-console-event span {
  margin-top: var(--bb-space-1);
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-2xs);
}

/* =====================================
   Highlight strip
===================================== */
.bb-draugr-strip {
  position: relative;
  z-index: 3;
  background: var(--bb-draugr-bg);
}

.bb-draugr-strip-shell {
  overflow: hidden;
  border: 1px solid var(--bb-draugr-line-strong);
  border-top: 0;
  background: var(--bb-draugr-soft);
}

.bb-draugr-strip-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.bb-draugr-strip-item {
  min-width: 0;
  padding: 1.5rem;
  border-right: 1px solid var(--bb-draugr-line);
}

.bb-draugr-strip-item:last-child {
  border-right: 0;
}

.bb-draugr-strip-item strong,
.bb-draugr-strip-item span {
  display: block;
}

.bb-draugr-strip-item strong {
  margin-bottom: var(--bb-space-2);
  color: var(--bb-draugr-ink);
  font-size: var(--bb-fs-lg);
}

.bb-draugr-strip-item span {
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

/* =====================================
   Shared section rhythm
===================================== */
.bb-draugr-section-head {
  max-width: 48rem;
}

.bb-draugr-section-head-wide {
  max-width: 54rem;
  margin-bottom: clamp(2rem, 4vw, 3.5rem);
}

.bb-draugr-section-title {
  margin: var(--bb-space-3) 0 1rem;
  font-size: clamp(2.35rem, 4vw, 4.5rem);
  font-weight: var(--bb-fw-extrabold);
  line-height: 1;
  letter-spacing: -0.055em;
}

.bb-draugr-section-text {
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-md);
  line-height: var(--bb-line-height-loose);
}

.bb-draugr-section-text p:last-child {
  margin-bottom: 0;
}

.bb-draugr-split {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(24rem, 1.15fr);
  gap: clamp(3rem, 7vw, 7rem);
  align-items: center;
}

.bb-draugr-intro-panel {
  border-top: 1px solid var(--bb-draugr-line-strong);
  border-bottom: 1px solid var(--bb-draugr-line-strong);
}

.bb-draugr-intro-card {
  display: grid;
  grid-template-columns: minmax(10rem, 0.6fr) 1fr;
  gap: var(--bb-space-5);
  padding: 1.5rem 0;
  border-top: 1px solid var(--bb-draugr-line);
}

.bb-draugr-intro-card:first-child {
  border-top: 0;
}

.bb-draugr-intro-card h3,
.bb-draugr-intro-card p {
  margin: 0;
}

.bb-draugr-intro-card h3 {
  font-size: var(--bb-fs-lg);
}

.bb-draugr-intro-card p {
  color: var(--bb-draugr-muted);
  line-height: var(--bb-line-height-content);
}

/* =====================================
   Service cards
===================================== */
.bb-draugr-service-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--bb-space-3);
}

.bb-draugr-service-card {
  min-height: 17rem;
  padding: 1.5rem;
  border: 1px solid var(--bb-draugr-line);
  border-radius: var(--bb-radius-xl);
  background: var(--bb-draugr-soft);
  transition: transform 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;
}

.bb-draugr-service-card:hover {
  transform: translateY(-0.25rem);
  border-color: var(--bb-draugr-accent-line);
  background: var(--bb-draugr-soft-strong);
}

.bb-draugr-service-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.75rem;
  height: 2.75rem;
  margin-bottom: 3.5rem;
  color: var(--bb-dark);
  background: var(--bb-draugr-accent);
  border-radius: var(--bb-radius-pill);
}

.bb-draugr-service-icon .material-symbols-outlined {
  font-size: var(--bb-fs-base);
}

.bb-draugr-service-title {
  margin-bottom: var(--bb-space-3);
  font-size: var(--bb-fs-xl);
}

.bb-draugr-service-text {
  margin: 0;
  color: var(--bb-draugr-muted);
  line-height: var(--bb-line-height-content);
}

/* =====================================
   Flow / cues
===================================== */
.bb-draugr-flow-shell {
  border-top: 1px solid var(--bb-draugr-line-strong);
  border-bottom: 1px solid var(--bb-draugr-line-strong);
}

.bb-draugr-flow-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.bb-draugr-flow-card {
  position: relative;
  min-height: 18rem;
  padding: 2rem;
  border-right: 1px solid var(--bb-draugr-line);
}

.bb-draugr-flow-card:last-child {
  border-right: 0;
}

.bb-draugr-flow-step {
  margin-bottom: 5rem;
  color: var(--bb-draugr-accent);
  font-family: var(--bb-font-mono);
  font-size: var(--bb-fs-xs);
  letter-spacing: 0.12em;
}

.bb-draugr-flow-card h3 {
  margin-bottom: var(--bb-space-3);
  font-size: var(--bb-fs-xl);
}

.bb-draugr-flow-card p {
  margin: 0;
  color: var(--bb-draugr-muted);
  line-height: var(--bb-line-height-content);
}

/* =====================================
   Architecture highlight
===================================== */
.bb-draugr-dark {
  position: relative;
  overflow: hidden;
  border-top: 1px solid var(--bb-draugr-accent-line);
  border-bottom: 1px solid var(--bb-draugr-accent-line);
  background: radial-gradient(circle at 80% 45%, var(--bb-draugr-accent-soft), transparent 28%), color-mix(in srgb, var(--bb-theme-on-dark) 2%, var(--bb-dark));
}

.bb-draugr-dark-copy {
  color: var(--bb-draugr-ink);
}

.bb-draugr-dark-copy h1,
.bb-draugr-dark-copy h2,
.bb-draugr-dark-copy h3,
.bb-draugr-dark-copy h4,
.bb-draugr-dark-copy h5,
.bb-draugr-dark-copy h6 {
  color: var(--bb-draugr-ink);
}

.bb-draugr-dark-copy p,
.bb-draugr-dark-copy li {
  color: var(--bb-draugr-muted);
  line-height: var(--bb-line-height-loose);
}

.bb-draugr-highlight-visual {
  position: relative;
  min-height: 31rem;
  border: 1px solid var(--bb-draugr-line-strong);
  border-radius: var(--bb-radius-2xl);
  background: var(--bb-draugr-soft);
}

.bb-draugr-highlight-ring {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 18rem;
  height: 18rem;
  transform: translate(-50%, -50%);
  border: 1px solid var(--bb-draugr-accent-line);
  border-radius: var(--bb-radius-pill);
}

.bb-draugr-highlight-ring::before,
.bb-draugr-highlight-ring::after {
  content: "";
  position: absolute;
  border: 1px solid var(--bb-draugr-line);
  border-radius: var(--bb-radius-pill);
}

.bb-draugr-highlight-ring::before {
  inset: 2rem;
}

.bb-draugr-highlight-ring::after {
  inset: 4rem;
}

.bb-draugr-highlight-core {
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  place-items: center;
  width: 8rem;
  height: 8rem;
  transform: translate(-50%, -50%);
  color: var(--bb-dark);
  background: var(--bb-draugr-accent);
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-extrabold);
  text-align: center;
  box-shadow: 0 0 0 0.75rem var(--bb-draugr-accent-soft);
}

.bb-draugr-highlight-card {
  position: absolute;
  width: 12rem;
  padding: 1rem;
  border: 1px solid var(--bb-draugr-line);
  border-radius: var(--bb-radius-lg);
  background: color-mix(in srgb, var(--bb-theme-on-dark) 5%, var(--bb-dark));
}

.bb-draugr-highlight-card strong,
.bb-draugr-highlight-card span {
  display: block;
}

.bb-draugr-highlight-card strong {
  margin-bottom: var(--bb-space-2);
  color: var(--bb-draugr-ink);
  font-size: var(--bb-fs-sm);
}

.bb-draugr-highlight-card span {
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-xs);
  line-height: var(--bb-line-height-content);
}

.bb-draugr-highlight-card-1 {
  top: 1.5rem;
  left: 1.5rem;
}

.bb-draugr-highlight-card-2 {
  top: 2.5rem;
  right: 1.5rem;
}

.bb-draugr-highlight-card-3 {
  bottom: 1.5rem;
  left: 2.5rem;
}

.bb-draugr-highlight-card-4 {
  right: 1.5rem;
  bottom: 2.5rem;
}

/* =====================================
   Difference cards
===================================== */
.bb-draugr-difference-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--bb-space-3);
}

.bb-draugr-difference-card {
  min-height: 13rem;
  padding: 1.5rem;
  border-top: 1px solid var(--bb-draugr-accent);
  background: var(--bb-draugr-soft);
}

.bb-draugr-difference-card h3 {
  margin-bottom: var(--bb-space-3);
  font-size: var(--bb-fs-lg);
}

.bb-draugr-difference-card p {
  margin: 0;
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

/* =====================================
   Pricing
===================================== */
.bb-draugr-pricing-section {
  border-top: 1px solid var(--bb-draugr-line);
  border-bottom: 1px solid var(--bb-draugr-line);
  background: color-mix(in srgb, var(--bb-theme-on-dark) 2%, var(--bb-dark));
}

.bb-draugr-pricing-head {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(18rem, 0.45fr);
  gap: clamp(2rem, 6vw, 6rem);
  align-items: end;
  margin-bottom: clamp(2.5rem, 5vw, 4rem);
}

.bb-draugr-pricing-note {
  margin: 0;
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-md);
  line-height: var(--bb-line-height-loose);
}

.bb-draugr-plans-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid var(--bb-draugr-line-strong);
  border-bottom: 1px solid var(--bb-draugr-line-strong);
}

.bb-draugr-plan-card {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 34rem;
  padding: 2rem;
  border-right: 1px solid var(--bb-draugr-line);
  background: transparent;
}

.bb-draugr-plan-card:last-child {
  border-right: 0;
}

.bb-draugr-plan-card.is-featured {
  background: var(--bb-draugr-soft-strong);
  box-shadow: inset 0 0.125rem 0 var(--bb-draugr-accent);
}

.bb-draugr-plan-badge {
  width: fit-content;
  margin-bottom: var(--bb-space-4);
  color: var(--bb-draugr-accent);
  font-family: var(--bb-font-mono);
  font-size: var(--bb-fs-2xs);
  font-weight: var(--bb-fw-bold);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.bb-draugr-plan-name {
  margin: 0;
  font-size: var(--bb-fs-2xl);
}

.bb-draugr-plan-summary {
  min-height: 3rem;
  margin-top: var(--bb-space-3);
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

.bb-draugr-plan-price {
  margin: 2rem 0;
  color: var(--bb-draugr-ink);
  font-size: clamp(2.25rem, 4vw, 3.5rem);
  font-weight: var(--bb-fw-extrabold);
  letter-spacing: -0.045em;
}

.bb-draugr-plan-price small {
  margin-left: var(--bb-space-2);
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-normal);
  letter-spacing: normal;
}

.bb-draugr-plan-action {
  margin-bottom: 1.75rem;
}

.bb-draugr-plan-action .btn {
  width: 100%;
}

.bb-draugr-plan-features {
  display: grid;
  gap: var(--bb-space-3);
  margin: 0;
  padding: 1.5rem 0 0;
  border-top: 1px solid var(--bb-draugr-line);
  list-style: none;
}

.bb-draugr-plan-features li {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: var(--bb-space-2);
  color: var(--bb-draugr-muted);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

.bb-draugr-plan-features .material-symbols-outlined {
  margin-top: 0.125rem;
  color: var(--bb-draugr-accent);
  font-size: var(--bb-fs-base);
}

.bb-draugr-plan-features strong {
  color: var(--bb-draugr-ink);
  font-weight: var(--bb-fw-semibold);
}

/* =====================================
   Banner / FAQ / final CTA
===================================== */
.bb-draugr-banner-section {
  padding-bottom: 0;
}

.bb-draugr-faq-section {
  border-top: 1px solid var(--bb-draugr-line);
}

.bb-draugr-faq-layout {
  display: grid;
  grid-template-columns: minmax(18rem, 0.55fr) minmax(0, 1fr);
  gap: clamp(2rem, 7vw, 7rem);
  align-items: start;
}

.bb-draugr-faq-intro {
  position: sticky;
  top: 2rem;
}

.bb-draugr-faq-intro p {
  max-width: 28rem;
  margin: 1rem 0 0;
  color: var(--bb-draugr-muted);
  line-height: var(--bb-line-height-loose);
}

.bb-draugr-faq-shell .bb-accordion {
  border-top: 1px solid var(--bb-draugr-line-strong);
}

.bb-draugr-faq-shell .accordion-item {
  color: var(--bb-draugr-ink);
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--bb-draugr-line-strong);
  border-radius: 0;
}

.bb-draugr-faq-shell .accordion-button {
  min-height: 5rem;
  padding: 1.25rem 0;
  color: var(--bb-draugr-ink);
  background: transparent;
  border: 0;
  box-shadow: none;
  font-size: var(--bb-fs-lg);
  font-weight: var(--bb-fw-semibold);
}

.bb-draugr-faq-shell .accordion-button:not(.collapsed) {
  color: var(--bb-draugr-accent);
  background: transparent;
  box-shadow: none;
}

.bb-draugr-faq-shell .accordion-button::after {
  display: none;
}

.bb-draugr-faq-shell .bb-accordion-icon {
  color: var(--bb-draugr-accent);
  transition: transform 0.2s ease;
}

