}

.bb-brand-nav-title {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-base);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-base);
}

.bb-brand-nav-title > .material-symbols-outlined {
