  width: 2.75rem;
  height: 2.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: color-mix(in srgb, var(--bb-primary) 54%, var(--bb-dark));
  background-color: color-mix(in srgb, var(--bb-primary) 15%, var(--bb-white));
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-primary) 16%, var(--bb-border-color));
