  font-size: var(--bb-icon-size-lg);
  line-height: 1;
}

.bb-brand-nav-subtitle {
  display: block;
  margin-top: 0.2rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
  line-height: var(--bb-line-height-base);
}

.bb-brand-nav-total {
  min-height: 2rem;
  padding: 0.35rem 0.875rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-heading-color);
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 76%, transparent);
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
  white-space: nowrap;
}

.bb-brand-nav-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.75rem;
}

.bb-brand-nav-item {
  min-height: 7rem;
  padding: 1rem;
  display: grid;
  place-items: center;
  gap: 0.75rem;
  color: var(--bb-heading-color);
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 82%, transparent);
  border-radius: var(--bb-radius-xl);
  text-align: center;
  text-decoration: none !important;
  transition: transform var(--bb-transition-normal), border-color var(--bb-transition-normal), background-color var(--bb-transition-normal), box-shadow var(--bb-transition-normal);
}

.bb-brand-nav-item:hover {
  transform: translateY(-2px);
  color: var(--bb-heading-color);
  background-color: var(--bb-body-bg);
  border-color: color-mix(in srgb, var(--bb-brand-accent, var(--bb-primary)) 32%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-sm);
}

.bb-brand-nav-icon {
  width: 2.75rem;
  height: 2.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-secondary-color);
  background-color: var(--bb-tertiary-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 72%, transparent);
  border-radius: var(--bb-radius-lg);
}

.bb-brand-nav-icon .material-symbols-outlined {
  color: currentColor;
  font-size: var(--bb-icon-size-lg);
  line-height: 1;
}

.bb-brand-nav-text {
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-base);
}

/* =====================================
   Brand Sections
===================================== */
.bb-brand-section {
  padding-top: 1.75rem;
  scroll-margin-top: 6.875rem;
}

.bb-brand-section + .bb-brand-section {
  margin-top: 1.25rem;
}

.bb-brand-section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1.125rem;
  margin-bottom: 1.125rem;
}

.bb-brand-section-head-left {
  min-width: 0;
  max-width: 47.5rem;
}

.bb-brand-section-label {
  gap: 0.4375rem;
  margin-bottom: 0.625rem;
  color: var(--bb-brand-success, var(--bb-success));
  background-color: var(--bb-brand-success-soft, color-mix(in srgb, var(--bb-success) 12%, var(--bb-white)));
}

.bb-brand-section-label .material-symbols-outlined {
  color: currentColor;
  font-size: var(--bb-fs-base);
  line-height: 1;
}

.bb-brand-section-title {
  margin-bottom: 0.5rem;
  color: var(--bb-heading-color);
  font-size: clamp(1.65rem, 3vw, 2.35rem);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: var(--bb-letter-spacing-tight, -0.035em);
}

.bb-brand-section-subtitle {
  max-width: 47.5rem;
  margin-bottom: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-base);
  line-height: var(--bb-line-height-content);
}

.bb-brand-section-count {
  min-height: 2.375rem;
  min-width: 3.625rem;
  padding: 0 0.8125rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-heading-color);
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-brand-border, var(--bb-border-color));
  border-radius: var(--bb-radius-pill);
  box-shadow: var(--bb-shadow-xs);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
  white-space: nowrap;
}

/* =====================================
   Brand Cards
===================================== */
.bb-brand-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.875rem;
}

.bb-brand-card {
  position: relative;
  overflow: hidden;
  display: block;
  height: 100%;
  padding: 0.8125rem;
  color: inherit;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-brand-border, var(--bb-border-color));
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-xs);
  text-decoration: none !important;
  transition: transform var(--bb-transition-normal), box-shadow var(--bb-transition-normal), border-color var(--bb-transition-normal);
}

.bb-brand-card:hover {
  transform: translateY(-4px);
  color: inherit;
  border-color: color-mix(in srgb, var(--bb-brand-accent, var(--bb-primary)) 46%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-sm);
}

.bb-brand-card-visual {
  height: 7.75rem;
  margin-bottom: 0.75rem;
  padding: 1rem;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 92% 10%, color-mix(in srgb, var(--bb-brand-accent, var(--bb-primary)) 10%, transparent) 0, transparent 34%), var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-brand-border-soft, var(--bb-border-color));
  border-radius: var(--bb-radius-xl);
}

.bb-brand-card-visual img {
  max-width: 100%;
  max-height: 4.875rem;
  display: block;
  object-fit: contain;
  transition: transform var(--bb-transition-normal);
}

.bb-brand-card:hover .bb-brand-card-visual img {
  transform: scale(1.045);
}

.bb-brand-card-title {
  display: block;
  min-height: 2.375rem;
  color: var(--bb-heading-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-base);
  text-align: center;
}

.bb-brand-card-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.3125rem;
  margin-top: 0.5rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
}

.bb-brand-card-footer .material-symbols-outlined {
  color: var(--bb-brand-success, var(--bb-success));
  font-size: var(--bb-fs-sm);
  line-height: 1;
}

.bb-brand-extra-item {
  display: none;
}

.bb-brand-extra-item.is-visible {
  display: block;
}

/* =====================================
   Brand More Button
===================================== */
.bb-brand-more-wrap {
  position: relative;
  margin-top: 1.125rem;
  padding: 0.125rem 0 1.125rem;
  text-align: center;
}

.bb-brand-more-wrap::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 1.4375rem;
  height: 1px;
  background-color: var(--bb-brand-border, var(--bb-border-color));
}

.bb-brand-more-btn {
  position: relative;
  z-index: 1;
  min-height: 2.75rem;
  padding: 0 1.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  color: var(--bb-heading-color);
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-brand-border, var(--bb-border-color));
  border-radius: var(--bb-radius-pill);
  box-shadow: var(--bb-shadow-xs);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
  cursor: pointer;
  transition: transform var(--bb-transition-normal), box-shadow var(--bb-transition-normal), border-color var(--bb-transition-normal), background-color var(--bb-transition-normal);
}

.bb-brand-more-btn:hover {
  transform: translateY(-2px);
  background-color: var(--bb-brand-accent-soft, color-mix(in srgb, var(--bb-primary) 12%, var(--bb-white)));
  border-color: color-mix(in srgb, var(--bb-brand-accent, var(--bb-primary)) 46%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-sm);
}

.bb-brand-more-btn .material-symbols-outlined {
  width: 1.375rem;
  height: 1.375rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-heading-color);
  background-color: var(--bb-brand-accent-soft, color-mix(in srgb, var(--bb-primary) 12%, var(--bb-white)));
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-md);
  line-height: 1;
  transition: transform var(--bb-transition-normal);
}

.bb-brand-more-btn:hover .material-symbols-outlined {
  transform: translateY(1px);
}

/* =====================================
   Brand Banner
===================================== */
.bb-brand-banner-shell {
  overflow: hidden;
  border-radius: var(--bb-radius-2xl);
}

/* =====================================
   Brand Responsive
===================================== */
@media (max-width: 1199.98px) {
  .bb-hero.bb-hero-dark.bb-brand-page-hero .bb-brand-page-hero-aside {
    justify-self: start;
  }
  .bb-brand-nav-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .bb-brand-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}
@media (max-width: 991.98px) {
  .bb-brand-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .bb-hero.bb-hero-dark.bb-brand-page-hero .bb-brand-page-hero-card {
    display: none;
  }
  .bb-brand-nav-shell {
    margin-top: -2.75rem;
    padding: 1rem;
    border-radius: var(--bb-radius-xl);
  }
  .bb-brand-nav-head,
  .bb-brand-section-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .bb-brand-nav-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .bb-brand-nav-item {
    min-height: 6.25rem;
  }
  .bb-brand-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.6875rem;
  }
  .bb-brand-card {
    padding: 0.625rem;
    border-radius: var(--bb-radius-xl);
  }
  .bb-brand-card-visual {
    height: 6.75rem;
    padding: 0.8125rem;
    border-radius: var(--bb-radius-lg);
  }
  .bb-brand-card-visual img {
    max-height: 4.25rem;
  }
}
@media (max-width: 575.98px) {
  .bb-brand-nav-grid {
    grid-template-columns: 1fr;
  }
}
