  --bb-brand-detail-card-surface: var(--bb-brand-detail-surface-strong);
  --bb-brand-detail-logo-frame-bg: var(--bb-body-bg);
  --bb-brand-detail-info-head-bg:
      radial-gradient(circle at 92% 10%, color-mix(in srgb, var(--bb-brand-detail-accent) 12%, transparent), transparent 10rem),
      color-mix(in srgb, var(--bb-tertiary-bg) 72%, var(--bb-body-bg));
}

[data-bs-theme=dark] {
  --bb-brand-detail-surface: var(--bb-surface-elevated, var(--bb-body-bg));
  --bb-brand-detail-surface-soft: color-mix(in srgb, var(--bb-tertiary-bg) 72%, var(--bb-body-bg));
  --bb-brand-detail-surface-strong: color-mix(in srgb, var(--bb-surface-elevated, var(--bb-body-bg)) 96%, var(--bb-white, #fff) 4%);
  --bb-brand-detail-border: color-mix(in srgb, var(--bb-border-color) 84%, transparent);
  --bb-brand-detail-accent-soft: color-mix(in srgb, var(--bb-primary) 17%, var(--bb-body-bg));
  --bb-brand-detail-accent-text: color-mix(in srgb, var(--bb-primary) 88%, var(--bb-emphasis-color));
  --bb-brand-detail-success-soft: color-mix(in srgb, var(--bb-success) 16%, var(--bb-body-bg));
  --bb-brand-detail-success-text: color-mix(in srgb, var(--bb-success) 86%, var(--bb-emphasis-color));
  --bb-brand-detail-info-soft: color-mix(in srgb, var(--bb-info) 15%, var(--bb-body-bg));
  --bb-brand-detail-info-text: color-mix(in srgb, var(--bb-info) 86%, var(--bb-emphasis-color));
  --bb-brand-detail-shadow:
      0 1.25rem 3.25rem color-mix(in srgb, var(--bb-black, #000) 24%, transparent),
      0 0.125rem 0.375rem color-mix(in srgb, var(--bb-black, #000) 12%, transparent);
  --bb-brand-detail-shadow-soft:
