  --bb-brand-detail-info-head-bg:
      radial-gradient(circle at 92% 10%, color-mix(in srgb, var(--bb-brand-detail-accent) 15%, transparent), transparent 10rem),
      color-mix(in srgb, var(--bb-tertiary-bg) 72%, var(--bb-body-bg));
