.bb-rfq-create-actions .btn:hover {
  color: var(--bb-primary-inverse) !important;
  background: linear-gradient(180deg, var(--bb-primary) 0%, color-mix(in srgb, var(--bb-primary) 86%, var(--bb-dark)) 100%) !important;
