    grid-template-columns: 1fr;
  }
  .bb-banner-picture.is-secondary {
    transform: none;
  }
  .bb-banner-actions,
  .bb-banner-type-3-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .bb-banner-actions .btn,
  .bb-banner-type-3-actions .btn {
