  color: var(--bb-emphasis-color);
  font-size: clamp(1.75rem, 3vw, 2.35rem);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-tight);
  letter-spacing: var(--bb-letter-spacing-tight, -0.04em);
}

.bb-community-create-text {
  max-width: 42rem;
