  line-height: 1;
}

.bb-community-create-guide-body {
  padding: 1rem;
}

.bb-community-create-guide-eyebrow {
  display: block;
  margin-bottom: 0.35rem;
  color: var(--bb-primary);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
