  flex: 0 0 auto;
  width: 2.25rem;
  height: 2.25rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-primary);
  background-color: color-mix(in srgb, var(--bb-primary) 8%, var(--bb-surface-elevated));
  border-radius: var(--bb-radius);
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-community-create-helper span:last-child {
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
}

/* Info grid */
.bb-community-create-info-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.625rem;
}

.bb-community-create-info-item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.375rem;
  min-height: 2.75rem;
  padding: 0.625rem;
  color: var(--bb-secondary-color);
  background-color: var(--bb-tertiary-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 80%, transparent);
  border-radius: var(--bb-radius);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  text-align: center;
}

.bb-community-create-info-item .material-symbols-outlined {
  color: var(--bb-primary);
  font-size: var(--bb-fs-base);
  line-height: 1;
}

/* Actions */
.bb-community-create-actions {
  display: flex;
  justify-content: flex-end;
  padding-top: 1rem;
  border-top: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 80%, transparent);
}

.bb-community-create-actions .btn {
  min-height: 2.875rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.375rem;
  min-width: 11rem;
  color: var(--bb-primary-inverse) !important;
  background-color: var(--bb-primary) !important;
  border-color: var(--bb-primary) !important;
  border-radius: var(--bb-radius-pill);
  font-weight: var(--bb-fw-bold);
}

.bb-community-create-actions .btn .material-symbols-outlined {
  font-size: var(--bb-fs-md);
  line-height: 1;
}

/* Result */
.bb-community-create-result-card {
  padding: clamp(2rem, 4vw, 3rem) 1.5rem;
  text-align: center;
  background: radial-gradient(circle at top right, color-mix(in srgb, var(--bb-success) 8%, transparent), transparent 32%), var(--bb-body-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 80%, transparent);
  border-radius: var(--bb-radius-xl);
  box-shadow: 0 1.25rem 3.25rem rgba(15, 23, 42, 0.05), 0 0.125rem 0.375rem rgba(15, 23, 42, 0.03);
}

.bb-community-create-result-icon {
  width: 4.75rem;
  height: 4.75rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  color: var(--bb-success);
  background-color: color-mix(in srgb, var(--bb-success) 8%, var(--bb-white));
  border-radius: 50%;
}

.bb-community-create-result-icon .material-symbols-outlined {
  font-size: var(--bb-icon-size-3xl);
  line-height: 1;
}

.bb-community-create-result-card h2 {
  margin: 0;
  color: var(--bb-emphasis-color);
  font-size: clamp(1.375rem, 3vw, 1.75rem);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: -0.025em;
}

.bb-community-create-result-card p {
  max-width: 34rem;
  margin: 0.625rem auto 1.25rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

/* LayoutLight width discipline */
.bb-layout-light-page:has(.bb-community-create-page) .bb-layout-light-content-col {
  width: 100%;
  max-width: 62rem;
  flex: 0 0 auto;
}

.bb-layout-light-page:has(.bb-community-create-page) .bb-layout-light-card {
  width: 100%;
  max-width: 62rem;
  margin-left: auto;
  margin-right: auto;
  border-color: color-mix(in srgb, var(--bb-border-color) 72%, transparent);
  box-shadow: 0 1.5rem 4rem rgba(15, 23, 42, 0.06), 0 0.125rem 0.375rem rgba(15, 23, 42, 0.03);
}

.bb-layout-light-page:has(.bb-community-create-page) .bb-layout-light-card-body {
  padding: clamp(1.5rem, 4vw, 2.25rem);
}

/* Responsive */
@media (max-width: 991.98px) {
  .bb-community-create-layout {
    grid-template-columns: 1fr;
  }
  .bb-community-create-guide-card {
    position: static;
  }
}
@media (max-width: 767.98px) {
  .bb-community-create-form-card,
  .bb-community-create-guide-card,
  .bb-community-create-result-card {
    border-radius: var(--bb-radius-lg);
  }
  .bb-community-create-info-grid {
    grid-template-columns: 1fr;
  }
  .bb-community-create-actions {
    justify-content: stretch;
  }
  .bb-community-create-actions .btn {
    width: 100%;
    border-radius: var(--bb-radius);
  }
}
.bb-b2b-home {
  --bb-b2b-primary: var(--bb-primary, #155eef);
  --bb-b2b-primary-dark: #0f2747;
  --bb-b2b-primary-deep: #123764;
  --bb-b2b-primary-soft: #eef4ff;
  --bb-b2b-primary-soft-2: #f5f8ff;
  --bb-b2b-ink: var(--bb-text, #101828);
  --bb-b2b-muted: var(--bb-text-muted, #667085);
  --bb-b2b-border: var(--bb-border-color, #e4e7ec);
  --bb-b2b-surface: var(--bb-surface, #ffffff);
  --bb-b2b-surface-soft: var(--bb-surface-soft, #f7f9fc);
  --bb-b2b-yellow: var(--bb-warning, #f7c600);
  --bb-b2b-radius-md: var(--bb-radius-md, 16px);
  --bb-b2b-radius-lg: var(--bb-radius-lg, 22px);
  --bb-b2b-radius-xl: var(--bb-radius-xl, 28px);
  --bb-b2b-shadow-soft: var(--bb-shadow-sm, 0 10px 24px rgba(16, 24, 40, 0.05));
  --bb-b2b-shadow-card: var(--bb-shadow-md, 0 12px 28px rgba(16, 24, 40, 0.07));
  background: radial-gradient(circle at top left, rgba(21, 94, 239, 0.055), transparent 34%), var(--bb-b2b-surface);
  color: var(--bb-b2b-ink);
  padding-bottom: 64px;
}

.bb-b2b-home-hero-section {
  padding-top: 16px;
}

.bb-b2b-banner-wrap {
  padding-top: 4px;
}

/* =====================================
   B2B Feature Band
   Slider bottom info band
   Token-driven | Dark/Light compatible
===================================== */
.bb-b2b-feature-band {
  --bb-b2b-feature-band-bg: var(--bb-home-hero-slide-bg, #0f3b74);
  --bb-b2b-feature-band-text: var(--bb-white, #ffffff);
  --bb-b2b-feature-band-muted: color-mix(in srgb, var(--bb-white, #ffffff) 76%, transparent);
  --bb-b2b-feature-band-border: color-mix(in srgb, var(--bb-white, #ffffff) 12%, transparent);
  --bb-b2b-feature-band-icon-bg: color-mix(in srgb, var(--bb-white, #ffffff) 10%, transparent);
  --bb-b2b-feature-band-icon-border: color-mix(in srgb, var(--bb-white, #ffffff) 14%, transparent);
  --bb-b2b-feature-band-icon-color: var(--bb-primary);
  position: relative;
  margin-top: 1.5rem;
  padding: clamp(1.25rem, 2.4vw, 1.75rem);
  overflow: hidden;
  color: var(--bb-b2b-feature-band-text);
  background: radial-gradient(circle at 82% 28%, rgba(123, 90, 255, 0.16), transparent 28%), radial-gradient(circle at 18% 85%, rgba(255, 212, 0, 0.08), transparent 22%), var(--bb-b2b-feature-band-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-primary) 14%, var(--bb-b2b-feature-band-border));
  border-radius: var(--bb-b2b-radius-xl, var(--bb-radius-2xl));
  box-shadow: 0 1.5rem 3.75rem color-mix(in srgb, var(--bb-black, #000000) 18%, transparent), 0 0.25rem 1rem color-mix(in srgb, var(--bb-black, #000000) 10%, transparent);
}

.bb-b2b-feature-band::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, color-mix(in srgb, var(--bb-white, #ffffff) 9%, transparent), transparent 48%);
  opacity: 0.7;
}

.bb-b2b-feature-band-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(1rem, 2.5vw, 2rem);
  align-items: start;
}

.bb-b2b-feature-item {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 0.875rem;
}

.bb-b2b-feature-icon {
  width: 3.125rem;
  height: 3.125rem;
  min-width: 3.125rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-b2b-feature-band-icon-color);
  background-color: var(--bb-b2b-feature-band-icon-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-feature-band-icon-border);
  border-radius: var(--bb-radius-xl);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 18%, transparent), 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-black, #000000) 12%, transparent);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.bb-b2b-feature-icon .material-symbols-outlined {
  color: currentColor;
  font-size: 1.75rem;
  line-height: 1;
  font-variation-settings: "FILL" 0, "wght" 560, "GRAD" 0, "opsz" 28;
}

.bb-b2b-feature-content {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.bb-b2b-feature-title {
  display: block;
  margin-bottom: 0.3125rem;
  color: var(--bb-b2b-feature-band-text);
  font-size: var(--bb-fs-base);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: var(--bb-letter-spacing-tight, -0.015em);
}

.bb-b2b-feature-text {
  display: block;
  color: var(--bb-b2b-feature-band-muted);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-medium);
  line-height: var(--bb-line-height-content);
}

.bb-b2b-feature-separator {
  display: none;
}

/* Dark */
[data-bs-theme=dark] .bb-b2b-feature-band {
  --bb-b2b-feature-band-bg: color-mix(in srgb, #0f3b74 74%, var(--bb-body-bg));
  --bb-b2b-feature-band-muted: color-mix(in srgb, var(--bb-white, #ffffff) 72%, transparent);
  --bb-b2b-feature-band-icon-bg: color-mix(in srgb, var(--bb-white, #ffffff) 8%, transparent);
  --bb-b2b-feature-band-icon-border: color-mix(in srgb, var(--bb-white, #ffffff) 10%, transparent);
  box-shadow: 0 1.5rem 3.75rem color-mix(in srgb, var(--bb-black, #000000) 38%, transparent), 0 0.25rem 1rem color-mix(in srgb, var(--bb-black, #000000) 22%, transparent);
}

/* Responsive */
@media (max-width: 1199.98px) {
  .bb-b2b-feature-band-inner {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .bb-b2b-feature-band {
    padding: 1rem;
    border-radius: var(--bb-radius-xl);
  }
  .bb-b2b-feature-band-inner {
    grid-template-columns: minmax(0, 1fr);
    gap: 1rem;
  }
  .bb-b2b-feature-item {
    gap: 0.75rem;
  }
  .bb-b2b-feature-icon {
    width: 2.75rem;
    height: 2.75rem;
    min-width: 2.75rem;
  }
  .bb-b2b-feature-icon .material-symbols-outlined {
    font-size: 1.5rem;
  }
  .bb-b2b-feature-title {
    font-size: var(--bb-fs-sm);
  }
  .bb-b2b-feature-text {
    font-size: var(--bb-fs-xs);
  }
}
/* Shared Section Header Compatibility */
.bb-b2b-section {
  padding-top: 34px;
}

.bb-b2b-section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 18px;
}

.bb-b2b-section-head-left {
  max-width: 880px;
}

.bb-b2b-section-title {
  font-size: clamp(28px, 3vw, 38px);
  line-height: 1.08;
  font-weight: var(--bb-fw-bold);
  color: var(--bb-b2b-ink);
  margin-bottom: 0.45rem;
}

.bb-b2b-section-text {
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-loose);
  color: var(--bb-b2b-muted);
  margin-bottom: 0;
}

.bb-b2b-section-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.75rem 1.15rem;
  border-radius: var(--bb-radius-pill);
  background: var(--bb-b2b-primary-dark);
  color: #ffffff !important;
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  text-decoration: none !important;
  box-shadow: var(--bb-b2b-shadow-soft);
  transition: transform 0.18s ease, box-shadow 0.18s ease, background-color 0.18s ease;
}

.bb-b2b-section-link:hover {
  color: #ffffff !important;
  transform: translateY(-1px);
  box-shadow: var(--bb-b2b-shadow-card);
}

/* Existing Product Grid Compatibility */
.bb-b2b-products-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 16px;
}

.bb-b2b-product-card {
  display: block;
  color: inherit;
  text-decoration: none !important;
}

.bb-b2b-product-box {
  height: 100%;
  overflow: hidden;
  border: 1px solid rgba(228, 231, 236, 0.86);
  border-radius: var(--bb-b2b-radius-lg);
  background: var(--bb-b2b-surface);
  box-shadow: var(--bb-b2b-shadow-soft);
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.bb-b2b-product-card:hover .bb-b2b-product-box {
  transform: translateY(-2px);
  border-color: rgba(21, 94, 239, 0.18);
  box-shadow: var(--bb-b2b-shadow-card);
}

.bb-b2b-product-media {
  position: relative;
  aspect-ratio: 1/1;
  overflow: hidden;
  background: linear-gradient(180deg, rgba(238, 244, 255, 0.55), rgba(255, 255, 255, 0.96));
}

.bb-b2b-product-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
}

.bb-b2b-product-card:hover .bb-b2b-product-media img {
  transform: scale(1.045);
}

.bb-b2b-product-body {
  padding: 0.8125rem 13px 15px;
}

.bb-b2b-product-name {
  display: block;
  min-height: 38px;
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
  font-weight: var(--bb-fw-bold);
  color: var(--bb-b2b-ink);
  margin-bottom: 0.45rem;
}

.bb-b2b-product-price {
  display: block;
  font-size: var(--bb-icon-size-md);
  line-height: var(--bb-line-height-tight);
  font-weight: var(--bb-fw-extrabold);
  color: var(--bb-b2b-primary);
  margin-bottom: 0.35rem;
}

.bb-b2b-product-meta {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.bb-b2b-product-meta span {
  font-size: var(--bb-fs-xs);
  line-height: var(--bb-line-height-base);
  color: var(--bb-b2b-muted);
}

/* Category Group Compatibility */
.bb-b2b-category-group + .bb-b2b-category-group {
  margin-top: 34px;
}

.bb-b2b-category-title-row {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 14px;
}

.bb-b2b-category-title {
  font-size: clamp(22px, 2.2vw, 28px);
  line-height: 1.08;
  font-weight: var(--bb-fw-bold);
  color: var(--bb-b2b-ink);
  margin-bottom: 0.35rem;
}

.bb-b2b-category-text {
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-loose);
  color: var(--bb-b2b-muted);
  margin-bottom: 0;
}

.bb-b2b-rfq-form-title {
  font-size: var(--bb-h3);
  line-height: var(--bb-line-height-tight);
  font-weight: var(--bb-fw-extrabold);
  color: var(--bb-b2b-ink);
  margin-bottom: 1rem;
}

.bb-b2b-form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.875rem;
}

.bb-b2b-form-group {
  margin-bottom: 14px;
}

.bb-b2b-form-control,
.bb-b2b-form-select,
.bb-b2b-form-textarea {
  min-height: 52px;
  border: 1px solid transparent;
  border-radius: var(--bb-radius-xl);
  background-color: #f4f7fb;
  color: #243347;
  font-size: var(--bb-fs-sm);
  box-shadow: none !important;
}

.bb-b2b-form-control,
.bb-b2b-form-select {
  padding-right: 16px;
  padding-left: 16px;
}

.bb-b2b-form-control:focus,
.bb-b2b-form-select:focus,
.bb-b2b-form-textarea:focus {
  border-color: rgba(21, 94, 239, 0.28);
  background-color: var(--bb-surface-elevated);
  box-shadow: 0 0 0 4px rgba(21, 94, 239, 0.08) !important;
}

.bb-b2b-form-textarea {
  min-height: 116px;
  resize: none;
  padding: 14px 16px;
}

/* Stats Band */
.bb-b2b-stats-band {
  width: 100%;
  position: relative;
  overflow: hidden;
  color: var(--bb-white);
  background: radial-gradient(circle at top left, rgba(247, 198, 0, 0.1), transparent 30%), linear-gradient(135deg, var(--bb-b2b-primary-dark) 0%, var(--bb-b2b-primary-deep) 100%);
}

.bb-b2b-stats-band::before {
  content: "";
  position: absolute;
  left: -100px;
  top: -100px;
  width: 16.25rem;
  height: 260px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--bb-white) 4.5%, transparent);
}

.bb-b2b-stats-band::after {
  content: "";
  position: absolute;
  right: -80px;
  bottom: -90px;
  width: 240px;
  height: 240px;
  border-radius: 50%;
  background: rgba(247, 198, 0, 0.1);
}

/* Stats Component Compatibility */
.bb-b2b-stats-wrap {
  position: relative;
  z-index: 2;
  padding-top: 42px;
  padding-bottom: 42px;
}

.bb-b2b-stats-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) repeat(3, minmax(0, 1fr));
  gap: 1.125rem;
  align-items: stretch;
}

.bb-b2b-stats-copy h2 {
  font-size: clamp(34px, 3.4vw, 42px);
  line-height: 1.02;
  font-weight: var(--bb-fw-extrabold);
  color: var(--bb-white);
  margin-bottom: 0.9rem;
  max-width: 520px;
}

.bb-b2b-stats-copy p {
  font-size: var(--bb-fs-sm);
  line-height: 1.85;
  color: color-mix(in srgb, var(--bb-white) 78%, transparent);
  max-width: 560px;
  margin-bottom: 0;
}

.bb-b2b-stat-card {
  min-height: 180px;
  border-radius: var(--bb-b2b-radius-lg);
  background: color-mix(in srgb, var(--bb-white) 7%, transparent);
  padding: 1.375rem;
  backdrop-filter: blur(8px);
  box-shadow: var(--bb-b2b-shadow-soft);
}

.bb-b2b-stat-number {
  display: block;
  font-size: var(--bb-icon-size-4xl);
  line-height: 1;
  font-weight: var(--bb-fw-extrabold);
  color: var(--bb-b2b-yellow);
  margin-bottom: 0.6rem;
}

.bb-b2b-stat-title {
  display: block;
  font-size: var(--bb-fs-md);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-bold);
  color: var(--bb-white);
  margin-bottom: 0.35rem;
}

.bb-b2b-stat-text {
  display: block;
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
  color: rgba(255, 255, 255, 0.76);
}

/* Responsive */
@media (max-width: 1399.98px) {
  .bb-b2b-products-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}
@media (max-width: 1199.98px) {
  .bb-b2b-feature-band-inner {
    flex-wrap: wrap;
    row-gap: 0.875rem;
  }
  .bb-b2b-feature-item {
    flex: 0 0 calc(50% - 9px);
  }
  .bb-b2b-feature-separator {
    display: none;
  }
  .bb-b2b-products-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .bb-b2b-stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .bb-b2b-stats-copy {
    grid-column: span 2;
  }
}
@media (max-width: 991.98px) {
  .bb-b2b-products-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .bb-b2b-home {
    padding-bottom: 44px;
  }
  .bb-b2b-feature-band {
    padding: 16px;
    border-radius: var(--bb-radius-2xl);
  }
  .bb-b2b-feature-band-inner {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }
  .bb-b2b-feature-item {
    flex: 0 0 100%;
  }
  .bb-b2b-products-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
  }
  .bb-b2b-form-row {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .bb-b2b-stats-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2b-stats-copy {
    grid-column: auto;
  }
}
@media (max-width: 575.98px) {
  .bb-b2b-products-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2b-product-media {
    aspect-ratio: 16/10;
  }
}
.bb-b2b-product-list-layout {
  display: grid;
  grid-template-columns: 16.25rem minmax(0, 1fr);
  gap: 1.75rem;
  align-items: start;
}

.bb-b2b-product-list-sidebar,
.bb-b2b-product-list-content {
  min-width: 0;
}

.bb-b2b-product-list-sidebar {
  position: sticky;
  top: 1rem;
}

/* Toolbar */
.bb-b2b-product-list-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.375rem;
  padding: 0.75rem 0.875rem;
  background-color: var(--bb-b2b-list-surface);
  border: var(--bb-border-width) solid var(--bb-b2b-list-border);
  border-radius: var(--bb-b2b-list-radius-lg);
  box-shadow: var(--bb-b2b-list-shadow);
}

.bb-b2b-product-list-toolbar-left,
.bb-b2b-product-list-toolbar-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.bb-b2b-product-list-filter-anchor {
  min-height: 2.5rem;
  border-radius: var(--bb-radius-pill);
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  font-weight: var(--bb-fw-bold);
}

.bb-b2b-product-list-filter-anchor .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2b-product-list-view-switch {
  align-items: center;
  gap: 0.375rem;
}

.bb-b2b-product-list-view-btn {
  width: 2.125rem;
  height: 2.125rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-secondary-color);
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius);
}

.bb-b2b-product-list-view-btn.active {
  color: var(--bb-primary);
  background-color: var(--bb-b2b-list-primary-soft);
  border-color: color-mix(in srgb, var(--bb-primary) 18%, var(--bb-border-color));
}

.bb-b2b-product-list-view-btn .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2b-product-list-sort-form {
  margin: 0;
}

.bb-b2b-product-list-sort-select {
  min-width: 13rem;
  min-height: 2.5rem;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2b-product-list-page-mini {
  align-items: center;
  gap: 0.4375rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
}

.bb-b2b-product-list-page-mini span {
  min-width: 2.375rem;
  height: 2.125rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-emphasis-color);
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius);
}

.bb-b2b-product-list-page-mini a {
  color: var(--bb-emphasis-color);
  text-decoration: none !important;
}

.bb-b2b-product-list-page-mini .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

/* Product grid */
.bb-b2b-product-list-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.125rem;
}

/* Pagination wrapper only */
.bb-b2b-product-list-pagination {
  margin-top: 1.5rem;
  padding: 0.875rem 1.125rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-b2b-list-radius-lg);
  box-shadow: var(--bb-b2b-list-shadow);
}

.bb-b2b-product-list-page-notify {
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-b2b-product-list-pagination-items {
  display: flex;
  justify-content: flex-end;
}

/* Empty */
.bb-b2b-product-list-empty {
  display: grid;
  grid-template-columns: 10rem minmax(0, 1fr);
  gap: 1.75rem;
  align-items: center;
  min-height: 18.75rem;
  padding: 2.125rem;
  background: radial-gradient(circle at top right, color-mix(in srgb, var(--bb-primary) 7%, transparent), transparent 32%), var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-b2b-list-radius-xl);
  box-shadow: var(--bb-b2b-list-shadow);
}

.bb-b2b-product-list-empty-icon {
  width: 9.375rem;
  height: 9.375rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-primary);
  background: linear-gradient(135deg, var(--bb-b2b-list-primary-soft), var(--bb-white));
  border-radius: var(--bb-b2b-list-radius-lg);
}

.bb-b2b-product-list-empty-icon .material-symbols-outlined {
  font-size: var(--bb-icon-size-4xl);
  line-height: 1;
}

.bb-b2b-product-list-empty-copy h1 {
  margin: 0.75rem 0 0.625rem;
  color: var(--bb-emphasis-color);
  font-size: clamp(1.5rem, 3vw, 1.875rem);
  line-height: var(--bb-line-height-heading);
  font-weight: var(--bb-fw-bold);
  letter-spacing: -0.025em;
}

.bb-b2b-product-list-empty-copy p {
  max-width: 47.5rem;
  margin-bottom: 0.75rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-loose);
}

.bb-b2b-product-list-empty-copy ul {
  margin: 0 0 1.125rem;
  padding-left: 1.125rem;
  color: var(--bb-emphasis-color);
}

.bb-b2b-product-list-empty-copy li {
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-loose);
}

.bb-b2b-product-list-empty-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

/* Category info */
.bb-b2b-product-list-category-info-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(18rem, 0.72fr);
  gap: 1.5rem;
  align-items: center;
  padding: 1.5rem;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-b2b-list-radius-xl);
  box-shadow: var(--bb-b2b-list-shadow);
}

.bb-b2b-product-list-category-info-copy h2 {
  margin: 0.75rem 0 0.625rem;
  color: var(--bb-emphasis-color);
  font-size: clamp(1.5rem, 3vw, 2rem);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: -0.025em;
}

.bb-b2b-product-list-category-info-copy p {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-loose);
}

.bb-b2b-product-list-category-info-media {
  overflow: hidden;
  border-radius: var(--bb-b2b-list-radius-lg);
  background-color: var(--bb-tertiary-bg);
}

.bb-b2b-product-list-category-info-media img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

/* Responsive */
@media (max-width: 1399.98px) {
  .bb-b2b-product-list-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 1199.98px) {
  .bb-b2b-product-list-layout {
    grid-template-columns: 1fr;
  }
  .bb-b2b-product-list-sidebar {
    position: static;
  }
}
@media (max-width: 991.98px) {
  .bb-b2b-product-list-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .bb-b2b-product-list-toolbar {
    align-items: stretch;
    flex-direction: column;
  }
  .bb-b2b-product-list-toolbar-left,
  .bb-b2b-product-list-toolbar-right {
    justify-content: space-between;
  }
  .bb-b2b-product-list-category-info-card {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 767.98px) {
  .bb-b2b-product-list-grid {
    gap: 0.75rem;
  }
  .bb-b2b-product-list-pagination {
    align-items: stretch;
    flex-direction: column;
  }
  .bb-b2b-product-list-page-notify {
    text-align: center;
  }
  .bb-b2b-product-list-pagination-items {
    justify-content: center;
  }
  .bb-b2b-product-list-empty {
    grid-template-columns: 1fr;
    padding: 1.375rem;
  }
  .bb-b2b-product-list-empty-icon {
    width: 6.875rem;
    height: 6.875rem;
  }
  .bb-b2b-product-list-empty-icon .material-symbols-outlined {
    font-size: var(--bb-icon-size-4xl);
  }
}
@media (max-width: 575.98px) {
  .bb-b2b-product-list-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2b-product-list-sort-form,
  .bb-b2b-product-list-sort-select {
    width: 100%;
  }
  .bb-b2b-product-list-toolbar-right {
    align-items: stretch;
    flex-direction: column;
  }
}
/* Hero */
.bb-b2b-detail-hero {
  padding: 0.75rem 0 2.25rem;
}

.bb-b2b-detail-product-head {
  margin-bottom: 1.25rem;
}

.bb-b2b-detail-supplier-line {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.625rem;
  padding: 0.8125rem 0.9375rem;
