  background-color: var(--bb-tertiary-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-lg);
}

.bb-b2b-detail-supplier-line-logo {
  width: 2rem;
  height: 2rem;
  min-width: 2rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-primary);
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius);
  overflow: hidden;
  text-decoration: none !important;
}

.bb-b2b-detail-supplier-line-logo img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
}

.bb-b2b-detail-supplier-line-logo .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2b-detail-supplier-line-name {
  color: var(--bb-primary) !important;
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  text-decoration: none !important;
}

.bb-b2b-detail-supplier-line-type {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2b-detail-supplier-line-type::before {
  content: "•";
