.bb-b2b-detail-safe-trading-icon {
  width: 2.25rem;
  height: 2.25rem;
  min-width: 2.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-primary);
  background-color: var(--bb-b2b-detail-primary-soft);
  border-radius: var(--bb-radius);
}

.bb-b2b-detail-safe-trading-icon .material-symbols-outlined {
  font-size: var(--bb-fs-xl);
  line-height: 1;
}

.bb-b2b-detail-safe-trading-copy {
  min-width: 0;
  flex: 1;
}

.bb-b2b-detail-safe-trading-copy strong {
  display: block;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2b-detail-safe-trading-copy small {
  display: block;
  margin-top: 0.125rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  line-height: var(--bb-line-height-base);
}

.bb-b2b-detail-safe-trading-arrow {
  color: var(--bb-secondary-color);
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

/* Sections */
.bb-b2b-detail-section {
  margin-top: 0;
}

.bb-b2b-detail-section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.875rem;
}

.bb-b2b-detail-section-copy {
  max-width: 50rem;
}

.bb-b2b-detail-section-label {
  margin-bottom: 0.625rem;
}

.bb-b2b-detail-section-label .material-symbols-outlined {
  font-size: var(--bb-fs-base);
  line-height: 1;
}

.bb-b2b-detail-section-title {
  margin: 0;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-web-subsection-title-size);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: -0.025em;
}

.bb-b2b-detail-section-card {
  overflow: hidden;
  padding: 1.25rem;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-xl);
  box-shadow: var(--bb-b2b-detail-shadow);
}

.bb-b2b-detail-description {
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-sm);
  line-height: 1.85;
}

.bb-b2b-detail-subsection-title {
  margin: 1.5rem 0 0.875rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-icon-size-md);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2b-detail-data-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  overflow: hidden;
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-lg);
}

.bb-b2b-detail-data-row {
  display: grid;
  grid-template-columns: minmax(8.75rem, 0.9fr) minmax(0, 1.1fr);
  min-height: 2.875rem;
  border-bottom: var(--bb-border-width) solid var(--bb-border-color);
}

.bb-b2b-detail-data-row:nth-last-child(-n+2) {
  border-bottom: 0;
}

.bb-b2b-detail-data-label,
.bb-b2b-detail-data-value {
  padding: 0.75rem 0.8125rem;
  font-size: var(--bb-fs-sm);
  line-height: 1.4;
}

.bb-b2b-detail-data-label {
  color: var(--bb-secondary-color);
  background-color: var(--bb-tertiary-bg);
  border-right: var(--bb-border-width) solid var(--bb-border-color);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2b-detail-data-value {
  color: var(--bb-emphasis-color);
  font-weight: var(--bb-fw-bold);
  overflow-wrap: anywhere;
}

/* Order cards */
.bb-b2b-order-info-stack {
  display: grid;
  gap: 1rem;
}

.bb-b2b-order-info-card {
  padding: 1.125rem;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-xl);
  box-shadow: var(--bb-b2b-detail-shadow);
}

.bb-b2b-order-info-card-head {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.bb-b2b-order-info-icon {
  width: 2.5rem;
  height: 2.5rem;
  min-width: 2.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-primary);
  background-color: var(--bb-b2b-detail-primary-soft);
  border-radius: var(--bb-radius);
}

.bb-b2b-order-info-icon .material-symbols-outlined {
  font-size: var(--bb-fs-xl);
  line-height: 1;
}

.bb-b2b-order-info-card h3 {
  margin: 0 0 0.25rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-base);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2b-order-info-card p {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  line-height: var(--bb-line-height-base);
}

.bb-b2b-order-info-table {
  border-top: var(--bb-border-width) solid var(--bb-border-color);
}

.bb-b2b-order-info-row {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.6875rem 0;
  border-bottom: var(--bb-border-width) solid var(--bb-border-color);
}

.bb-b2b-order-info-row:last-child {
  border-bottom: 0;
}

.bb-b2b-order-info-row span {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
}

.bb-b2b-order-info-row strong {
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  text-align: right;
}

.bb-b2b-leadtime-table {
  overflow: hidden;
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius);
}

.bb-b2b-leadtime-row {
  display: grid;
  grid-template-columns: 1.1fr repeat(4, 1fr);
}

.bb-b2b-leadtime-row span,
.bb-b2b-leadtime-row strong {
  padding: 0.6875rem 0.625rem;
  border-right: var(--bb-border-width) solid var(--bb-border-color);
  border-bottom: var(--bb-border-width) solid var(--bb-border-color);
  font-size: var(--bb-fs-xs);
  line-height: var(--bb-line-height-base);
}

.bb-b2b-leadtime-row span:last-child,
.bb-b2b-leadtime-row strong:last-child {
  border-right: 0;
}

.bb-b2b-leadtime-row:last-child span,
.bb-b2b-leadtime-row:last-child strong {
  border-bottom: 0;
}

.bb-b2b-leadtime-head {
  background-color: var(--bb-tertiary-bg);
}

.bb-b2b-leadtime-head span {
  color: var(--bb-secondary-color);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2b-leadtime-row strong {
  color: var(--bb-emphasis-color);
  font-weight: var(--bb-fw-bold);
}

.bb-b2b-custom-option-list {
  display: grid;
  gap: 0.625rem;
}

.bb-b2b-custom-option {
  padding: 0.75rem;
  background-color: var(--bb-tertiary-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius);
}

.bb-b2b-custom-option span,
.bb-b2b-custom-option strong,
.bb-b2b-custom-option small {
  display: block;
}

.bb-b2b-custom-option span {
  margin-bottom: 0.25rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-b2b-custom-option strong {
  margin-bottom: 0.125rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2b-custom-option small {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
}

.bb-b2b-order-info-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.625rem;
  margin-top: 0.875rem;
}

.bb-b2b-order-info-action {
  min-height: 2.25rem;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
}

.bb-b2b-detail-supplier-card {
  padding: 1.375rem;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-xl);
  box-shadow: var(--bb-b2b-detail-shadow);
}

.bb-b2b-detail-supplier-top {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(16rem, 20rem);
  gap: 1.5rem;
  align-items: start;
}

.bb-b2b-detail-supplier-main {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  min-width: 0;
}

.bb-b2b-detail-supplier-logo {
  width: 4.5rem;
  height: 4.5rem;
  min-width: 4.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-primary);
  background-color: var(--bb-tertiary-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-lg);
  overflow: hidden;
  text-decoration: none !important;
}

.bb-b2b-detail-supplier-logo img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
}

.bb-b2b-detail-supplier-logo .material-symbols-outlined {
  font-size: var(--bb-fs-3xl);
  line-height: 1;
}

.bb-b2b-detail-supplier-info {
  min-width: 0;
}

.bb-b2b-detail-supplier-info h3 {
  margin: 0 0 0.5rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-xl);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  overflow-wrap: anywhere;
}

.bb-b2b-detail-supplier-info h3 a {
  color: inherit;
  text-decoration: none !important;
}

.bb-b2b-detail-supplier-info h3 a:hover {
  color: var(--bb-primary);
}

.bb-b2b-detail-supplier-info p {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
  line-height: var(--bb-line-height-base);
}

.bb-b2b-detail-supplier-trust {
  justify-self: end;
  width: 100%;
}

.bb-b2b-detail-supplier-badges {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 0.875rem;
}

.bb-b2b-detail-supplier-badges span {
  min-height: 1.625rem;
  display: inline-flex;
  align-items: center;
  padding: 0 0.625rem;
  color: var(--bb-secondary-color);
  background-color: var(--bb-tertiary-bg);
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
}

.bb-b2b-detail-supplier-rating {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 0.625rem;
}

.bb-b2b-detail-supplier-rating strong {
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-3xl);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
}

.bb-b2b-detail-supplier-stars {
  display: block;
  color: var(--bb-warning);
  font-size: var(--bb-fs-sm);
  letter-spacing: 0.0625rem;
  line-height: var(--bb-line-height-heading);
}

.bb-b2b-detail-supplier-rating small {
  display: block;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
}

.bb-b2b-detail-company-picture-host {
  margin-top: 1.375rem;
  padding-top: 1.375rem;
  border-top: var(--bb-border-width) solid var(--bb-border-color);
}

.bb-b2b-detail-company-picture-host:empty {
  display: none;
}

.bb-b2b-detail-supplier-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.75rem;
  margin-top: 1.125rem;
}

.bb-b2b-detail-supplier-actions .btn {
  min-height: 2.625rem;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

/* Responsive */
@media (max-width: 1199.98px) {
  .bb-b2b-detail-main-grid {
    grid-template-columns: minmax(0, 1fr) minmax(18rem, 24rem);
    gap: 1.375rem;
  }
}
@media (max-width: 991.98px) {
  .bb-b2b-detail-main-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2b-detail-offer-card {
    position: static;
  }
  .bb-b2b-detail-supplier-top {
    grid-template-columns: 1fr;
  }
  .bb-b2b-detail-supplier-trust {
    justify-self: stretch;
  }
  .bb-b2b-detail-supplier-badges,
  .bb-b2b-detail-supplier-rating {
    justify-content: flex-start;
  }
  .bb-b2b-detail-data-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2b-detail-data-row:nth-last-child(-n+2) {
    border-bottom: var(--bb-border-width) solid var(--bb-border-color);
  }
  .bb-b2b-detail-data-row:last-child {
    border-bottom: 0;
  }
}
@media (max-width: 767.98px) {
  .bb-b2b-detail-hero {
    padding-top: 0.5rem;
  }
  .bb-b2b-detail-product-title {
    font-size: var(--bb-fs-2xl);
  }
  .bb-b2b-detail-section-card,
  .bb-b2b-order-info-card,
  .bb-b2b-detail-supplier-card {
    padding: 1rem;
    border-radius: var(--bb-radius-lg);
  }
  .bb-b2b-detail-data-row {
    grid-template-columns: 1fr;
  }
  .bb-b2b-detail-data-label {
    border-right: 0;
    border-bottom: var(--bb-border-width) solid var(--bb-border-color);
  }
  .bb-b2b-leadtime-row {
    grid-template-columns: 1fr;
  }
  .bb-b2b-leadtime-row span,
  .bb-b2b-leadtime-row strong {
    border-right: 0;
  }
  .bb-b2b-order-info-actions {
    flex-direction: column;
    align-items: stretch;
  }
  .bb-b2b-order-info-action {
    width: 100%;
  }
  .bb-b2b-detail-supplier-actions {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 575.98px) {
  .bb-b2b-detail-offer-meta-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2b-detail-supplier-main {
    gap: 0.75rem;
  }
  .bb-b2b-detail-supplier-logo {
    width: 3.875rem;
    height: 3.875rem;
    min-width: 3.875rem;
  }
  .bb-b2b-detail-supplier-info h3 {
    font-size: var(--bb-icon-size-md);
  }
}
/* =====================================
   B2B Special Category Page
   Scope: category/special.cshtml
   Token-driven | Light/Dark compatible

   Razor roots:
   - .bb-b2b-special-page
   - .bb-b2b-special-hero
   - .bb-b2b-special-quick-nav
   - .bb-b2b-special-products-section
   - .bb-b2b-special-products-grid

   Product cards:
   - Visual card anatomy comes from .bb-product-card
===================================== */
/* =====================================
   Page Root
===================================== */
.bb-b2b-special-page {
  --bb-b2b-special-primary: var(--bb-primary, #155eef);
  --bb-b2b-special-navy: #0f2747;
  --bb-b2b-special-navy-soft: #123b66;
  --bb-b2b-special-yellow: var(--bb-warning, #f7c600);
  --bb-b2b-special-ink: var(--bb-emphasis-color);
  --bb-b2b-special-muted: var(--bb-secondary-color);
  --bb-b2b-special-border: color-mix(
      in srgb,
      var(--bb-border-color) 84%,
      transparent
  );
  --bb-b2b-special-radius-md: var(--bb-radius-xl);
  --bb-b2b-special-radius-lg: var(--bb-radius-2xl);
  --bb-b2b-special-radius-xl: calc(var(--bb-radius-2xl) + 0.25rem);
  --bb-b2b-special-shadow:
      0 0.875rem 2rem color-mix(in srgb, var(--bb-emphasis-color) 6%, transparent);
  --bb-b2b-special-shadow-hover:
      0 1.25rem 3rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent);
  --bb-b2b-special-panel-bg: color-mix(in srgb, var(--bb-surface-elevated) 94%, transparent);
  --bb-b2b-special-panel-border: color-mix(in srgb, var(--bb-border-color) 84%, transparent);
  --bb-b2b-special-panel-shadow:
      0 1.25rem 3rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent),
      inset 0 1px 0 color-mix(in srgb, var(--bb-surface-elevated) 42%, transparent);
  --bb-b2b-special-item-bg: color-mix(in srgb, var(--bb-surface-soft) 74%, var(--bb-body-bg));
  --bb-b2b-special-item-border: color-mix(in srgb, var(--bb-border-color) 86%, transparent);
  --bb-b2b-special-item-hover-bg: var(--bb-surface-elevated);
  --bb-b2b-special-item-hover-border: color-mix(in srgb, var(--bb-b2b-special-primary) 20%, var(--bb-border-color));
  --bb-b2b-special-item-active-bg: color-mix(in srgb, var(--bb-b2b-special-primary) 8%, var(--bb-surface-elevated));
  --bb-b2b-special-item-active-border: color-mix(in srgb, var(--bb-b2b-special-primary) 24%, var(--bb-border-color));
  --bb-b2b-special-icon-color: color-mix(in srgb, var(--bb-b2b-special-primary) 82%, var(--bb-emphasis-color));
  --bb-b2b-special-icon-bg: color-mix(in srgb, var(--bb-b2b-special-primary) 10%, var(--bb-surface-elevated));
  --bb-b2b-special-icon-border: color-mix(in srgb, var(--bb-b2b-special-primary) 12%, var(--bb-border-color));
  --bb-b2b-special-surface-bg: var(--bb-surface-elevated);
  --bb-b2b-special-surface-border: color-mix(in srgb, var(--bb-border-color) 84%, transparent);
  position: relative;
  overflow: hidden;
  background-color: var(--bb-body-bg);
  color: var(--bb-body-color);
}

/* =====================================
   Hero
===================================== */
.bb-b2b-special-hero-label {
  margin-bottom: 1.125rem;
  color: var(--bb-white, #ffffff);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 14%, transparent);
  border-color: color-mix(in srgb, var(--bb-white, #ffffff) 20%, transparent);
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-black, #000000) 10%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 20%, transparent);
}

.bb-b2b-special-hero-label .material-symbols-outlined {
  color: currentColor;
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2b-special-hero-actions .btn-primary {
  color: var(--bb-emphasis-color);
  background-color: var(--bb-b2b-special-yellow);
  border-color: color-mix(in srgb, var(--bb-b2b-special-yellow) 86%, var(--bb-emphasis-color));
  box-shadow: 0 1rem 2rem color-mix(in srgb, var(--bb-b2b-special-yellow) 24%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 24%, transparent);
}

.bb-b2b-special-hero-actions .btn-light {
  color: var(--bb-white, #ffffff);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 13%, transparent);
  border-color: color-mix(in srgb, var(--bb-white, #ffffff) 18%, transparent);
  box-shadow: 0 1rem 2rem color-mix(in srgb, var(--bb-black, #000000) 10%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 14%, transparent);
}

.bb-b2b-special-hero-actions .btn-light:hover,
.bb-b2b-special-hero-actions .btn-light:focus {
  color: var(--bb-white, #ffffff);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 18%, transparent);
}

.bb-b2b-special-hero-visual {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.bb-b2b-special-hero-picture {
  position: relative;
  width: min(100%, 25rem);
  min-height: clamp(15rem, 24vw, 21rem);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(1rem, 2vw, 1.5rem);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-white, #ffffff) 22%, transparent);
  border-radius: var(--bb-radius-2xl);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 11%, transparent);
  box-shadow: 0 1.5rem 3.5rem color-mix(in srgb, var(--bb-black, #000000) 18%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 20%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.bb-b2b-special-hero-picture img {
  display: block;
  max-width: 100%;
  max-height: clamp(14rem, 22vw, 19rem);
  object-fit: contain;
  filter: drop-shadow(0 1.25rem 1.75rem color-mix(in srgb, var(--bb-black, #000000) 18%, transparent));
}

.bb-b2b-special-hero-placeholder {
  width: 6rem;
  height: 6rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-white, #ffffff);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 12%, transparent);
  border-radius: var(--bb-radius-2xl);
}

.bb-b2b-special-hero-placeholder .material-symbols-outlined {
  font-size: 3rem;
  line-height: 1;
}

/* =====================================
   Quick Nav
===================================== */
.bb-b2b-special-quick-nav {
  position: relative;
  z-index: 5;
  margin-top: -2.75rem;
}

.bb-b2b-special-quick-nav-card {
  overflow: hidden;
  padding: clamp(1rem, 2vw, 1.25rem);
  background-color: var(--bb-b2b-special-panel-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-special-panel-border);
  border-radius: var(--bb-b2b-special-radius-xl);
  box-shadow: var(--bb-b2b-special-panel-shadow);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.bb-b2b-special-quick-nav-head {
  margin-bottom: 0.875rem;
}

.bb-b2b-special-quick-nav-eyebrow {
  display: inline-flex;
  margin-bottom: 0.4rem;
  color: var(--bb-b2b-special-primary);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-extrabold);
  line-height: 1;
  letter-spacing: var(--bb-letter-spacing-wide, 0.075em);
  text-transform: uppercase;
}

.bb-b2b-special-quick-nav-title {
  margin: 0;
  color: var(--bb-b2b-special-ink);
  font-size: clamp(var(--bb-fs-base), 1.3vw, var(--bb-fs-xl));
  font-weight: var(--bb-fw-extrabold, 800);
  line-height: var(--bb-line-height-heading);
  letter-spacing: var(--bb-letter-spacing-tight, -0.02em);
}

.bb-b2b-special-quick-nav-list {
  display: flex;
  gap: 0.875rem;
  overflow-x: auto;
  padding-bottom: 0.25rem;
  scrollbar-width: thin;
}

.bb-b2b-special-quick-nav-list::-webkit-scrollbar {
  height: 0.375rem;
}

.bb-b2b-special-quick-nav-list::-webkit-scrollbar-thumb {
  border-radius: var(--bb-radius-pill);
  background-color: color-mix(in srgb, var(--bb-border-color) 72%, var(--bb-secondary-color));
}

.bb-b2b-special-quick-nav-item {
  min-width: 9.5rem;
  min-height: 6rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem;
  color: var(--bb-b2b-special-ink) !important;
  background-color: var(--bb-b2b-special-item-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-special-item-border);
  border-radius: var(--bb-b2b-special-radius-md);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-extrabold);
  line-height: var(--bb-line-height-base);
  text-align: center;
  text-decoration: none !important;
  transition: transform var(--bb-transition-fast), border-color var(--bb-transition-fast), background-color var(--bb-transition-fast), box-shadow var(--bb-transition-fast);
}

.bb-b2b-special-quick-nav-item:hover,
.bb-b2b-special-quick-nav-item:focus {
  transform: translateY(-2px);
  background-color: var(--bb-b2b-special-item-hover-bg);
  border-color: var(--bb-b2b-special-item-hover-border);
  box-shadow: 0 0.875rem 1.75rem color-mix(in srgb, var(--bb-emphasis-color) 7%, transparent);
}

.bb-b2b-special-quick-nav-item.active {
  background-color: var(--bb-b2b-special-item-active-bg);
  border-color: var(--bb-b2b-special-item-active-border);
  box-shadow: 0 0.875rem 1.75rem color-mix(in srgb, var(--bb-b2b-special-primary) 8%, transparent);
}

.bb-b2b-special-quick-nav-icon {
  width: 2.75rem;
  height: 2.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-b2b-special-icon-color);
  background-color: var(--bb-b2b-special-icon-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-special-icon-border);
  border-radius: 1rem;
}

.bb-b2b-special-quick-nav-icon .material-symbols-outlined {
  color: currentColor;
  font-size: 1.5rem;
  line-height: 1;
  font-variation-settings: "FILL" 0, "wght" 500, "GRAD" 0, "opsz" 24;
}

/* =====================================
   Products Section
===================================== */
.bb-b2b-special-products-section {
  padding-top: clamp(2.25rem, 4vw, 3.75rem);
  padding-bottom: clamp(2.25rem, 4vw, 3.75rem);
}

.bb-b2b-special-section-head {
  margin-bottom: clamp(1.25rem, 2vw, 1.5rem);
}

.bb-b2b-special-section-copy {
  max-width: 54rem;
}

.bb-b2b-special-section-label {
  margin-bottom: 0.75rem;
}

.bb-b2b-special-section-label .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2b-special-section-title {
  color: var(--bb-b2b-special-ink);
}

.bb-b2b-special-section-text {
  max-width: 54rem;
  color: var(--bb-b2b-special-muted);
}

/* Product Grid */
.bb-b2b-special-products-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: clamp(0.875rem, 1.25vw, 1.125rem);
  align-items: stretch;
}

.bb-b2b-special-products-grid .bb-product-card {
  height: 100%;
}

/* =====================================
   Pagination
===================================== */
.bb-b2b-special-pagination {
  margin-top: 1.375rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.875rem 1.125rem;
  background-color: var(--bb-b2b-special-surface-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-special-surface-border);
  border-radius: var(--bb-b2b-special-radius-lg);
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-emphasis-color) 5%, transparent);
}

.bb-b2b-special-pagination-summary {
  color: var(--bb-b2b-special-ink);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-b2b-special-pagination-list {
  display: flex;
  justify-content: flex-end;
}

/* =====================================
   Empty State
===================================== */
.bb-b2b-special-empty {
  padding: clamp(2rem, 4vw, 3rem) 1.5rem;
  text-align: center;
  background: radial-gradient(circle at top right, color-mix(in srgb, var(--bb-b2b-special-primary) 7%, transparent), transparent 18rem), var(--bb-b2b-special-surface-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-special-surface-border);
  border-radius: var(--bb-b2b-special-radius-xl);
  box-shadow: 0 0.875rem 2rem color-mix(in srgb, var(--bb-emphasis-color) 6%, transparent);
}

.bb-b2b-special-empty-icon {
  width: 4.25rem;
  height: 4.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.125rem;
  color: var(--bb-b2b-special-primary);
  background-color: color-mix(in srgb, var(--bb-b2b-special-primary) 10%, var(--bb-body-bg));
  border-radius: var(--bb-radius-2xl);
}

.bb-b2b-special-empty-icon .material-symbols-outlined {
  font-size: var(--bb-icon-size-2xl);
  line-height: 1;
}

.bb-b2b-special-empty-title {
  margin: 0 0 0.65rem;
  color: var(--bb-b2b-special-ink);
  font-size: var(--bb-fs-2xl);
  font-weight: var(--bb-fw-extrabold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2b-special-empty-text {
  max-width: 35rem;
  margin: 0 auto 1.25rem;
  color: var(--bb-b2b-special-muted);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

.bb-b2b-special-empty-btn {
  min-height: 2.75rem;
  border-radius: var(--bb-radius-pill);
  font-weight: var(--bb-fw-extrabold);
}

/* =====================================
   Bottom Banner
===================================== */
.bb-b2b-special-bottom-banner {
  padding-top: 0;
  padding-bottom: clamp(2.5rem, 5vw, 4rem);
}

/* =====================================
   Dark tokens
===================================== */
[data-bs-theme=dark] .bb-b2b-special-page {
  --bb-b2b-special-border: color-mix(in srgb, var(--bb-border-color) 74%, transparent);
  --bb-b2b-special-shadow: 0 0.875rem 2rem color-mix(in srgb, var(--bb-black) 22%, transparent);
  --bb-b2b-special-shadow-hover: 0 1.25rem 3rem color-mix(in srgb, var(--bb-black) 28%, transparent);
  --bb-b2b-special-panel-bg: color-mix(in srgb, var(--bb-surface-elevated) 86%, transparent);
  --bb-b2b-special-panel-border: color-mix(in srgb, var(--bb-border-color) 74%, transparent);
  --bb-b2b-special-panel-shadow:
      0 1.25rem 3rem color-mix(in srgb, var(--bb-black) 26%, transparent),
      inset 0 1px 0 color-mix(in srgb, var(--bb-white) 6%, transparent);
  --bb-b2b-special-item-bg: color-mix(in srgb, var(--bb-surface-elevated) 82%, var(--bb-body-bg));
  --bb-b2b-special-item-border: color-mix(in srgb, var(--bb-border-color) 72%, transparent);
  --bb-b2b-special-item-hover-bg: color-mix(in srgb, var(--bb-b2b-special-primary) 14%, var(--bb-surface-elevated));
  --bb-b2b-special-item-hover-border: color-mix(in srgb, var(--bb-b2b-special-primary) 28%, var(--bb-border-color));
  --bb-b2b-special-item-active-bg: var(--bb-b2b-special-item-hover-bg);
  --bb-b2b-special-item-active-border: var(--bb-b2b-special-item-hover-border);
  --bb-b2b-special-icon-color: color-mix(in srgb, var(--bb-white) 86%, var(--bb-b2b-special-primary));
  --bb-b2b-special-icon-bg: color-mix(in srgb, var(--bb-b2b-special-primary) 24%, var(--bb-surface-elevated));
  --bb-b2b-special-icon-border: color-mix(in srgb, var(--bb-b2b-special-primary) 20%, var(--bb-border-color));
  --bb-b2b-special-surface-bg: color-mix(in srgb, var(--bb-surface-elevated) 90%, var(--bb-body-bg));
  --bb-b2b-special-surface-border: color-mix(in srgb, var(--bb-border-color) 74%, transparent);
}

/* =====================================
   Responsive
===================================== */
@media (max-width: 1399.98px) {
  .bb-b2b-special-products-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 1199.98px) {
  .bb-b2b-special-hero-visual {
    justify-content: flex-start;
  }
  .bb-b2b-special-products-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 991.98px) {
  .bb-b2b-special-quick-nav {
    margin-top: -2.125rem;
  }
  .bb-b2b-special-products-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .bb-b2b-special-pagination {
    align-items: stretch;
    flex-direction: column;
  }
  .bb-b2b-special-pagination-summary {
    text-align: center;
  }
  .bb-b2b-special-pagination-list {
    justify-content: center;
  }
}
@media (max-width: 767.98px) {
  .bb-b2b-special-quick-nav {
    margin-top: -1.75rem;
  }
  .bb-b2b-special-quick-nav-card {
    border-radius: var(--bb-radius-2xl);
  }
  .bb-b2b-special-products-section {
    padding-top: 2rem;
    padding-bottom: 2rem;
  }
}
@media (max-width: 575.98px) {
  .bb-b2b-special-products-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2b-special-hero-picture {
    width: 100%;
    min-height: 13rem;
  }
}
/* =====================================
   B2B Category Page
   Scope: category detail page
   Token-driven | Light/Dark compatible

   Razor roots:
   - .bb-b2b-category-hero
   - .bb-b2b-category-quicknav
   - .bb-b2b-category-stage
   - .bb-b2b-category-content-groups
   - .bb-b2b-category-component-host-*
===================================== */
.bb-b2b-category-page {
  --bb-b2b-category-hero-label-bg: color-mix(in srgb, var(--bb-success) 92%, var(--bb-emphasis-color));
  --bb-b2b-category-hero-label-border: color-mix(in srgb, var(--bb-success) 82%, var(--bb-white));
  --bb-b2b-category-hero-tag-color: color-mix(in srgb, var(--bb-emphasis-color) 72%, var(--bb-secondary-color));
  --bb-b2b-category-hero-tag-bg: var(--bb-surface-elevated);
  --bb-b2b-category-hero-tag-border: color-mix(in srgb, var(--bb-border-color) 82%, transparent);
  --bb-b2b-category-hero-tag-icon: var(--bb-emphasis-color);
  --bb-b2b-category-hero-panel-bg: color-mix(in srgb, var(--bb-surface-elevated) 86%, transparent);
  --bb-b2b-category-hero-panel-border: color-mix(in srgb, var(--bb-surface-elevated) 68%, var(--bb-border-color));
  --bb-b2b-category-hero-panel-shadow:
      0 1.25rem 3rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent),
      inset 0 1px 0 color-mix(in srgb, var(--bb-surface-elevated) 46%, transparent);
  --bb-b2b-category-hero-panel-item-bg: color-mix(in srgb, var(--bb-surface-elevated) 94%, var(--bb-body-bg));
  --bb-b2b-category-hero-panel-item-border: color-mix(in srgb, var(--bb-border-color) 82%, transparent);
  --bb-b2b-category-icon-color: color-mix(in srgb, var(--bb-primary) 78%, var(--bb-emphasis-color) 22%);
  --bb-b2b-category-icon-bg: color-mix(in srgb, var(--bb-primary) 14%, var(--bb-surface-elevated));
  --bb-b2b-category-icon-border: color-mix(in srgb, var(--bb-primary) 14%, var(--bb-border-color));
  --bb-b2b-category-icon-shadow: inset 0 1px 0 color-mix(in srgb, var(--bb-surface-elevated) 42%, transparent);
  --bb-b2b-category-stage-bg: color-mix(in srgb, var(--bb-surface-elevated) 96%, var(--bb-body-bg));
  --bb-b2b-category-stage-border: color-mix(in srgb, var(--bb-border-color) 84%, transparent);
  --bb-b2b-category-stage-shadow:
      0 1rem 2.5rem color-mix(in srgb, var(--bb-emphasis-color) 6%, transparent),
      0 0.25rem 0.875rem color-mix(in srgb, var(--bb-emphasis-color) 3%, transparent);
  --bb-b2b-category-stage-soft-bg:
      radial-gradient(circle at 92% 8%, color-mix(in srgb, var(--bb-primary) 8%, transparent), transparent 18rem),
      radial-gradient(circle at 12% 92%, color-mix(in srgb, var(--bb-info) 6%, transparent), transparent 16rem),
      linear-gradient(180deg, color-mix(in srgb, var(--bb-surface-soft) 64%, var(--bb-body-bg)), var(--bb-b2b-category-stage-bg));
  --bb-b2b-category-quicknav-bg: color-mix(in srgb, var(--bb-surface-elevated) 96%, var(--bb-body-bg));
  --bb-b2b-category-quicknav-border: var(--bb-b2b-category-stage-border);
  --bb-b2b-category-quicknav-icon-color: var(--bb-primary-text);
  --bb-b2b-category-quicknav-icon-bg: var(--bb-primary-light);
  --bb-b2b-category-quicknav-icon-border: color-mix(in srgb, var(--bb-primary) 18%, var(--bb-border-color));
  --bb-b2b-category-content-stage-bg:
      radial-gradient(circle at 96% 8%, color-mix(in srgb, var(--bb-primary) 5%, transparent), transparent 16rem),
      linear-gradient(180deg, color-mix(in srgb, var(--bb-surface-elevated) 98%, var(--bb-body-bg)), color-mix(in srgb, var(--bb-surface-soft) 42%, var(--bb-body-bg)));
  --bb-b2b-category-content-stage-border: color-mix(in srgb, var(--bb-border-color) 82%, transparent);
  --bb-b2b-category-content-stage-shadow:
      0 1rem 2.25rem color-mix(in srgb, var(--bb-emphasis-color) 4%, transparent),
      0 0.25rem 0.75rem color-mix(in srgb, var(--bb-emphasis-color) 2%, transparent);
}

[data-bs-theme=dark] .bb-b2b-category-page {
  --bb-b2b-category-hero-label-bg: color-mix(in srgb, var(--bb-success) 78%, var(--bb-emphasis-color));
  --bb-b2b-category-hero-label-border: color-mix(in srgb, var(--bb-success) 54%, var(--bb-border-color));
  --bb-b2b-category-hero-tag-color: var(--bb-emphasis-color);
  --bb-b2b-category-hero-tag-bg: color-mix(in srgb, var(--bb-surface-elevated) 92%, var(--bb-body-bg));
  --bb-b2b-category-hero-tag-border: color-mix(in srgb, var(--bb-border-color) 76%, transparent);
  --bb-b2b-category-hero-tag-icon: var(--bb-body-color);
  --bb-b2b-category-hero-panel-bg: color-mix(in srgb, var(--bb-surface-elevated) 84%, transparent);
  --bb-b2b-category-hero-panel-border: color-mix(in srgb, var(--bb-border-color) 76%, transparent);
  --bb-b2b-category-hero-panel-shadow:
      0 1.25rem 3rem color-mix(in srgb, var(--bb-black) 26%, transparent),
      inset 0 1px 0 color-mix(in srgb, var(--bb-white) 7%, transparent);
  --bb-b2b-category-hero-panel-item-bg: color-mix(in srgb, var(--bb-surface-elevated) 82%, var(--bb-body-bg));
  --bb-b2b-category-hero-panel-item-border: color-mix(in srgb, var(--bb-border-color) 72%, transparent);
  --bb-b2b-category-icon-color: color-mix(in srgb, var(--bb-white) 90%, var(--bb-primary) 10%);
  --bb-b2b-category-icon-bg: color-mix(in srgb, var(--bb-primary) 26%, var(--bb-surface-elevated) 74%);
  --bb-b2b-category-icon-border: color-mix(in srgb, var(--bb-primary) 20%, var(--bb-border-color) 80%);
  --bb-b2b-category-icon-shadow: inset 0 1px 0 color-mix(in srgb, var(--bb-white) 4%, transparent);
  --bb-b2b-category-stage-bg: color-mix(in srgb, var(--bb-surface-elevated) 86%, var(--bb-body-bg));
  --bb-b2b-category-stage-border: color-mix(in srgb, var(--bb-border-color) 74%, transparent);
  --bb-b2b-category-stage-shadow:
      0 1rem 2.5rem color-mix(in srgb, var(--bb-black) 24%, transparent),
      0 0.25rem 0.875rem color-mix(in srgb, var(--bb-black) 14%, transparent);
  --bb-b2b-category-stage-soft-bg:
      radial-gradient(circle at 92% 8%, color-mix(in srgb, var(--bb-primary) 7%, transparent), transparent 18rem),
      radial-gradient(circle at 12% 92%, color-mix(in srgb, var(--bb-info) 6%, transparent), transparent 16rem),
      linear-gradient(180deg, color-mix(in srgb, var(--bb-surface-elevated) 80%, var(--bb-body-bg)), var(--bb-b2b-category-stage-bg));
  --bb-b2b-category-quicknav-bg: color-mix(in srgb, var(--bb-surface-elevated) 90%, var(--bb-body-bg));
  --bb-b2b-category-quicknav-border: color-mix(in srgb, var(--bb-border-color) 74%, transparent);
  --bb-b2b-category-quicknav-icon-color: color-mix(in srgb, var(--bb-primary) 74%, var(--bb-white));
  --bb-b2b-category-quicknav-icon-bg: color-mix(in srgb, var(--bb-primary) 24%, var(--bb-surface-elevated));
  --bb-b2b-category-quicknav-icon-border: color-mix(in srgb, var(--bb-primary) 18%, var(--bb-border-color));
  --bb-b2b-category-content-stage-bg:
      radial-gradient(circle at 96% 8%, color-mix(in srgb, var(--bb-primary) 6%, transparent), transparent 16rem),
      linear-gradient(180deg, color-mix(in srgb, var(--bb-surface-elevated) 82%, var(--bb-body-bg)), color-mix(in srgb, var(--bb-surface-elevated) 88%, var(--bb-body-bg)));
  --bb-b2b-category-content-stage-border: color-mix(in srgb, var(--bb-border-color) 74%, transparent);
  --bb-b2b-category-content-stage-shadow:
      0 1rem 2.25rem color-mix(in srgb, var(--bb-black) 22%, transparent),
      0 0.25rem 0.75rem color-mix(in srgb, var(--bb-black) 12%, transparent);
}

/* =====================================
   Hero
===================================== */
/* Hero label */
.bb-b2b-category-hero-label {
  margin-bottom: 1.125rem;
  color: var(--bb-white, #ffffff);
  background-color: var(--bb-b2b-category-hero-label-bg);
  border-color: var(--bb-b2b-category-hero-label-border);
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-success, #16a34a) 18%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 18%, transparent);
}

.bb-b2b-category-hero-label .material-symbols-outlined {
  color: currentColor;
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

/* Hero actions */
.bb-b2b-category-hero-btn {
  min-height: 3rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  padding-right: 1.25rem;
  padding-left: 1.25rem;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-b2b-category-hero-btn .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2b-category-hero .bb-hero-actions .btn-light {
  color: var(--bb-emphasis-color);
  background-color: var(--bb-b2b-category-hero-tag-bg);
  border-color: var(--bb-b2b-category-hero-tag-border);
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-emphasis-color) 7%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 72%, transparent);
}

.bb-b2b-category-hero .bb-hero-actions .btn-light:hover,
.bb-b2b-category-hero .bb-hero-actions .btn-light:focus {
  color: var(--bb-emphasis-color);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 92%, var(--bb-primary));
  border-color: color-mix(in srgb, var(--bb-primary) 20%, var(--bb-border-color));
}

/* Hero quick chips */
.bb-b2b-category-hero .bb-hero-quick-links {
  margin-top: 1.5rem;
}

.bb-b2b-category-hero-tag {
  color: var(--bb-b2b-category-hero-tag-color);
  background-color: var(--bb-white, #ffffff);
  border-color: color-mix(in srgb, var(--bb-border-color) 82%, transparent);
  font-weight: var(--bb-fw-semibold);
  box-shadow: 0 0.5rem 1.125rem color-mix(in srgb, var(--bb-emphasis-color) 6%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 60%, transparent);
}

.bb-b2b-category-hero-tag .material-symbols-outlined {
  color: var(--bb-b2b-category-hero-tag-icon);
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

/* =====================================
   Hero Quick Panel
===================================== */
.bb-b2b-category-hero .bb-hero-panel {
  position: relative;
  z-index: 2;
  width: 100%;
  max-width: 29rem;
  justify-self: end;
  align-self: center;
  padding: clamp(1rem, 2vw, 1.25rem);
  background-color: var(--bb-b2b-category-hero-panel-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-category-hero-panel-border);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-b2b-category-hero-panel-shadow);
  backdrop-filter: blur(14px);
