  --bb-b2b-featured-picture-bg:
      radial-gradient(
          circle at 42% 34%,
          color-mix(in srgb, var(--bb-surface-elevated) 96%, transparent),
          color-mix(in srgb, var(--bb-primary) 7%, var(--bb-surface-elevated)) 68%,
          color-mix(in srgb, var(--bb-primary) 12%, var(--bb-surface-elevated)) 100%
      );
  --bb-b2b-featured-picture-border: color-mix(in srgb, var(--bb-primary) 12%, var(--bb-border-color));
  --bb-b2b-featured-picture-shadow:
      inset 0 0 0 1px color-mix(in srgb, var(--bb-surface-elevated) 72%, transparent),
      0 1.5rem 3.5rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent);
  --bb-b2b-featured-surface-bg: color-mix(in srgb, var(--bb-surface-elevated) 96%, var(--bb-body-bg));
  --bb-b2b-featured-surface-border: color-mix(in srgb, var(--bb-border-color) 86%, transparent);
  --bb-b2b-featured-list-bg:
      linear-gradient(180deg, var(--bb-body-bg), color-mix(in srgb, var(--bb-tertiary-bg) 44%, var(--bb-body-bg)));
