      radial-gradient(circle at 88% 18%, color-mix(in srgb, var(--bb-primary) 10%, transparent), transparent 20rem),
      radial-gradient(circle at 12% 82%, color-mix(in srgb, var(--bb-info) 8%, transparent), transparent 18rem),
      linear-gradient(180deg, color-mix(in srgb, var(--bb-surface-elevated) 68%, var(--bb-body-bg)), var(--bb-body-bg));
  --bb-b2b-featured-picture-bg:
      radial-gradient(
          circle at 42% 34%,
          color-mix(in srgb, var(--bb-surface-elevated) 94%, var(--bb-body-bg)),
