          color-mix(in srgb, var(--bb-primary) 12%, var(--bb-body-bg)) 100%
      );
  --bb-b2b-featured-picture-border: color-mix(in srgb, var(--bb-primary) 18%, var(--bb-border-color));
  --bb-b2b-featured-picture-shadow:
      inset 0 0 0 1px color-mix(in srgb, var(--bb-white) 8%, transparent),
      0 1.5rem 3.5rem color-mix(in srgb, var(--bb-black) 22%, transparent);
