  height: 2.25rem;
  min-width: 2.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-primary);
  background-color: color-mix(in srgb, var(--bb-primary) 12%, var(--bb-body-bg));
  border-radius: var(--bb-radius-lg);
}

.bb-b2b-featured-products-quicknav-icon .material-symbols-outlined {
  font-size: 1.25rem;
  line-height: 1;
}

/* =====================================
   Product List Section
===================================== */
.bb-b2b-featured-products-list {
  padding-top: clamp(2rem, 4vw, 3.5rem);
  padding-bottom: clamp(2.5rem, 5vw, 4.5rem);
  background: var(--bb-b2b-featured-list-bg);
}

.bb-b2b-featured-products-section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: clamp(1.25rem, 2.5vw, 2rem);
}

.bb-b2b-featured-products-section-copy {
  max-width: 50rem;
  min-width: 0;
}

.bb-b2b-featured-products-section-chip {
  margin-bottom: 0.875rem;
}

.bb-b2b-featured-products-section-chip .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2b-featured-products-section-title {
  margin: 0 0 0.65rem;
  color: var(--bb-emphasis-color);
  font-size: clamp(1.75rem, 3vw, 2.75rem);
  font-weight: var(--bb-fw-extrabold, 800);
  line-height: 1.06;
  letter-spacing: var(--bb-letter-spacing-tight, -0.04em);
}

.bb-b2b-featured-products-section-text {
  max-width: 42rem;
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-base);
  line-height: var(--bb-line-height-content);
}

.bb-b2b-featured-products-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.5rem;
  padding: 0.65rem 1rem;
  color: var(--bb-emphasis-color);
  background-color: var(--bb-b2b-featured-surface-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-featured-surface-border);
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  box-shadow: var(--bb-shadow-xs);
}

/* Grid: global bb-product-card ailesini taşır */
.bb-b2b-featured-products-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: clamp(0.875rem, 1.5vw, 1.125rem);
  align-items: stretch;
}

/* Bu sayfaya özel küçük kart ritmi */
.bb-b2b-featured-products-grid .bb-product-card {
  height: 100%;
}

.bb-b2b-featured-products-grid .bb-product-card-title {
  min-height: 2.6em;
}

.bb-b2b-featured-products-grid .bb-product-card-actions {
  margin-top: auto;
}

/* =====================================
   Pagination
===================================== */
.bb-b2b-featured-products-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-top: clamp(1.5rem, 3vw, 2.25rem);
  padding: 1rem;
  background-color: var(--bb-b2b-featured-surface-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-featured-surface-border);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-xs);
}

.bb-b2b-featured-products-pagination-summary {
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2b-featured-products-pagination-list {
  display: flex;
  align-items: center;
  justify-content: flex-end;
}

/* =====================================
   Empty
===================================== */
.bb-b2b-featured-products-empty {
  max-width: 42rem;
  margin: 0 auto;
  padding: clamp(2rem, 4vw, 3rem);
  text-align: center;
  background-color: var(--bb-b2b-featured-surface-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-featured-surface-border);
  border-radius: var(--bb-radius-2xl);
  box-shadow: 0 1rem 2.5rem color-mix(in srgb, var(--bb-emphasis-color) 6%, transparent), var(--bb-shadow-xs);
}

.bb-b2b-featured-products-empty-icon {
  width: 4.25rem;
  height: 4.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  color: var(--bb-primary);
  background-color: color-mix(in srgb, var(--bb-primary) 12%, var(--bb-body-bg));
  border-radius: var(--bb-radius-2xl);
}

.bb-b2b-featured-products-empty-icon .material-symbols-outlined {
  font-size: 2rem;
  line-height: 1;
}

.bb-b2b-featured-products-empty-title {
  margin: 0 0 0.65rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-2xl);
  font-weight: var(--bb-fw-extrabold, 800);
  line-height: var(--bb-line-height-heading);
}

.bb-b2b-featured-products-empty-text {
  margin: 0 0 1.25rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-base);
  line-height: var(--bb-line-height-content);
}

.bb-b2b-featured-products-empty-btn {
  min-height: 2.875rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding-right: 1.25rem;
  padding-left: 1.25rem;
  border-radius: var(--bb-radius-pill);
  font-weight: var(--bb-fw-bold);
}

/* =====================================
   Bottom Banner
===================================== */
.bb-b2b-featured-products-bottom-banner {
  padding-top: clamp(1.5rem, 3vw, 2.5rem);
  padding-bottom: clamp(2.5rem, 5vw, 4rem);
  background: var(--bb-b2b-featured-bottom-bg);
}

/* =====================================
   Responsive
===================================== */
@media (max-width: 1399.98px) {
  .bb-b2b-featured-products-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 1199.98px) {
  .bb-b2b-featured-products-hero-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2b-featured-products-hero-media {
    display: none;
  }
  .bb-b2b-featured-products-quicknav-card {
    grid-template-columns: 1fr;
  }
  .bb-b2b-featured-products-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 991.98px) {
  .bb-b2b-featured-products-quicknav-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .bb-b2b-featured-products-section-head {
    align-items: flex-start;
    flex-direction: column;
  }
}
@media (max-width: 767.98px) {
  .bb-b2b-featured-products-hero {
    padding-top: 1.75rem;
    padding-bottom: 2.25rem;
  }
  .bb-b2b-featured-products-hero-title {
    font-size: var(--bb-fs-3xl);
    line-height: 1.08;
  }
  .bb-b2b-featured-products-hero-text {
    font-size: var(--bb-fs-sm);
  }
  .bb-b2b-featured-products-hero-actions {
    display: grid;
    grid-template-columns: 1fr;
  }
  .bb-b2b-featured-products-hero-btn {
    width: 100%;
  }
  .bb-b2b-featured-products-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.875rem;
  }
  .bb-b2b-featured-products-pagination {
    align-items: flex-start;
    flex-direction: column;
  }
  .bb-b2b-featured-products-pagination-list {
    width: 100%;
    justify-content: flex-start;
  }
}
@media (max-width: 575.98px) {
  .bb-b2b-featured-products-quicknav-list {
    grid-template-columns: 1fr;
  }
  .bb-b2b-featured-products-grid {
    grid-template-columns: 1fr;
  }
}
/* =====================================
   B2B Home Hero Slider
   Scope: _HomepageB2BSlider
   Token-driven | Light/Dark compatible
===================================== */
[type=button]:not(:disabled),
[type=reset]:not(:disabled),
[type=submit]:not(:disabled),
button:not(:disabled) {
  cursor: pointer;
}

/* Layout */
.bb-b2b-homepage-slider-layout {
  --bb-b2b-slider-carousel-bg:
      radial-gradient(circle at 82% 28%, rgba(123, 90, 255, 0.16), transparent 28%),
      radial-gradient(circle at 18% 85%, rgba(255, 212, 0, 0.08), transparent 22%),
      var(--bb-home-hero-slide-bg, #0f3b74);
  --bb-b2b-slider-carousel-border: color-mix(in srgb, var(--bb-primary) 16%, var(--bb-border-color));
  --bb-b2b-slider-carousel-shadow:
      0 1.5rem 3.5rem color-mix(in srgb, var(--bb-black) 18%, transparent),
      0 0.25rem 1rem color-mix(in srgb, var(--bb-black) 10%, transparent);
  --bb-b2b-slider-picture-bg:
      radial-gradient(
          circle at 42% 34%,
          color-mix(in srgb, var(--bb-surface-elevated) 96%, transparent),
          color-mix(in srgb, var(--bb-primary) 8%, var(--bb-surface-elevated)) 68%,
          color-mix(in srgb, var(--bb-primary) 13%, var(--bb-surface-elevated)) 100%
      );
  --bb-b2b-slider-picture-shadow:
      inset 0 0 0 1px color-mix(in srgb, var(--bb-surface-elevated) 72%, transparent),
      0 1.25rem 3rem color-mix(in srgb, var(--bb-black) 18%, transparent);
  --bb-b2b-slider-dot-bg: color-mix(in srgb, var(--bb-white) 30%, transparent);
  --bb-b2b-slider-dot-active-bg: var(--bb-primary);
  --bb-b2b-slider-dot-active-shadow: 0 0.375rem 1rem color-mix(in srgb, var(--bb-primary) 24%, transparent);
  --bb-b2b-slider-control-color: var(--bb-white);
  --bb-b2b-slider-control-bg: color-mix(in srgb, var(--bb-surface-elevated) 18%, transparent);
  --bb-b2b-slider-control-shadow:
      0 0.75rem 1.75rem color-mix(in srgb, var(--bb-black) 18%, transparent),
      inset 0 0 0 1px color-mix(in srgb, var(--bb-white) 10%, transparent);
  --bb-b2b-slider-control-hover-bg: color-mix(in srgb, var(--bb-surface-elevated) 28%, transparent);
  display: grid;
  grid-template-columns: minmax(0, 1fr) clamp(18rem, 22vw, 21rem);
  gap: 1rem;
  align-items: stretch;
}

.bb-b2b-homepage-slider-carousel {
  position: relative;
  min-width: 0;
  min-height: 28rem;
  overflow: hidden;
  background: var(--bb-b2b-slider-carousel-bg);
  border: var(--bb-border-width) solid var(--bb-b2b-slider-carousel-border);
  border-radius: var(--bb-b2b-slider-radius-xl, var(--bb-radius-2xl));
  box-shadow: var(--bb-b2b-slider-carousel-shadow);
}

.bb-b2b-homepage-slider-inner,
.bb-b2b-homepage-slider-item {
  height: 100%;
}

/* Slide */
.bb-b2b-homepage-slider-slide {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.18fr) minmax(18rem, 0.82fr);
  align-items: center;
  gap: clamp(1.5rem, 3vw, 2.5rem);
  min-height: 28rem;
  overflow: hidden;
  padding: clamp(1.75rem, 3.4vw, 2.75rem) clamp(4.75rem, 6vw, 5.5rem);
}

.bb-b2b-homepage-slider-slide::before {
  content: "";
  position: absolute;
  top: -8rem;
  right: -5rem;
  z-index: 1;
  width: 20rem;
  height: 20rem;
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 12%, transparent);
  border-radius: 50%;
}

.bb-b2b-homepage-slider-slide::after {
  content: "";
  position: absolute;
  left: -5.5rem;
  bottom: -7.5rem;
  z-index: 1;
  width: 15rem;
  height: 15rem;
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 10%, transparent);
  border-radius: 50%;
}

/* Copy */
.bb-b2b-homepage-slider-copy {
  position: relative;
  z-index: 2;
  min-width: 0;
  max-width: 48rem;
  padding-left: clamp(0.375rem, 1vw, 0.875rem);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.bb-b2b-homepage-slider-label {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  margin-bottom: 1rem;
  padding: 0.55rem 0.9rem;
  color: var(--bb-white, #ffffff);
  background-color: color-mix(in srgb, var(--bb-black, #000000) 78%, #0f3b74);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-white, #ffffff) 10%, transparent);
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
  letter-spacing: var(--bb-letter-spacing-tight, -0.01em);
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-black, #000000) 18%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 12%, transparent);
}

.bb-b2b-homepage-slider-label .material-symbols-outlined {
  color: var(--bb-primary);
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

/* Title */
.bb-b2b-homepage-slider-title {
  max-width: 42rem;
  margin: 0 0 1rem;
  color: var(--bb-white, #ffffff) !important;
  font-size: clamp(2rem, 3.05vw, 2.875rem);
  font-weight: var(--bb-fw-bold);
  line-height: 1.06;
  letter-spacing: -0.04em;
}

.bb-b2b-homepage-slider-title *,
.bb-b2b-homepage-slider-title strong,
.bb-b2b-homepage-slider-title span,
.bb-b2b-homepage-slider-title h1,
.bb-b2b-homepage-slider-title h2,
.bb-b2b-homepage-slider-title h3 {
  color: inherit !important;
  font: inherit;
  font-weight: inherit;
  line-height: inherit;
  letter-spacing: inherit;
}

.bb-b2b-homepage-slider-text {
  max-width: 39rem;
  margin: 0 0 1.125rem;
  color: color-mix(in srgb, var(--bb-white, #ffffff) 82%, transparent);
  font-size: var(--bb-fs-base);
  font-weight: var(--bb-fw-medium);
  line-height: 1.65;
}

.bb-b2b-homepage-slider-text strong,
.bb-b2b-homepage-slider-text span {
  color: inherit;
  font: inherit;
  font-weight: inherit;
}

.bb-b2b-homepage-slider-text h1,
.bb-b2b-homepage-slider-text h2,
.bb-b2b-homepage-slider-text h3,
.bb-b2b-homepage-slider-text h4 {
  display: none !important;
}

/* Pills first, buttons second */
.bb-b2b-homepage-slider-pills {
  order: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  max-width: 39rem;
  margin-bottom: 1rem;
}

.bb-b2b-homepage-slider-actions {
  order: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 0;
}

/* Pills */
.bb-b2b-homepage-slider-pills .bb-chip {
  color: color-mix(in srgb, var(--bb-white, #ffffff) 78%, transparent);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 7%, transparent);
  border-color: color-mix(in srgb, var(--bb-white, #ffffff) 10%, transparent);
  font-weight: var(--bb-fw-semibold);
  box-shadow: none;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.bb-b2b-homepage-slider-pills .bb-chip:nth-child(1) {
  color: #8be5ae;
  background-color: rgba(32, 110, 74, 0.16);
  border-color: rgba(101, 216, 154, 0.2);
}

.bb-b2b-homepage-slider-pills .bb-chip:nth-child(2) {
  color: #9bbdff;
  background-color: rgba(56, 102, 196, 0.16);
  border-color: rgba(129, 164, 238, 0.22);
}

.bb-b2b-homepage-slider-pills .bb-chip:nth-child(3) {
  color: #ffe08a;
  background-color: rgba(148, 117, 17, 0.16);
  border-color: rgba(255, 214, 93, 0.22);
}

.bb-b2b-homepage-slider-pills .material-symbols-outlined {
  font-size: var(--bb-fs-md);
}

/* Buttons */
.bb-b2b-homepage-slider-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  min-height: 3rem;
  padding-right: 1.35rem;
  padding-left: 1.35rem;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-extrabold, var(--bb-fw-bold));
  box-shadow: 0 0.875rem 1.75rem color-mix(in srgb, var(--bb-black, #000000) 18%, transparent);
}

.bb-b2b-homepage-slider-btn .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.btn.btn-primary.bb-b2b-homepage-slider-btn {
  color: var(--bb-dark, #111827);
  background-color: var(--bb-primary);
  border-color: var(--bb-primary);
  box-shadow: 0 1rem 2rem color-mix(in srgb, var(--bb-primary) 34%, transparent), 0 0 0 0.25rem color-mix(in srgb, var(--bb-primary) 10%, transparent);
}

.btn.btn-primary.bb-b2b-homepage-slider-btn:hover,
.btn.btn-primary.bb-b2b-homepage-slider-btn:focus {
  color: var(--bb-dark, #111827);
  background-color: color-mix(in srgb, var(--bb-primary) 90%, var(--bb-white, #ffffff));
  border-color: color-mix(in srgb, var(--bb-primary) 90%, var(--bb-white, #ffffff));
}

.btn.btn-light.bb-b2b-homepage-slider-btn {
  color: var(--bb-white, #ffffff);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 13%, transparent);
  border-color: color-mix(in srgb, var(--bb-white, #ffffff) 12%, transparent);
  box-shadow: inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 12%, transparent), 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-black, #000000) 12%, transparent);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

.btn.btn-light.bb-b2b-homepage-slider-btn:hover,
.btn.btn-light.bb-b2b-homepage-slider-btn:focus {
  color: var(--bb-white, #ffffff);
  background-color: color-mix(in srgb, var(--bb-white, #ffffff) 19%, transparent);
  border-color: color-mix(in srgb, var(--bb-white, #ffffff) 16%, transparent);
}

/* Visual */
.bb-b2b-homepage-slider-visual {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 24rem;
  padding: 1rem 1.5rem 1rem 0;
}

.bb-b2b-homepage-slider-picture-card {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  width: min(100%, 20.5rem);
  aspect-ratio: 1/1;
  padding: 1.5rem;
  background: var(--bb-b2b-slider-picture-bg);
  border-radius: 50%;
  box-shadow: var(--bb-b2b-slider-picture-shadow);
}

.bb-b2b-homepage-slider-picture-card img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: drop-shadow(0 1rem 1.4rem color-mix(in srgb, var(--bb-black, #000000) 18%, transparent));
}

.bb-b2b-homepage-slider-picture-placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  color: color-mix(in srgb, var(--bb-primary) 42%, transparent);
  background: color-mix(in srgb, var(--bb-surface-elevated) 74%, transparent);
  border-radius: 50%;
}

.bb-b2b-homepage-slider-picture-placeholder .material-symbols-outlined {
  font-size: var(--bb-icon-size-4xl);
}

/* Network */
.bb-b2b-homepage-slider-network {
  position: absolute;
  inset: 1.25rem 1.5rem 1.25rem 0;
  z-index: 1;
  pointer-events: none;
}

.bb-b2b-homepage-slider-network-ring {
  position: absolute;
  border: var(--bb-border-width) dashed color-mix(in srgb, var(--bb-primary) 22%, transparent);
  border-radius: 50%;
}

.bb-b2b-homepage-slider-network-ring-one {
  inset: 12%;
}

.bb-b2b-homepage-slider-network-ring-two {
  inset: 27%;
}

.bb-b2b-homepage-slider-network-dot {
  position: absolute;
  width: 0.55rem;
  height: 0.55rem;
  background: var(--bb-primary);
  border-radius: 50%;
  box-shadow: 0 0 0 0.375rem color-mix(in srgb, var(--bb-primary) 10%, transparent);
}

.bb-b2b-homepage-slider-network-dot-one {
  top: 22%;
  left: 26%;
}

.bb-b2b-homepage-slider-network-dot-two {
  top: 31%;
  right: 18%;
}

.bb-b2b-homepage-slider-network-dot-three {
  right: 12%;
  bottom: 38%;
}

.bb-b2b-homepage-slider-network-dot-four {
  left: 33%;
  bottom: 22%;
}

/* Indicators */
.bb-b2b-homepage-slider-indicators {
  position: absolute;
  left: 50%;
  right: auto;
  bottom: 1.25rem;
  z-index: 5;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.45rem;
  width: auto;
  margin: 0;
  transform: translateX(-50%);
}

.bb-b2b-homepage-slider-indicators [data-bs-target],
.bb-b2b-homepage-slider-dot {
  width: 0.5rem;
  min-width: 0.5rem;
  height: 0.5rem;
  margin: 0;
  background: var(--bb-b2b-slider-dot-bg);
  border: 0;
  border-radius: var(--bb-radius-pill);
  opacity: 1;
