  pointer-events: none;
  transition: opacity var(--bb-transition-fast);
}

.bb-b2c-category-brands-card:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--bb-primary) 28%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-sm);
}

