  width: 9.375rem;
  height: 9.375rem;
  background-color: color-mix(in srgb, var(--bb-primary) 20%, transparent);
  border-radius: 50%;
}

.bb-b2c-offer-request-card h3,
.bb-b2c-offer-request-card p,
.bb-b2c-offer-request-card a {
  position: relative;
  z-index: 2;
}

.bb-b2c-offer-request-card h3 {
  margin: 0;
  color: var(--bb-white);
  font-size: var(--bb-icon-size-md);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2c-offer-request-card p {
  margin: 0.5625rem 0 1rem;
  color: color-mix(in srgb, var(--bb-white) 78%, transparent);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
}

.bb-b2c-offer-request-btn {
  width: 100%;
  min-height: 2.6875rem;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-b2c-offer-request-btn .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2c-offer-side-card {
  --bb-card-radius: var(--bb-radius-lg);
  --bb-card-shadow: var(--bb-shadow-xs);
  margin-bottom: 1rem;
  padding: 1.125rem;
}

.bb-b2c-offer-side-title {
  margin: 0 0 0.625rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-base);
  font-weight: var(--bb-fw-bold);
  line-height: 1.3;
}

.bb-b2c-offer-side-text {
  margin: 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
}

.bb-b2c-offer-side-list {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
  margin-top: 0.875rem;
}

.bb-b2c-offer-side-item {
  display: flex;
  align-items: flex-start;
  gap: 0.625rem;
  padding: 0.6875rem;
  background-color: var(--bb-tertiary-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius);
}

.bb-b2c-offer-side-icon {
  width: 2.125rem;
  height: 2.125rem;
  flex: 0 0 2.125rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-emphasis-color);
  background: linear-gradient(135deg, color-mix(in srgb, var(--bb-primary) 24%, var(--bb-white)) 0%, color-mix(in srgb, var(--bb-success) 12%, var(--bb-white)) 100%);
  border-radius: var(--bb-radius);
}

.bb-b2c-offer-side-icon .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2c-offer-side-item strong {
  display: block;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1.3;
}

.bb-b2c-offer-side-item span span {
  display: block;
  margin-top: 0.125rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  line-height: 1.4;
}

/* Empty */
.bb-b2c-offer-empty {
  --bb-card-radius: var(--bb-radius-xl);
  --bb-card-shadow: var(--bb-shadow-xs);
  padding: 2.125rem;
  text-align: center;
}

.bb-b2c-offer-empty-icon {
  width: 3.625rem;
  height: 3.625rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.875rem;
  color: var(--bb-emphasis-color);
  background-color: color-mix(in srgb, var(--bb-primary) 24%, var(--bb-white));
  border-radius: var(--bb-radius-lg);
}

.bb-b2c-offer-empty-icon .material-symbols-outlined {
  font-size: var(--bb-h3);
  line-height: 1;
}

.bb-b2c-offer-empty h1 {
  margin: 0;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-icon-size-xl);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2c-offer-empty p {
  max-width: 35rem;
  margin: 0.625rem auto 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

/* Responsive */
@media (max-width: 1199.98px) {
  .bb-b2c-offer-layout {
    grid-template-columns: 1fr;
  }
  .bb-b2c-offer-right {
    position: static;
  }
  .bb-b2c-shoe-guide-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 767.98px) {
  .bb-b2c-offer-title {
    font-size: var(--bb-h3);
  }
  .bb-b2c-offer-subtitle {
    font-size: var(--bb-fs-sm);
  }
  .bb-b2c-offer-section-head {
    align-items: flex-start;
    flex-direction: column;
  }
  .bb-b2c-offer-card-main {
    grid-template-columns: 1fr;
  }
  .bb-b2c-offer-card-actions {
    align-items: stretch;
    min-width: 0;
  }
  .bb-b2c-offer-select-btn {
    width: 100%;
  }
  .bb-b2c-offer-store-line {
    align-items: flex-start;
  }
  .bb-b2c-offer-filter-row {
    flex-wrap: nowrap;
    overflow-x: auto;
    padding-bottom: 0.125rem;
  }
  .bb-b2c-offer-filter-btn {
    flex: 0 0 auto;
  }
  .bb-b2c-shoe-guide-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2c-offer-product-summary {
    display: none;
  }
}
/* =====================================
   B2C Product Special Page
   Scope: category/special.cshtml
   Token-driven | Light/Dark compatible

   Razor roots:
   - .bb-b2c-special-page
   - .bb-b2c-special-hero
   - .bb-b2c-special-stage
   - .bb-b2c-special-products-shell
   - .bb-b2c-special-products-grid
   - .bb-b2c-special-pager

   Product cards:
   - Visual card anatomy comes from .bb-product-card
===================================== */
/* =====================================
   Page Root
===================================== */
.bb-b2c-special-page {
  --bb-b2c-special-accent: var(--bb-warning, #f7c600);
  --bb-b2c-special-accent-soft: color-mix(
      in srgb,
      var(--bb-b2c-special-accent) 18%,
      var(--bb-white, #ffffff)
  );
  --bb-b2c-special-pop: #ff7a2f;
  --bb-b2c-special-pop-soft: color-mix(
      in srgb,
      var(--bb-b2c-special-pop) 12%,
      var(--bb-white, #ffffff)
  );
  --bb-b2c-special-ink: var(--bb-emphasis-color);
  --bb-b2c-special-muted: var(--bb-secondary-color);
  --bb-b2c-special-border: color-mix(
      in srgb,
      var(--bb-border-color) 84%,
      transparent
  );
  --bb-b2c-special-radius-md: var(--bb-radius-xl);
  --bb-b2c-special-radius-lg: var(--bb-radius-2xl);
  --bb-b2c-special-radius-xl: calc(var(--bb-radius-2xl) + 0.25rem);
  --bb-b2c-special-shadow:
      0 0.875rem 2rem color-mix(in srgb, var(--bb-emphasis-color) 6%, transparent);
  --bb-b2c-special-shadow-hover:
      0 1.25rem 3rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent);
  --bb-b2c-special-media-bg: color-mix(in srgb, var(--bb-surface-elevated) 72%, transparent);
  --bb-b2c-special-media-border: color-mix(in srgb, var(--bb-surface-elevated) 68%, var(--bb-border-color));
  --bb-b2c-special-stage-bg: color-mix(in srgb, var(--bb-surface-elevated) 96%, transparent);
  --bb-b2c-special-surface-bg: var(--bb-surface-elevated);
  --bb-b2c-special-surface-border: color-mix(in srgb, var(--bb-border-color) 84%, transparent);
  --bb-b2c-special-chip-bg: color-mix(in srgb, var(--bb-b2c-special-accent) 8%, var(--bb-surface-elevated));
  --bb-b2c-special-chip-border: color-mix(in srgb, var(--bb-b2c-special-accent) 22%, var(--bb-border-color));
  --bb-b2c-special-chip-hover-bg: var(--bb-surface-elevated);
  --bb-b2c-special-chip-hover-border: color-mix(in srgb, var(--bb-b2c-special-accent) 38%, var(--bb-border-color));
  --bb-b2c-special-chip-active-bg: color-mix(in srgb, var(--bb-b2c-special-accent) 16%, var(--bb-surface-elevated));
  --bb-b2c-special-chip-active-border: color-mix(in srgb, var(--bb-b2c-special-accent) 42%, var(--bb-border-color));
  --bb-b2c-special-icon-color: color-mix(in srgb, var(--bb-b2c-special-accent) 74%, var(--bb-emphasis-color));
  --bb-b2c-special-icon-bg: color-mix(in srgb, var(--bb-b2c-special-accent) 14%, var(--bb-surface-elevated));
  --bb-b2c-special-icon-border: color-mix(in srgb, var(--bb-b2c-special-accent) 18%, var(--bb-border-color));
  position: relative;
  overflow: hidden;
  background-color: var(--bb-body-bg);
  color: var(--bb-body-color);
}

/* =====================================
   Hero
===================================== */
.bb-b2c-special-hero-badge {
  margin-bottom: 1.125rem;
  color: var(--bb-emphasis-color);
  background-color: color-mix(in srgb, var(--bb-b2c-special-accent) 32%, var(--bb-white, #ffffff));
  border-color: color-mix(in srgb, var(--bb-b2c-special-accent) 40%, var(--bb-border-color));
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-b2c-special-accent) 14%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 44%, transparent);
}

.bb-b2c-special-page .bb-hero-actions .btn-primary {
  color: var(--bb-emphasis-color);
  background-color: var(--bb-b2c-special-accent);
  border-color: color-mix(in srgb, var(--bb-b2c-special-accent) 86%, var(--bb-emphasis-color));
  box-shadow: 0 1rem 2rem color-mix(in srgb, var(--bb-b2c-special-accent) 22%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 24%, transparent);
}

.bb-b2c-special-page .bb-hero-actions .btn-light {
  color: var(--bb-emphasis-color);
  background-color: var(--bb-white, #ffffff);
  border-color: color-mix(in srgb, var(--bb-border-color) 82%, transparent);
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-emphasis-color) 7%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 72%, transparent);
}

.bb-b2c-special-page .bb-hero-media {
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.bb-b2c-special-page .bb-hero-media img {
  display: block;
  max-width: min(100%, 25rem);
  max-height: clamp(14rem, 22vw, 20rem);
  object-fit: contain;
  filter: drop-shadow(0 1.25rem 1.75rem color-mix(in srgb, var(--bb-emphasis-color) 12%, transparent));
}

.bb-b2c-special-page .bb-hero-media-card {
  width: min(100%, 20rem);
  min-height: 15rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-b2c-special-accent);
  background-color: var(--bb-b2c-special-media-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-special-media-border);
  border-radius: var(--bb-radius-2xl);
  box-shadow: 0 1.5rem 3.5rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 42%, transparent);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.bb-b2c-special-page .bb-hero-media-card .material-symbols-outlined {
  font-size: 4rem;
  line-height: 1;
}

/* =====================================
   Quick Nav / Stage
===================================== */
.bb-b2c-special-stage {
  position: relative;
  z-index: 5;
  margin-top: -2.75rem;
  padding-top: 0;
}

.bb-b2c-special-stage-card {
  overflow: hidden;
  padding: clamp(1rem, 2vw, 1.25rem);
  background-color: var(--bb-b2c-special-stage-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-special-surface-border);
  border-radius: var(--bb-b2c-special-radius-xl);
  box-shadow: 0 1.25rem 3rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent), inset 0 1px 0 color-mix(in srgb, var(--bb-white, #ffffff) 42%, transparent);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.bb-b2c-special-stage-head {
  margin-bottom: 0.875rem;
}

.bb-b2c-special-stage-label {
  display: block;
  margin-bottom: 0.25rem;
  color: var(--bb-b2c-special-muted);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
}

.bb-b2c-special-stage-title {
  margin: 0;
  color: var(--bb-b2c-special-ink);
  font-size: clamp(var(--bb-fs-base), 1.3vw, var(--bb-fs-xl));
  font-weight: var(--bb-fw-extrabold, 800);
  line-height: var(--bb-line-height-heading);
  letter-spacing: var(--bb-letter-spacing-tight, -0.02em);
}

.bb-b2c-special-stage-scroll {
  display: flex;
  gap: 0.875rem;
  overflow-x: auto;
  padding-bottom: 0.25rem;
  scrollbar-width: thin;
}

.bb-b2c-special-stage-scroll::-webkit-scrollbar {
  height: 0.375rem;
}

.bb-b2c-special-stage-scroll::-webkit-scrollbar-thumb {
  border-radius: var(--bb-radius-pill);
  background-color: color-mix(in srgb, var(--bb-b2c-special-accent) 35%, var(--bb-border-color));
}

.bb-b2c-special-stage-chip {
  min-width: 9.5rem;
  min-height: 6rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.75rem;
  color: var(--bb-b2c-special-ink) !important;
  background-color: var(--bb-b2c-special-chip-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-special-chip-border);
  border-radius: var(--bb-b2c-special-radius-md);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-extrabold);
  line-height: var(--bb-line-height-base);
  text-align: center;
  text-decoration: none !important;
  transition: transform var(--bb-transition-fast), border-color var(--bb-transition-fast), background-color var(--bb-transition-fast), box-shadow var(--bb-transition-fast);
}

.bb-b2c-special-stage-chip:hover,
.bb-b2c-special-stage-chip:focus {
  transform: translateY(-2px);
  background-color: var(--bb-b2c-special-chip-hover-bg);
  border-color: var(--bb-b2c-special-chip-hover-border);
  box-shadow: 0 0.875rem 1.75rem color-mix(in srgb, var(--bb-b2c-special-accent) 10%, transparent);
}

.bb-b2c-special-stage-chip.active,
.bb-b2c-special-stage-chip.is-active {
  background-color: var(--bb-b2c-special-chip-active-bg);
  border-color: var(--bb-b2c-special-chip-active-border);
  box-shadow: 0 0.875rem 1.75rem color-mix(in srgb, var(--bb-b2c-special-accent) 12%, transparent);
}

.bb-b2c-special-stage-icon {
  width: 2.75rem;
  height: 2.75rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--bb-b2c-special-icon-color);
  background-color: var(--bb-b2c-special-icon-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-special-icon-border);
  border-radius: 1rem;
}

.bb-b2c-special-stage-icon .material-symbols-outlined {
  color: currentColor;
  font-size: 1.5rem;
  line-height: 1;
  font-variation-settings: "FILL" 0, "wght" 500, "GRAD" 0, "opsz" 24;
}

/* =====================================
   Products Section
===================================== */
#special-products.bb-section {
  padding-top: clamp(2.25rem, 4vw, 3.75rem);
  padding-bottom: clamp(2.25rem, 4vw, 3.75rem);
}

.bb-b2c-special-products-shell {
  position: relative;
  overflow: hidden;
  padding: clamp(1.25rem, 2.25vw, 1.75rem);
  background: radial-gradient(circle at 96% 8%, color-mix(in srgb, var(--bb-b2c-special-accent) 8%, transparent), transparent 16rem), var(--bb-b2c-special-surface-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-special-surface-border);
  border-radius: var(--bb-b2c-special-radius-xl);
  box-shadow: 0 1rem 2.5rem color-mix(in srgb, var(--bb-emphasis-color) 6%, transparent), 0 0.25rem 0.875rem color-mix(in srgb, var(--bb-emphasis-color) 3%, transparent);
}

.bb-b2c-special-products-shell::after {
  content: "";
  position: absolute;
  right: -5rem;
  bottom: -6rem;
  z-index: 0;
  width: 15rem;
  height: 15rem;
  background-color: color-mix(in srgb, var(--bb-b2c-special-accent) 7%, transparent);
  border-radius: 50%;
  pointer-events: none;
}

.bb-b2c-special-products-shell > * {
  position: relative;
  z-index: 2;
}

.bb-b2c-special-products-shell .bb-section-head {
  margin-bottom: clamp(1.25rem, 2vw, 1.5rem);
}

.bb-b2c-special-products-shell .bb-section-label {
  margin-bottom: 0.75rem;
}

.bb-b2c-special-products-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: clamp(0.875rem, 1.25vw, 1.125rem);
  align-items: stretch;
}

.bb-b2c-special-products-grid .bb-product-card {
  height: 100%;
}

/* =====================================
   Pager
===================================== */
.bb-b2c-special-pagination-wrap {
  margin-top: 1.25rem;
}

.bb-b2c-special-pager {
  margin-top: 1.375rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.875rem 1.125rem;
  background-color: var(--bb-b2c-special-surface-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-special-surface-border);
  border-radius: var(--bb-b2c-special-radius-lg);
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-emphasis-color) 5%, transparent);
}

.bb-b2c-special-pager-info {
  color: var(--bb-b2c-special-ink);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

/* =====================================
   Empty State
===================================== */
.bb-b2c-special-empty {
  padding: clamp(2rem, 4vw, 3rem) 1.5rem;
  text-align: center;
  background: radial-gradient(circle at top right, color-mix(in srgb, var(--bb-b2c-special-accent) 9%, transparent), transparent 18rem), var(--bb-b2c-special-surface-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-special-surface-border);
  border-radius: var(--bb-b2c-special-radius-xl);
  box-shadow: 0 0.875rem 2rem color-mix(in srgb, var(--bb-emphasis-color) 6%, transparent);
}

.bb-b2c-special-empty-icon {
  width: 4.625rem;
  height: 4.625rem;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.125rem;
  color: var(--bb-b2c-special-accent);
  background-color: color-mix(in srgb, var(--bb-b2c-special-accent) 14%, var(--bb-surface-elevated));
  border-radius: var(--bb-radius-pill);
}

.bb-b2c-special-empty-icon .material-symbols-outlined {
  font-size: var(--bb-icon-size-2xl);
  line-height: 1;
}

.bb-b2c-special-empty-symbol {
  margin-inline: auto;
  margin-bottom: 1.125rem;
}

.bb-b2c-special-empty-symbol .material-symbols-outlined {
  color: var(--bb-b2c-special-accent);
}

.bb-b2c-special-empty h2,
.bb-b2c-special-empty-title {
  margin: 0 0 0.65rem;
  color: var(--bb-b2c-special-ink);
  font-size: var(--bb-fs-2xl);
  font-weight: var(--bb-fw-extrabold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2c-special-empty p,
.bb-b2c-special-empty-text {
  max-width: 35rem;
  margin: 0 auto 1.25rem;
  color: var(--bb-b2c-special-muted);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

.bb-b2c-special-empty-link {
  min-height: 2.875rem;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

/* =====================================
   Dark tokens
===================================== */
[data-bs-theme=dark] .bb-b2c-special-page {
  --bb-b2c-special-border: color-mix(in srgb, var(--bb-border-color) 74%, transparent);
  --bb-b2c-special-shadow: 0 0.875rem 2rem color-mix(in srgb, var(--bb-black) 22%, transparent);
  --bb-b2c-special-shadow-hover: 0 1.25rem 3rem color-mix(in srgb, var(--bb-black) 28%, transparent);
  --bb-b2c-special-media-bg: color-mix(in srgb, var(--bb-surface-elevated) 88%, var(--bb-body-bg));
  --bb-b2c-special-media-border: color-mix(in srgb, var(--bb-border-color) 74%, transparent);
  --bb-b2c-special-stage-bg: var(--bb-b2c-special-media-bg);
  --bb-b2c-special-surface-bg: var(--bb-b2c-special-media-bg);
  --bb-b2c-special-surface-border: var(--bb-b2c-special-media-border);
  --bb-b2c-special-chip-bg: color-mix(in srgb, var(--bb-surface-elevated) 82%, var(--bb-body-bg));
  --bb-b2c-special-chip-border: color-mix(in srgb, var(--bb-border-color) 72%, transparent);
  --bb-b2c-special-chip-hover-bg: color-mix(in srgb, var(--bb-b2c-special-accent) 12%, var(--bb-surface-elevated));
  --bb-b2c-special-chip-hover-border: color-mix(in srgb, var(--bb-b2c-special-accent) 28%, var(--bb-border-color));
  --bb-b2c-special-chip-active-bg: var(--bb-b2c-special-chip-hover-bg);
  --bb-b2c-special-chip-active-border: var(--bb-b2c-special-chip-hover-border);
  --bb-b2c-special-icon-color: color-mix(in srgb, var(--bb-white) 86%, var(--bb-b2c-special-accent));
  --bb-b2c-special-icon-bg: color-mix(in srgb, var(--bb-b2c-special-accent) 18%, var(--bb-surface-elevated));
  --bb-b2c-special-icon-border: color-mix(in srgb, var(--bb-b2c-special-accent) 20%, var(--bb-border-color));
}

/* =====================================
   Responsive
===================================== */
@media (max-width: 1399.98px) {
  .bb-b2c-special-products-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (max-width: 1199.98px) {
  .bb-b2c-special-page .bb-hero-media {
    justify-content: flex-start;
  }
  .bb-b2c-special-products-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
@media (max-width: 991.98px) {
  .bb-b2c-special-stage {
    margin-top: -2.125rem;
  }
  .bb-b2c-special-products-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .bb-b2c-special-pager {
    align-items: stretch;
    flex-direction: column;
  }
  .bb-b2c-special-pager-info {
    text-align: center;
  }
}
@media (max-width: 767.98px) {
  .bb-b2c-special-stage {
    margin-top: -1.75rem;
  }
  .bb-b2c-special-stage-card {
    border-radius: var(--bb-radius-2xl);
  }
  #special-products.bb-section {
    padding-top: 2rem;
    padding-bottom: 2rem;
  }
  .bb-b2c-special-products-shell {
    padding: 1rem;
    border-radius: var(--bb-radius-2xl);
  }
}
@media (max-width: 575.98px) {
  .bb-b2c-special-products-grid {
    grid-template-columns: 1fr;
  }
  .bb-b2c-special-page .bb-hero-media-card {
    width: 100%;
    min-height: 13rem;
  }
}
/* =====================================
   Bulbulustur B2C - Product Reviews Page
===================================== */
/* =====================================
   Review Tokens
===================================== */
.bb-b2c-review-page {
  --bb-b2c-review-page-bg: var(--bb-body-bg);
  --bb-b2c-review-surface: var(--bb-surface-elevated, var(--bb-body-bg));
  --bb-b2c-review-surface-soft: color-mix(in srgb, var(--bb-tertiary-bg) 82%, var(--bb-body-bg));
  --bb-b2c-review-border: color-mix(in srgb, var(--bb-border-color) 82%, transparent);
  --bb-b2c-review-accent: var(--bb-primary);
  --bb-b2c-review-accent-soft: color-mix(in srgb, var(--bb-primary) 14%, var(--bb-body-bg));
  --bb-b2c-review-accent-strong: color-mix(in srgb, var(--bb-primary) 82%, var(--bb-emphasis-color));
  --bb-b2c-review-star: var(--bb-primary);
  --bb-b2c-review-star-muted: color-mix(in srgb, var(--bb-secondary-color) 34%, transparent);
  --bb-b2c-review-text: var(--bb-body-color);
  --bb-b2c-review-heading: var(--bb-emphasis-color);
  --bb-b2c-review-muted: var(--bb-secondary-color);
  --bb-b2c-review-subtle: var(--bb-tertiary-color);
  --bb-b2c-review-avatar-bg: color-mix(in srgb, var(--bb-primary) 18%, var(--bb-body-bg));
  --bb-b2c-review-avatar-color: color-mix(in srgb, var(--bb-primary) 82%, var(--bb-emphasis-color));
  --bb-b2c-review-shadow:
      0 1.25rem 3.25rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent),
      0 0.125rem 0.375rem color-mix(in srgb, var(--bb-emphasis-color) 3%, transparent);
  --bb-b2c-review-shadow-hover:
      0 1.5rem 3.75rem color-mix(in srgb, var(--bb-emphasis-color) 12%, transparent),
      0 0.125rem 0.375rem color-mix(in srgb, var(--bb-emphasis-color) 4%, transparent);
  --bb-b2c-review-gallery-overlay-bg: color-mix(in srgb, var(--bb-black, #000) 64%, transparent);
}

[data-bs-theme=dark] .bb-b2c-review-page {
  --bb-b2c-review-page-bg: var(--bb-body-bg);
  --bb-b2c-review-surface: var(--bb-surface-elevated, var(--bb-body-bg));
  --bb-b2c-review-surface-soft: color-mix(in srgb, var(--bb-tertiary-bg) 72%, var(--bb-body-bg));
  --bb-b2c-review-border: color-mix(in srgb, var(--bb-border-color) 84%, transparent);
  --bb-b2c-review-accent-soft: color-mix(in srgb, var(--bb-primary) 17%, var(--bb-body-bg));
  --bb-b2c-review-accent-strong: color-mix(in srgb, var(--bb-primary) 88%, var(--bb-emphasis-color));
  --bb-b2c-review-star-muted: color-mix(in srgb, var(--bb-secondary-color) 42%, transparent);
  --bb-b2c-review-avatar-bg: color-mix(in srgb, var(--bb-primary) 18%, var(--bb-body-bg));
  --bb-b2c-review-avatar-color: color-mix(in srgb, var(--bb-primary) 88%, var(--bb-emphasis-color));
  --bb-b2c-review-shadow:
      0 1.25rem 3.25rem color-mix(in srgb, var(--bb-black, #000) 22%, transparent),
      0 0.125rem 0.375rem color-mix(in srgb, var(--bb-black, #000) 12%, transparent);
  --bb-b2c-review-shadow-hover:
      0 1.5rem 3.75rem color-mix(in srgb, var(--bb-black, #000) 28%, transparent),
      0 0.125rem 0.375rem color-mix(in srgb, var(--bb-black, #000) 14%, transparent);
  --bb-b2c-review-gallery-overlay-bg: color-mix(in srgb, var(--bb-black, #000) 72%, transparent);
}

/* =====================================
   Hero
===================================== */
.bb-b2c-review-hero-label {
  gap: 0.4375rem;
  margin-bottom: 1rem;
}

.bb-b2c-review-hero-label .material-symbols-outlined {
  color: var(--bb-b2c-review-accent-strong);
  font-size: var(--bb-icon-size-sm);
  line-height: 1;
}

.bb-b2c-review-hero-btn .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

/* =====================================
   Hero Product Card
===================================== */
.bb-b2c-review-hero-aside {
  min-width: 0;
  justify-self: end;
  width: min(100%, 34rem);
}

.bb-b2c-review-hero-product {
  min-width: 0;
  overflow: hidden;
  width: 100%;
  padding: clamp(1rem, 2.5vw, 1.5rem);
  border-color: var(--bb-b2c-review-border);
  border-radius: var(--bb-radius-2xl);
  background: radial-gradient(circle at 90% 12%, color-mix(in srgb, var(--bb-primary) 12%, transparent), transparent 13rem), var(--bb-b2c-review-surface);
  box-shadow: var(--bb-b2c-review-shadow);
}

.bb-b2c-review-hero-product * {
  min-width: 0;
}

.bb-b2c-review-hero-product a {
  color: inherit;
  text-decoration: none !important;
}

.bb-b2c-review-hero-product img {
  display: block;
  max-width: 100%;
  height: auto;
  object-fit: contain;
}

.bb-b2c-review-hero-product :is(h1, h2, h3, h4, strong) {
  color: var(--bb-b2c-review-heading);
}

/* Eski / component içi ProductReviewHeader classları varsa toparla */
.bb-b2c-review-hero-product .bb-b2c-review-hero-product-card {
  width: 100%;
  max-width: none;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.bb-b2c-review-hero-product .bb-b2c-review-hero-product-image {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 12rem;
  padding: 1rem;
  border-radius: var(--bb-radius-xl);
  background-color: var(--bb-tertiary-bg);
}

.bb-b2c-review-hero-product .bb-b2c-review-hero-product-image img {
  width: 100%;
  max-height: 14rem;
  object-fit: contain;
}

.bb-b2c-review-hero-product .bb-b2c-review-hero-product-title {
  margin: 0.875rem 0 0;
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-fs-lg);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: -0.025em;
  text-align: center;
}

.bb-b2c-review-hero-empty-product {
  display: grid;
  place-items: center;
  min-height: 16rem;
  gap: 0.625rem;
  padding: 1.5rem;
  border: var(--bb-border-width) dashed var(--bb-b2c-review-border);
  border-radius: var(--bb-radius-xl);
  background-color: var(--bb-b2c-review-surface-soft);
  text-align: center;
}

.bb-b2c-review-hero-empty-product .material-symbols-outlined {
  color: var(--bb-b2c-review-accent-strong);
  font-size: var(--bb-icon-size-2xl);
  line-height: 1;
}

.bb-b2c-review-hero-empty-product strong {
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-fs-base);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2c-review-hero-empty-product small {
  max-width: 18rem;
  color: var(--bb-b2c-review-muted);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
}

/* =====================================
   Review Section Shell
===================================== */
.bb-b2c-review-section {
  background-color: var(--bb-b2c-review-page-bg);
}

.bb-b2c-review-shell {
  overflow: hidden;
  padding: clamp(1.25rem, 3vw, 1.75rem);
  border-color: var(--bb-b2c-review-border);
  border-radius: var(--bb-radius-2xl);
  background-color: var(--bb-b2c-review-surface);
  box-shadow: var(--bb-b2c-review-shadow);
}

.bb-b2c-review-section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1.375rem;
}

.bb-b2c-review-section-title {
  margin: 0.75rem 0 0;
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-web-section-title-size);
  font-weight: var(--bb-fw-extrabold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: -0.045em;
}

.bb-b2c-review-section-text {
  max-width: 48rem;
  margin: 0.75rem 0 0;
  color: var(--bb-b2c-review-muted);
  font-size: var(--bb-fs-base);
  line-height: var(--bb-line-height-loose);
}

.bb-b2c-review-summary-wrap {
  margin-bottom: 1.5rem;
  padding-bottom: 1.5rem;
  border-bottom: var(--bb-border-width) solid var(--bb-b2c-review-border);
}

/* =====================================
   Review Summary
===================================== */
.bb-b2c-review-summary {
  display: grid;
  grid-template-columns: minmax(10rem, 0.34fr) minmax(0, 1fr);
  gap: clamp(1.25rem, 4vw, 2.125rem);
  align-items: center;
  width: 100%;
  padding: clamp(1.25rem, 3vw, 1.75rem);
  border: var(--bb-border-width) solid var(--bb-b2c-review-border);
  border-radius: var(--bb-radius-xl);
  background: radial-gradient(circle at top right, color-mix(in srgb, var(--bb-primary) 10%, transparent), transparent 16rem), var(--bb-b2c-review-surface-soft);
}

.bb-b2c-review-score {
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.bb-b2c-review-score-value {
  display: block;
  margin-bottom: 1rem;
  color: var(--bb-b2c-review-heading);
  font-size: clamp(3.75rem, 7vw, 4.875rem);
  font-weight: var(--bb-fw-normal);
  line-height: 0.92;
  letter-spacing: -0.065em;
}

.bb-b2c-review-stars,
.bb-b2c-review-bar-stars,
.bb-b2c-review-gallery-stars {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.125rem;
  color: var(--bb-b2c-review-star);
}

.bb-b2c-review-stars {
  margin-bottom: 0.625rem;
}

.bb-b2c-review-stars .material-symbols-outlined,
.bb-b2c-review-bar-stars .material-symbols-outlined,
.bb-b2c-review-gallery-stars .material-symbols-outlined {
  line-height: 1;
  font-variation-settings: "FILL" 1, "wght" 500, "GRAD" 0, "opsz" 24;
}

.bb-b2c-review-stars .material-symbols-outlined {
  font-size: var(--bb-icon-size-lg);
}

.bb-b2c-review-bar-stars .material-symbols-outlined,
.bb-b2c-review-gallery-stars .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
}

.bb-b2c-review-star-muted {
  color: var(--bb-b2c-review-star-muted) !important;
}

.bb-b2c-review-score-label {
  display: block;
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2c-review-bars {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.8125rem;
  width: 100%;
}

.bb-b2c-review-bar-row {
  display: grid;
  grid-template-columns: 6.5rem minmax(0, 1fr) 1.75rem;
  gap: 0.625rem;
  align-items: center;
  width: 100%;
}

.bb-b2c-review-bar-stars {
  white-space: nowrap;
}

.bb-b2c-review-bar-track {
  display: block;
  overflow: hidden;
  width: 100%;
  height: 0.5625rem;
  border-radius: var(--bb-radius-pill);
  background-color: color-mix(in srgb, var(--bb-border-color) 52%, var(--bb-tertiary-bg));
}

.bb-b2c-review-bar-fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background-color: var(--bb-b2c-review-star);
}

.bb-b2c-review-bar-count {
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
  text-align: right;
}

/* =====================================
   Review List
===================================== */
.bb-b2c-review-list {
  display: flex;
  flex-direction: column;
}

.bb-b2c-review-item {
  padding: 1.625rem 0;
  border-top: var(--bb-border-width) solid var(--bb-b2c-review-border);
}

.bb-b2c-review-item:first-child {
  padding-top: 0;
  border-top: 0;
}

.bb-b2c-review-item:last-child {
  padding-bottom: 0;
}

.bb-b2c-review-item-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: flex-start;
  gap: 0.875rem;
  margin-bottom: 0.75rem;
}

.bb-b2c-review-author-block {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  min-width: 0;
}

.bb-b2c-review-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3.25rem;
  height: 3.25rem;
  flex: 0 0 3.25rem;
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-b2c-review-avatar-bg);
  color: var(--bb-b2c-review-avatar-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1;
  box-shadow: 0 0.75rem 1.5rem color-mix(in srgb, var(--bb-primary) 12%, transparent);
}

.bb-b2c-review-author-main {
  min-width: 0;
  padding-top: 0.1875rem;
}

.bb-b2c-review-author-line {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.1875rem;
  min-width: 0;
}

.bb-b2c-review-author {
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1.25;
}

.bb-b2c-review-date {
  color: var(--bb-b2c-review-subtle);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-semibold);
  line-height: var(--bb-line-height-base);
}

.bb-b2c-review-location {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 0.4375rem;
  margin-left: auto;
}

.bb-b2c-review-content {
  min-width: 0;
  margin-left: 4rem;
}

.bb-b2c-review-text-wrap {
  position: relative;
}

.bb-b2c-review-text {
  position: relative;
  overflow: hidden;
  margin: 0;
  color: var(--bb-b2c-review-muted);
  font-size: var(--bb-fs-sm);
  line-height: 1.85;
  white-space: pre-line;
}

.bb-b2c-review-text.is-collapsed {
  display: -webkit-box;
  max-height: 5.55em;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
}

.bb-b2c-review-text.is-collapsed::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 3rem;
  background: linear-gradient(to bottom, color-mix(in srgb, var(--bb-b2c-review-surface) 0%, transparent), var(--bb-b2c-review-surface));
  pointer-events: none;
}

.bb-b2c-review-text.is-expanded {
  display: block;
  max-height: none;
  overflow: visible;
}

.bb-b2c-review-more-link {
  display: inline-flex;
  margin-top: 0.625rem;
  padding: 0;
  border: 0;
  background-color: transparent;
  color: var(--bb-b2c-review-accent-strong) !important;
  cursor: pointer;
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
  text-decoration: none !important;
}

.bb-b2c-review-more-link:hover {
  color: var(--bb-primary) !important;
  text-decoration: underline !important;
}

/* =====================================
   Review Pictures
===================================== */
.bb-b2c-review-picture-card {
  margin-top: 1rem;
  padding: 0.875rem;
  border: var(--bb-border-width) solid var(--bb-b2c-review-border);
  border-radius: var(--bb-radius-xl);
  background: radial-gradient(circle at 92% 8%, color-mix(in srgb, var(--bb-primary) 8%, transparent), transparent 10rem), var(--bb-b2c-review-surface-soft);
}

.bb-b2c-review-picture-card-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.bb-b2c-review-picture-list {
  display: flex !important;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.625rem;
  padding: 0 !important;
  margin: 0 !important;
  list-style: none !important;
}

.bb-b2c-review-picture-item {
  display: block;
  flex: 0 0 auto;
  width: auto;
  margin: 0 !important;
  padding: 0 !important;
}

.bb-b2c-review-picture-btn {
  display: block !important;
  width: 5.125rem !important;
  height: 5.125rem !important;
  min-width: 5.125rem !important;
  max-width: 5.125rem !important;
  min-height: 5.125rem !important;
  max-height: 5.125rem !important;
  padding: 0 !important;
  border: 0 !important;
  background-color: transparent !important;
  cursor: pointer;
}

.bb-b2c-review-picture-frame {
  display: flex !important;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  width: 100% !important;
  height: 100% !important;
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-lg);
  background-color: var(--bb-tertiary-bg);
  transition: transform var(--bb-transition-fast), border-color var(--bb-transition-fast), box-shadow var(--bb-transition-fast);
}

.bb-b2c-review-picture-btn:hover .bb-b2c-review-picture-frame {
  transform: translateY(-0.125rem);
  border-color: color-mix(in srgb, var(--bb-primary) 34%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-xs);
}

.bb-b2c-review-picture-frame img {
  display: block !important;
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
}

/* =====================================
   Pagination
===================================== */
.bb-b2c-review-pagination-wrap {
  margin-top: 1.5rem;
  padding-top: 1.125rem;
  border-top: var(--bb-border-width) solid var(--bb-b2c-review-border);
}

/* =====================================
   Empty State
===================================== */
.bb-b2c-review-empty {
  display: grid;
  place-items: center;
  min-height: 24rem;
  padding: clamp(2rem, 5vw, 4rem);
  border-color: var(--bb-b2c-review-border);
  border-radius: var(--bb-radius-2xl);
  background: radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--bb-primary) 12%, transparent), transparent 20rem), var(--bb-b2c-review-surface);
  text-align: center;
  box-shadow: var(--bb-b2c-review-shadow);
}

.bb-b2c-review-empty-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 4.625rem;
  height: 4.625rem;
  margin-bottom: 1.125rem;
  border-radius: var(--bb-radius-2xl);
  background-color: var(--bb-b2c-review-accent-soft);
  color: var(--bb-b2c-review-accent-strong);
}

.bb-b2c-review-empty-icon .material-symbols-outlined {
  font-size: var(--bb-icon-size-2xl);
  line-height: 1;
}

.bb-b2c-review-empty h2 {
  margin: 0;
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-fs-2xl);
  font-weight: var(--bb-fw-extrabold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2c-review-empty p {
  max-width: 34rem;
  margin: 0.75rem auto 0;
  color: var(--bb-b2c-review-muted);
  font-size: var(--bb-fs-base);
  line-height: var(--bb-line-height-loose);
}

.bb-b2c-review-empty-link {
  margin-top: 1.25rem;
}

/* =====================================
   Gallery Overlay
===================================== */
.bb-b2c-review-gallery-overlay {
  position: fixed;
  inset: 0;
  z-index: 1060;
  background-color: var(--bb-b2c-review-gallery-overlay-bg);
  opacity: 0;
  visibility: hidden;
  transition: opacity var(--bb-transition-fast), visibility var(--bb-transition-fast);
}

.bb-b2c-review-gallery-overlay.is-active {
  opacity: 1;
  visibility: visible;
}

.bb-b2c-review-gallery-modal {
  position: fixed;
  left: 50%;
  top: 50%;
  z-index: 1070;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  overflow: hidden;
  width: min(73.75rem, 100vw - 2rem);
  height: min(47.5rem, 100vh - 2.625rem);
  border: var(--bb-border-width) solid var(--bb-b2c-review-border);
  border-radius: var(--bb-radius-2xl);
  background-color: var(--bb-b2c-review-surface);
  box-shadow: 0 1.5rem 4.375rem color-mix(in srgb, var(--bb-black, #000) 28%, transparent);
  opacity: 0;
  visibility: hidden;
  transform: translate(-50%, -46%) scale(0.98);
  transition: opacity var(--bb-transition-fast), visibility var(--bb-transition-fast), transform var(--bb-transition-fast);
}

.bb-b2c-review-gallery-modal.is-active {
  opacity: 1;
  visibility: visible;
  transform: translate(-50%, -50%) scale(1);
}

.bb-b2c-review-gallery-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 3.625rem;
  padding: 0 1.125rem;
  border-bottom: var(--bb-border-width) solid var(--bb-b2c-review-border);
}

.bb-b2c-review-gallery-title {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
}

.bb-b2c-review-gallery-title .material-symbols-outlined {
  color: var(--bb-b2c-review-accent-strong);
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2c-review-gallery-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-b2c-review-surface);
  color: var(--bb-b2c-review-heading);
  cursor: pointer;
}

.bb-b2c-review-gallery-close:hover {
  border-color: color-mix(in srgb, var(--bb-primary) 24%, var(--bb-border-color));
  background-color: color-mix(in srgb, var(--bb-primary) 10%, transparent);
}

.bb-b2c-review-gallery-close .material-symbols-outlined {
  font-size: var(--bb-icon-size-md);
  line-height: 1;
}

.bb-b2c-review-gallery-body {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(20rem, 0.65fr);
  min-height: 0;
  background-color: var(--bb-b2c-review-surface);
}

.bb-b2c-review-gallery-media {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-width: 0;
  min-height: 0;
  padding: 1.375rem;
  background-color: var(--bb-b2c-review-surface-soft);
}

.bb-b2c-review-gallery-image-frame {
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  width: 100%;
  height: 100%;
  max-height: 40rem;
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-xl);
  background-color: var(--bb-b2c-review-surface);
}

.bb-b2c-review-gallery-image-frame img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.bb-b2c-review-gallery-arrow {
  position: absolute;
  top: 50%;
  z-index: 3;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.625rem;
  height: 2.625rem;
  border: 0;
  border-radius: var(--bb-radius-pill);
  background-color: color-mix(in srgb, var(--bb-black, #000) 72%, transparent);
  color: var(--bb-white);
  cursor: pointer;
  transform: translateY(-50%);
}

.bb-b2c-review-gallery-arrow-left {
  left: 1.25rem;
}

.bb-b2c-review-gallery-arrow-right {
  right: 1.25rem;
}

.bb-b2c-review-gallery-arrow .material-symbols-outlined {
  font-size: var(--bb-icon-size-lg);
  line-height: 1;
}

.bb-b2c-review-gallery-side {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  border-left: var(--bb-border-width) solid var(--bb-b2c-review-border);
  background-color: var(--bb-b2c-review-surface);
}

.bb-b2c-review-gallery-review {
  flex: 1;
  overflow-y: auto;
  padding: 1.375rem;
}

.bb-b2c-review-gallery-review-head {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.bb-b2c-review-gallery-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.625rem;
  height: 2.625rem;
  flex: 0 0 2.625rem;
  border-radius: var(--bb-radius-pill);
  background-color: var(--bb-b2c-review-avatar-bg);
  color: var(--bb-b2c-review-avatar-color);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
}

.bb-b2c-review-gallery-author {
  min-width: 0;
}

.bb-b2c-review-gallery-author strong {
  display: block;
  color: var(--bb-b2c-review-heading);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  line-height: 1.25;
}

.bb-b2c-review-gallery-author span {
  display: block;
  margin-top: 0.1875rem;
  color: var(--bb-b2c-review-subtle);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-semibold);
  line-height: var(--bb-line-height-base);
}

.bb-b2c-review-gallery-stars {
  margin-bottom: 0.75rem;
}

.bb-b2c-review-gallery-location {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 0.4375rem;
  margin-bottom: 0.875rem;
}

.bb-b2c-review-gallery-text {
  margin: 0;
  color: var(--bb-b2c-review-muted);
  font-size: var(--bb-fs-sm);
  line-height: 1.8;
  white-space: pre-line;
}

.bb-b2c-review-gallery-thumbs {
  display: flex;
  gap: 0.5rem;
  overflow-x: auto;
  padding: 0.875rem;
  border-top: var(--bb-border-width) solid var(--bb-b2c-review-border);
  background-color: var(--bb-b2c-review-surface);
}

.bb-b2c-review-gallery-thumb {
  overflow: hidden;
  width: 3.625rem;
  height: 3.625rem;
  flex: 0 0 3.625rem;
  padding: 0;
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-lg);
  background-color: var(--bb-tertiary-bg);
  cursor: pointer;
}

.bb-b2c-review-gallery-thumb.is-active {
  border-color: var(--bb-primary);
  box-shadow: 0 0 0 0.125rem color-mix(in srgb, var(--bb-primary) 18%, transparent);
}

.bb-b2c-review-gallery-thumb img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

body.bb-b2c-review-gallery-open {
  overflow: hidden;
}

/* =====================================
   Responsive
===================================== */
@media (max-width: 1199.98px) {
  .bb-b2c-review-hero-inner {
    grid-template-columns: minmax(0, 1fr) minmax(24rem, 0.5fr);
  }
  .bb-b2c-review-hero-aside {
    width: min(100%, 30rem);
  }
}
@media (max-width: 991.98px) {
  .bb-b2c-review-hero-inner {
    grid-template-columns: 1fr;
  }
  .bb-b2c-review-hero-aside {
    justify-self: start;
    width: min(100%, 34rem);
  }
  .bb-b2c-review-gallery-modal {
    height: min(52.5rem, 100vh - 1.5rem);
  }
  .bb-b2c-review-gallery-body {
    grid-template-columns: 1fr;
    grid-template-rows: minmax(17.5rem, 0.9fr) minmax(16.25rem, 0.7fr);
  }
  .bb-b2c-review-gallery-side {
    border-left: 0;
    border-top: var(--bb-border-width) solid var(--bb-b2c-review-border);
  }
}
@media (max-width: 767.98px) {
  .bb-b2c-review-hero {
    padding-top: 2.25rem;
    padding-bottom: 2.75rem;
  }
  .bb-b2c-review-hero-title {
    font-size: var(--bb-hero-title-size);
  }
  .bb-b2c-review-hero-actions {
    flex-direction: column;
  }
  .bb-b2c-review-hero-btn {
    width: 100%;
  }
  .bb-b2c-review-shell {
    padding: 1rem;
  }
  .bb-b2c-review-summary {
    grid-template-columns: 1fr;
    text-align: center;
  }
  .bb-b2c-review-bar-row {
    grid-template-columns: 5.75rem minmax(0, 1fr) 1.5rem;
  }
  .bb-b2c-review-item-head {
    grid-template-columns: 1fr;
  }
  .bb-b2c-review-location {
    justify-content: flex-start;
    margin-left: 4rem;
  }
  .bb-b2c-review-text {
    font-size: var(--bb-fs-sm);
    line-height: 1.75;
  }
  .bb-b2c-review-text.is-collapsed {
    max-height: 5.25em;
  }
  .bb-b2c-review-gallery-modal {
    width: calc(100vw - 1.125rem);
    height: calc(100vh - 1.125rem);
    border-radius: var(--bb-radius-xl);
  }
  .bb-b2c-review-gallery-media {
    padding: 0.75rem;
  }
  .bb-b2c-review-gallery-arrow {
    width: 2.25rem;
    height: 2.25rem;
  }
  .bb-b2c-review-gallery-arrow-left {
    left: 0.75rem;
  }
  .bb-b2c-review-gallery-arrow-right {
    right: 0.75rem;
  }
  .bb-b2c-review-gallery-review {
    padding: 1rem;
  }
}
@media (max-width: 575.98px) {
  .bb-b2c-review-content,
  .bb-b2c-review-location {
    margin-left: 0;
  }
  .bb-b2c-review-author-block {
    align-items: center;
  }
  .bb-b2c-review-picture-btn {
    width: 4.5rem !important;
    height: 4.5rem !important;
    min-width: 4.5rem !important;
    max-width: 4.5rem !important;
    min-height: 4.5rem !important;
    max-height: 4.5rem !important;
  }
  .bb-b2c-review-shell,
  .bb-b2c-review-summary,
  .bb-b2c-review-picture-card,
  .bb-b2c-review-empty,
  .bb-b2c-review-hero-product {
    border-radius: var(--bb-radius-xl);
  }
}
/* =====================================
   B2C Sponsored Product Top Product List
   Component-specific
===================================== */
.bb-b2c-sponsored-top {
  position: relative;
  overflow: hidden;
  margin-bottom: 1.5rem;
  padding: 1.125rem;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-xl);
  box-shadow: var(--bb-shadow-xs);
}

.bb-b2c-sponsored-top::before {
  content: "";
  position: absolute;
  right: -5.625rem;
  top: -5.625rem;
  width: 13.75rem;
  height: 13.75rem;
  background-color: color-mix(in srgb, var(--bb-primary) 8%, transparent);
  border-radius: 50%;
  pointer-events: none;
}

.bb-b2c-sponsored-top-inner {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 15rem minmax(0, 1fr);
  gap: 1.375rem;
  align-items: stretch;
}

/* -------------------------------------
   Brand panel
------------------------------------- */
.bb-b2c-sponsored-top-brand {
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 1.125rem;
  background: linear-gradient(180deg, color-mix(in srgb, var(--bb-primary) 7%, var(--bb-surface-elevated)) 0%, var(--bb-body-bg) 100%);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-primary) 15%, var(--bb-border-color));
  border-radius: var(--bb-radius-lg);
}

.bb-b2c-sponsored-top-brand-logo {
  width: 6rem;
  height: 3.5rem;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  margin-bottom: 0.875rem;
}

.bb-b2c-sponsored-top-brand-logo img {
  display: block;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}

.bb-b2c-sponsored-top-label {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  width: fit-content;
  min-height: 1.75rem;
  margin-bottom: 0.625rem;
  padding: 0 0.625rem;
  color: var(--bb-primary);
  background-color: color-mix(in srgb, var(--bb-primary) 10%, transparent);
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2c-sponsored-top-label .material-symbols-outlined {
  font-size: var(--bb-fs-sm);
  line-height: 1;
}

.bb-b2c-sponsored-top-title {
  margin: 0 0 0.4375rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-xl);
  font-weight: var(--bb-fw-semibold);
  line-height: var(--bb-line-height-heading);
}

.bb-b2c-sponsored-top-title a {
  color: inherit !important;
  text-decoration: none !important;
}

.bb-b2c-sponsored-top-title a:hover {
  color: var(--bb-primary) !important;
}

.bb-b2c-sponsored-top-text {
  margin: 0 0 0.875rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-base);
}

.bb-b2c-sponsored-top-about {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  width: fit-content;
  margin-top: auto;
  color: var(--bb-secondary-color) !important;
  text-decoration: none !important;
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2c-sponsored-top-about:hover {
  color: var(--bb-primary) !important;
}

.bb-b2c-sponsored-top-about .material-symbols-outlined {
  font-size: var(--bb-fs-sm);
  line-height: 1;
}

/* -------------------------------------
   Products
------------------------------------- */
.bb-b2c-sponsored-top-products {
  min-width: 0;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.875rem;
}

.bb-b2c-sponsored-top-product {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 15.625rem;
  overflow: hidden;
  background-color: var(--bb-body-bg);
  border: var(--bb-border-width) solid var(--bb-border-color);
  border-radius: var(--bb-radius-lg);
  box-shadow: var(--bb-shadow-xs);
  transition: border-color var(--bb-transition-fast), box-shadow var(--bb-transition-fast), transform var(--bb-transition-fast);
}

.bb-b2c-sponsored-top-product:hover {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--bb-primary) 24%, var(--bb-border-color));
  box-shadow: var(--bb-shadow-sm);
}

.bb-b2c-sponsored-top-product-media {
  position: relative;
  display: block;
  height: 7.625rem;
  overflow: hidden;
  padding: 0.75rem;
  background: linear-gradient(180deg, var(--bb-body-bg) 0%, var(--bb-tertiary-bg) 100%);
  border-bottom: var(--bb-border-width) solid var(--bb-border-color);
  text-decoration: none !important;
}

.bb-b2c-sponsored-top-product-media img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  border-radius: var(--bb-radius);
  transition: transform var(--bb-transition-normal);
}

.bb-b2c-sponsored-top-product:hover .bb-b2c-sponsored-top-product-media img {
  transform: scale(1.035);
}

.bb-b2c-sponsored-top-product-tag {
  position: absolute;
  left: 0.5rem;
  top: 0.5rem;
  z-index: 2;
  display: inline-flex;
  align-items: center;
  min-height: 1.375rem;
  padding: 0 0.5rem;
  color: var(--bb-secondary-color);
  background-color: color-mix(in srgb, var(--bb-surface-elevated) 92%, transparent);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 70%, transparent);
  border-radius: var(--bb-radius-pill);
  box-shadow: var(--bb-shadow-xs);
  font-size: var(--bb-fs-2xs);
  font-weight: var(--bb-fw-semibold);
}

/* -------------------------------------
   Product body
------------------------------------- */
.bb-b2c-sponsored-top-product-body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: 0.75rem;
}

.bb-b2c-sponsored-top-product-title {
  display: -webkit-box;
  min-height: 2.375rem;
  max-height: 2.375rem;
  overflow: hidden;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  color: var(--bb-emphasis-color) !important;
  text-decoration: none !important;
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
  line-height: var(--bb-line-height-base);
  transition: color var(--bb-transition-fast);
}

.bb-b2c-sponsored-top-product-title:hover {
  color: var(--bb-primary) !important;
}

.bb-b2c-sponsored-top-product-price {
  display: inline-flex;
  align-items: baseline;
  gap: 0.1875rem;
  margin-top: 0.5rem;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-icon-size-md);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-tight);
  letter-spacing: var(--bb-letter-spacing-tight, -0.02em);
}

.bb-b2c-sponsored-top-product-price span {
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-semibold);
}

.bb-b2c-sponsored-top-product-meta {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  margin-top: 0.375rem;
  margin-bottom: 0.625rem;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-xs);
  line-height: var(--bb-line-height-base);
}

.bb-b2c-sponsored-top-product-meta .material-symbols-outlined {
  color: var(--bb-warning);
  font-size: var(--bb-fs-sm);
  line-height: 1;
}

.bb-b2c-sponsored-top-product-action {
  width: 100%;
  min-height: 2rem;
  margin-top: auto;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-xs);
  font-weight: var(--bb-fw-bold);
}

/* -------------------------------------
   Responsive
------------------------------------- */
@media (max-width: 1399.98px) {
  .bb-b2c-sponsored-top-products {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .bb-b2c-sponsored-top-products .bb-b2c-sponsored-top-product:nth-child(n+5) {
    display: none;
  }
}
@media (max-width: 1199.98px) {
  .bb-b2c-sponsored-top-inner {
    grid-template-columns: 1fr;
  }
  .bb-b2c-sponsored-top-brand {
    min-height: auto;
  }
}
@media (max-width: 991.98px) {
  .bb-b2c-sponsored-top-products {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .bb-b2c-sponsored-top-products .bb-b2c-sponsored-top-product:nth-child(n+4) {
    display: none;
  }
}
@media (max-width: 767.98px) {
  .bb-b2c-sponsored-top {
    padding: 0.75rem;
    border-radius: var(--bb-radius-lg);
  }
  .bb-b2c-sponsored-top-brand {
    padding: 0.875rem;
  }
  .bb-b2c-sponsored-top-title {
    font-size: var(--bb-icon-size-md);
  }
  .bb-b2c-sponsored-top-products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
  }
  .bb-b2c-sponsored-top-products .bb-b2c-sponsored-top-product:nth-child(n+4),
