  font-weight: var(--bb-fw-semibold);
}

/* Form */
.bb-b2c-filter-form {
  display: flex;
  flex-direction: column;
}

.bb-b2c-filter-group {
  border-bottom: var(--bb-border-width) solid var(--bb-border-color);
}

.bb-b2c-filter-group:last-child {
  border-bottom: 0;
}

.bb-b2c-filter-group summary {
