/* -------------------------------------
   Bank head
------------------------------------- */
.bb-b2c-product-installment-card-head {
  display: grid;
  grid-template-columns: 3.875rem minmax(0, 1fr);
  gap: 0.8125rem;
  align-items: center;
  min-height: 4.625rem;
  padding: 0.875rem;
