}

.bb-b2c-product-installment-table tr.is-highlighted td:first-child::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.5625rem;
  bottom: 0.5625rem;
  width: 0.25rem;
  background-color: var(--bb-primary);
  border-radius: var(--bb-radius-pill);
}

.bb-b2c-product-installment-unavailable {
