===================================== */
.bb-b2c-homepage-slider {
  --bb-b2c-slider-carousel-bg:
    radial-gradient(circle at 86% 12%, color-mix(in srgb, var(--bb-primary) 22%, transparent), transparent 28%),
    radial-gradient(circle at 12% 88%, color-mix(in srgb, var(--bb-success) 12%, transparent), transparent 30%),
    linear-gradient(135deg, color-mix(in srgb, var(--bb-primary) 10%, var(--bb-surface-elevated)) 0%, color-mix(in srgb, var(--bb-primary) 6%, var(--bb-surface-elevated)) 46%, color-mix(in srgb, var(--bb-warning) 12%, var(--bb-surface-elevated)) 100%);
  --bb-b2c-slider-carousel-border: color-mix(in srgb, var(--bb-primary) 22%, var(--bb-border-color));
  --bb-b2c-slider-control-bg: color-mix(in srgb, var(--bb-surface-elevated) 72%, transparent);
  --bb-b2c-slider-control-border: color-mix(in srgb, var(--bb-surface-elevated) 76%, transparent);
  --bb-b2c-slider-control-shadow:
    0 0.75rem 1.75rem color-mix(in srgb, var(--bb-emphasis-color) 8%, transparent),
    inset 0 0 0 1px color-mix(in srgb, var(--bb-surface-elevated) 22%, transparent);
  --bb-b2c-slider-control-hover-bg: color-mix(in srgb, var(--bb-surface-elevated) 92%, transparent);
  --bb-b2c-slider-control-hover-border: color-mix(in srgb, var(--bb-primary) 32%, var(--bb-surface-elevated));
  --bb-b2c-slider-dot-bg: color-mix(in srgb, var(--bb-emphasis-color) 22%, transparent);
  position: relative;
}

.bb-b2c-homepage-slider-carousel {
  position: relative;
  overflow: hidden;
  min-height: 31.25rem;
  background: var(--bb-b2c-slider-carousel-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-slider-carousel-border);
  border-radius: var(--bb-radius-2xl);
  box-shadow: var(--bb-shadow-sm);
}

.bb-b2c-homepage-slider-carousel::before {
  content: "";
  position: absolute;
  right: -5rem;
  top: -5rem;
  z-index: 1;
  width: 17.5rem;
  height: 17.5rem;
  background-color: color-mix(in srgb, var(--bb-surface-elevated) 26%, transparent);
  border-radius: 50%;
}

.bb-b2c-homepage-slider-carousel::after {
  content: "";
  position: absolute;
  left: -4.375rem;
  bottom: -5.625rem;
  z-index: 1;
  width: 15rem;
  height: 15rem;
  background-color: color-mix(in srgb, var(--bb-surface-elevated) 20%, transparent);
  border-radius: 50%;
}

.bb-b2c-homepage-slider-inner {
  position: relative;
  z-index: 2;
  min-height: 31.25rem;
}

.bb-b2c-homepage-slider-item {
  min-height: 31.25rem;
}

.bb-b2c-homepage-slider-slide {
  min-height: 31.25rem;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(18rem, 0.88fr);
  gap: clamp(1.5rem, 4vw, 3rem);
  align-items: center;
  padding: clamp(1.75rem, 4vw, 3rem) clamp(4.5rem, 6vw, 5.5rem);
