/* Controls */
.bb-b2c-homepage-slider-control {
  top: 50%;
  z-index: 6;
  width: 3.125rem;
  height: 3.125rem;
  align-items: center;
  justify-content: center;
  color: var(--bb-emphasis-color);
  background-color: var(--bb-b2c-slider-control-bg);
  border: var(--bb-border-width) solid var(--bb-b2c-slider-control-border);
  border-radius: var(--bb-radius-pill);
  box-shadow: var(--bb-b2c-slider-control-shadow);
  opacity: 0.86;
  transform: translateY(-50%);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  transition: opacity var(--bb-transition-fast), background-color var(--bb-transition-fast), transform var(--bb-transition-fast), box-shadow var(--bb-transition-fast), border-color var(--bb-transition-fast);
}

.bb-b2c-homepage-slider-control:hover {
  color: var(--bb-emphasis-color);
  background-color: var(--bb-b2c-slider-control-hover-bg);
