  --bb-b2c-slider-control-hover-border: color-mix(in srgb, var(--bb-primary) 28%, var(--bb-border-color));
  --bb-b2c-slider-dot-bg: color-mix(in srgb, var(--bb-white) 28%, transparent);
}

/* Responsive */
@media (max-width: 991.98px) {
