/*
=====================================
   B2C From Brands
   Component-specific
   Uses Main CSS: bb-chip, bb-carousel
=====================================
*/
.bb-b2c-from-brand {
  --bb-from-brand-bg-image: none;
  --bb-from-brand-surface-bg: color-mix(in srgb, var(--bb-body-bg) 42%, transparent);
  --bb-from-brand-card-bg: var(--bb-surface-elevated);
  --bb-from-brand-caption-bg: color-mix(in srgb, var(--bb-surface-elevated) 88%, transparent);
  --bb-from-brand-overlay-start: color-mix(in srgb, var(--bb-body-bg) 92%, transparent);
  --bb-from-brand-overlay-end: color-mix(in srgb, var(--bb-body-bg) 74%, transparent);
  --bb-from-brand-surface-background:
    radial-gradient(circle at 92% 6%, color-mix(in srgb, var(--bb-primary) 18%, transparent), transparent 32%),
    radial-gradient(circle at 8% 96%, color-mix(in srgb, var(--bb-info) 8%, transparent), transparent 34%),
    var(--bb-from-brand-surface-bg);
  --bb-from-brand-floating-border: color-mix(in srgb, var(--bb-white) 64%, transparent);
  position: relative;
  margin: 1.625rem 0;
  overflow: hidden;
  background-image: linear-gradient(90deg, var(--bb-from-brand-overlay-start), var(--bb-from-brand-overlay-end)), var(--bb-from-brand-bg-image);
  background-repeat: no-repeat;
  background-position: center;
  background-size: cover;
  border-radius: var(--bb-radius-xl);
}

.bb-b2c-from-brand-surface {
  position: relative;
  z-index: 1;
  padding: clamp(1.375rem, 3vw, 2.25rem);
  background: var(--bb-from-brand-surface-background);
  backdrop-filter: blur(5px);
  -webkit-backdrop-filter: blur(5px);
}

/* Head */
.bb-b2c-from-brand-head {
  position: relative;
  z-index: 3;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
}

.bb-b2c-from-brand-head-content {
  min-width: 0;
}

.bb-b2c-from-brand-chip {
  color: color-mix(in srgb, var(--bb-primary) 78%, var(--bb-emphasis-color));
  background-color: color-mix(in srgb, var(--bb-primary) 16%, var(--bb-body-bg));
}

.bb-b2c-from-brand-title {
  margin: 0.625rem 0 0;
  color: var(--bb-emphasis-color);
  font-size: clamp(1.375rem, 3vw, 1.875rem);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: -0.025em;
}

.bb-b2c-from-brand-text {
  max-width: 42rem;
  margin: 0.5rem 0 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  line-height: var(--bb-line-height-content);
}

.bb-b2c-from-brand-count {
  background-color: color-mix(in srgb, var(--bb-surface-elevated) 70%, transparent);
  border-color: var(--bb-from-brand-floating-border);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}

/* Carousel */
.bb-b2c-from-brand-carousel {
  --bb-carousel-control-size: 2.75rem;
  --bb-carousel-control-inset: 0.75rem;
  --bb-carousel-control-bg-color: var(--bb-emphasis-color);
  --bb-carousel-control-bg-opacity: 0.24;
  --bb-carousel-control-bg-opacity-hover: 0.46;
  position: relative;
  z-index: 2;
}

.bb-b2c-from-brand-carousel .carousel-inner {
  overflow: hidden;
  border-radius: var(--bb-radius-lg);
}

.bb-b2c-from-brand-carousel .carousel-item {
  min-height: 28.3125rem;
}

.bb-b2c-from-brand-carousel .carousel-indicators {
  padding-top: 1rem;
}

.bb-b2c-from-brand-carousel .carousel-control-prev,
.bb-b2c-from-brand-carousel .carousel-control-next {
  z-index: 5;
}

.bb-b2c-from-brand-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.875rem;
}

/* Card */
.bb-b2c-from-brand-card {
  position: relative;
  display: block;
  min-width: 0;
  height: 28.3125rem;
  min-height: 28.3125rem;
  overflow: hidden;
  color: inherit;
  text-decoration: none;
  background-color: var(--bb-from-brand-card-bg);
  border: var(--bb-border-width) solid color-mix(in srgb, var(--bb-border-color) 82%, transparent);
  border-radius: var(--bb-radius-lg);
  box-shadow: var(--bb-shadow-xs);
}

.bb-b2c-from-brand-card:hover {
  color: inherit;
  text-decoration: none;
}

.bb-b2c-from-brand-media {
  width: 100%;
  height: 100%;
  overflow: hidden;
}

.bb-b2c-from-brand-media img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transition: transform var(--bb-transition-normal);
}

.bb-b2c-from-brand-card:hover .bb-b2c-from-brand-media img {
  transform: scale(1.035);
}

/* Caption */
.bb-b2c-from-brand-caption {
  position: absolute;
  left: 0.875rem;
  right: 0.875rem;
  bottom: 0.875rem;
  z-index: 2;
  padding: 0.875rem 0.9375rem;
  color: var(--bb-emphasis-color);
  background-color: var(--bb-from-brand-caption-bg);
  border: var(--bb-border-width) solid var(--bb-from-brand-floating-border);
  border-radius: var(--bb-radius);
  box-shadow: var(--bb-shadow-xs);
  text-align: center;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}

.bb-b2c-from-brand-caption h3 {
  margin: 0;
  color: var(--bb-emphasis-color);
  font-size: var(--bb-fs-md);
  font-weight: var(--bb-fw-bold);
  line-height: var(--bb-line-height-heading);
  letter-spacing: var(--bb-letter-spacing-tight, -0.015em);
}

.bb-b2c-from-brand-caption p {
  display: -webkit-box;
  overflow: hidden;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  margin: 0.375rem 0 0;
  color: var(--bb-secondary-color);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-medium);
  line-height: var(--bb-line-height-base);
}

/* Dark tokens */
[data-bs-theme=dark] .bb-b2c-from-brand {
  --bb-from-brand-surface-bg: color-mix(in srgb, var(--bb-body-bg) 34%, transparent);
  --bb-from-brand-card-bg: color-mix(in srgb, var(--bb-surface-elevated) 96%, var(--bb-body-bg));
  --bb-from-brand-caption-bg: color-mix(in srgb, var(--bb-surface-elevated) 78%, transparent);
  --bb-from-brand-overlay-start: color-mix(in srgb, var(--bb-body-bg) 90%, transparent);
  --bb-from-brand-overlay-end: color-mix(in srgb, var(--bb-body-bg) 68%, transparent);
  --bb-from-brand-surface-background:
    radial-gradient(circle at 92% 6%, color-mix(in srgb, var(--bb-primary) 13%, transparent), transparent 32%),
    radial-gradient(circle at 8% 96%, color-mix(in srgb, var(--bb-info) 8%, transparent), transparent 34%),
    var(--bb-from-brand-surface-bg);
  --bb-from-brand-floating-border: color-mix(in srgb, var(--bb-border-color) 78%, transparent);
}

/* Responsive */
@media (max-width: 991.98px) {
  .bb-b2c-from-brand-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .bb-b2c-from-brand-carousel .carousel-item,
