}

.bb-account-order-detail-back-btn {
  min-height: 2.375rem;
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  border-radius: var(--bb-radius-pill);
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-bold);
  white-space: nowrap;
}

.bb-account-order-detail-back-btn .material-symbols-outlined {
  font-size: var(--bb-fs-base);
