.bb-account-order-detail-cargo-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.bb-account-order-detail-cargo-item {
  display: grid;
  gap: 0.25rem;
}

.bb-account-order-detail-cargo-item span {
  color: var(--bb-secondary-color);
