}

.bb-posb-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.875rem;
  margin: 2rem 0 0;
}

.bb-posb-actions .btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

.bb-posb-hero-foot {
  margin-top: 2rem;
}

.bb-posb-ecosystem-link {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--bb-secondary-color);
  font-weight: var(--bb-fw-semibold);
