  padding: 1.5rem;
}

.bb-posb-terminal {
  overflow: hidden;
  min-height: 26rem;
  border: 1px solid color-mix(in srgb, var(--bb-color-white) 16%, transparent);
  border-radius: var(--bb-radius-2xl);
