  background: var(--bb-color-navy-900);
  box-shadow: var(--bb-shadow-lg);
  transform: rotate(-2deg);
}

.bb-posb-terminal-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.125rem 1.5rem;
  border-bottom: 1px solid color-mix(in srgb, var(--bb-color-white) 12%, transparent);
}

.bb-posb-terminal-logo {
  display: inline-flex;
  align-items: center;
  gap: 0.625rem;
  font-size: var(--bb-fs-lg);
  font-weight: var(--bb-fw-extrabold);
}

.bb-posb-terminal-logo .material-symbols-outlined {
  color: var(--bb-color-yellow-500);
}

.bb-posb-terminal-status {
  display: flex;
  gap: 0.375rem;
}

.bb-posb-terminal-status span {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 100%;
  background: color-mix(in srgb, var(--bb-color-white) 32%, transparent);
}

.bb-posb-terminal-body {
  display: grid;
  grid-template-columns: 3.5rem 1fr;
  min-height: 24rem;
}

.bb-posb-terminal-sidebar {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1.5rem;
  padding: 1.75rem 0.5rem;
  border-right: 1px solid color-mix(in srgb, var(--bb-color-white) 12%, transparent);
}

.bb-posb-terminal-sidebar .material-symbols-outlined {
  color: color-mix(in srgb, var(--bb-color-white) 55%, transparent);
}

.bb-posb-terminal-sidebar .material-symbols-outlined:first-child {
  color: var(--bb-color-yellow-500);
}

.bb-posb-terminal-content {
  padding: clamp(1.125rem, 2.5vw, 2rem);
}

.bb-posb-terminal-overline {
  width: 30%;
  height: 0.5rem;
  margin-bottom: 1rem;
