  padding: 1.125rem;
  border: 1px solid color-mix(in srgb, var(--bb-color-white) 13%, transparent);
  border-radius: var(--bb-radius-xl);
  background: color-mix(in srgb, var(--bb-color-white) 6%, transparent);
}

.bb-posb-terminal-metric .material-symbols-outlined {
  color: var(--bb-color-yellow-500);
}

.bb-posb-terminal-metric strong {
  font-size: var(--bb-fs-sm);
  font-weight: var(--bb-fw-semibold);
}

.bb-posb-terminal-metric i {
  height: 0.4rem;
  width: 80%;
  border-radius: var(--bb-radius-pill);
  background: color-mix(in srgb, var(--bb-color-white) 24%, transparent);
}

.bb-posb-terminal-metric i:last-child {
