  background: color-mix(in srgb, var(--bb-color-white) 22%, transparent);
}

.bb-posb-terminal-bottom {
  display: flex;
  justify-content: flex-end;
  gap: 0.625rem;
  margin-top: 1rem;
}

.bb-posb-terminal-bottom span {
  width: 4rem;
  height: 1.625rem;
